/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210419-5","meetingId":"r03-cm04","date":"2021年4月19日","dateIso":"2021-04-19","committee":"総務委員会","time":"午後 １時００分～午後 ３時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"令和３年度 組織改正","agenda":"令和３年度 組織改正","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"先ほどの説明ですと、区職員の育成に係る総合的な調整とその推進ということですけれども、もう少し詳しくご説明いただけたらと思います。どういう背景で、どういうことを進めていきたいのか、ご説明くださいとの意見を述べました。","respondent":"佐藤（憲）企画調整課長","answer":"人材育成担当課長の具体的な業務というところだと思います。広い視野と新しい発想で仕事に取り組む人材というのが非常に必要なところで、土木、そういった業務を担うというふうに考えております。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"給付事務から解放されるというか、障害者福祉というものに、例えば相談とかそういうことに専念できるというふうに考えてよろしいのか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"障害者福祉課の組織改正に関するご質問です。障害者給付事務係に係長を新しく１人置いて、給付そういったものの相談について特化して対応する組織を、新しく立ち上げたところです。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"ただ、これは組織体制の話であって、人数というか、給付事務は結構大変なわけです。いろいろ当事者の方からも意見があったのですが、係を分けたことは大変評価したいと思うのですけれど、そのことはいかがか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"障害者福祉係は、昨年度まで担っていた職員の数をそのまま障害者給付事務係に充てて、さらに事務を統括する係長を配置したです。説明が足りませんでした。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"今後の推移を見て、また新たな組織改正が必要だったら、ぜひ検討してほしいと求めました。これは意見でとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"品川区指定管理者制度活用に係る基本方針の改定","agenda":"品川区指定管理者制度活用に係る基本方針の改定","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"指定管理者の選定の公募・選定ですけれども、連続して１０年を限度とするということですが、そう定めた理由を伺いたいと思います。その考えをどう変えたのか、なぜ変えたのか、併せてお伺いしたいと思います。","respondent":"佐藤（憲）企画調整課長","answer":"公募によらない選定を連続１０年までとした理由です。今回双方のバランスをとって連続１０年までということで、連続して１５年を限度というところで、方針を改定したところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"特養など福祉施設も、１０年ないし１５年で公募をかけるということは、事業者変更も制度上、可能だということを選択肢としてつくるわけです。これはやめるべきだと思うのですが、いかがか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"それを選定委員会で選定して、よりよい区民サービスを提供するというのが、制度の一つの原則です。委員ご紹介のとおり継続性というところもありますので、実態としては１５年という制度で運用していくということを、区のほうで判断したところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"総合得点のみではなく、それぞれのカテゴリーごとの点数も、議会に対して公表すべきだと思いますが、いかがでしょうか。最後に、いずれにしても公表すべき中身は品川区のホームページにしっかり掲載すべきだと思いますが、それぞれいかがか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"１点目の、公平性に関しましてもきちんとご説明をしてご議論いただき、議会のほうにも資料として提示いたします。最後のホームページに載せるかということは、区ホームページに載せていきます。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に選定委員の名簿を、氏名も含めて議会への資料に載せるということでよいのか、確認させてください。ぜひカテゴリーごとの得点も示すべきだと改めて求めたいと思いますが、いかがか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"１点目のご質問の選定委員の名簿に関しましては、氏名も含めて公表、議会のほうにもお出しするということを予定しています。近隣自治体とか、公表している自治体の状況も確認しながら、今回は総合得点のみということで改定を行うところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"透明性、公平性、客観性の向上とおっしゃるのであれば、十分な情報公開を引き続き求めてまいりたいと思います。福祉施設については事業の継続性、利用者との関係性も重視すべきだと思うので、現事業者を継続するよう強く求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"３の指定管理者の選定の(4)指定管理者候補者選定予備委員会のところで、なぜ、伺いたいです。情報公開を求める人はどういう手続きを、どういうふうにするのか分からないかなと思ったので、その辺についても確認させてください。","respondent":"佐藤（憲）企画調整課長","answer":"今回定める基本方針に関しましては大きな枠組みというところで、これを柱として各所管で、サービスの内容に応じて募集要項等を定めていくです。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"内部委員という言い方がいいのでしょうか、やはりざっくりでいいから半数以上とか、何かそういうことはぜひ考えていただきたいと。そこだけ確認させてください。","respondent":"佐藤（憲）企画調整課長","answer":"情報公開に関しましては、委員がまとめていただいたとおりです。これからも区として適切に、事業者のほうに働きかけていくです。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"今後どういうことが起きて、これは区の施設ではないのですかということで、そういうことも起きかねないと思います。そういうことがないように、支援もするし、常に見守っていますという仕組みや担保というのはあるのか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"今回、その辺に関しましても、基本方針に明確に記載したところです。収支の状況は必ず毎年チェックしておりますので、今後も継続的な、よりよい区民サービスにつながるよう、評価していきたいと考えております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"その事業者が安定的に区民サービスを行えるような、そういう制度、システムもあるのでしょうか。説明を求めました。","respondent":"佐藤（憲）企画調整課長","answer":"それに加えまして、第三者的な視点の評価を行ってきたところです。その辺はまた新型コロナウイルス感染症の影響もありますから、厳しく中身のほうを確認してまいりたいと考えております。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"「学識経験者・弁護士等」と書いてあるのですけれど、「等」の中にどういう方が含まれているのか教えていただきたい。これを明記した理由をお聞かせほしいと求めました。","respondent":"佐藤（憲）企画調整課長","answer":"２点目の緊急時の対応をなぜ明記したかですが、施設の継続的な維持管理、今後も困難な面が予想されます。これまで年度協定とかでも記載していたところですが、特出しして区の方針として明記し、きちんと対応していくということから記載しています。","id":"exchange-014"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それから２ページで、指定管理者は品川区とのコミュニケーションを密にとることも大変重要だと考えています。具体的に行っていること、もしくは行おうとしていくことなどがあれば、教えてほしいと求めました。","respondent":"佐藤（憲）企画調整課長","answer":"年度末に関しましては当然、決算見込みというところで見ますので、適宜、適切に事業者とコミュニケーションを図っているところです。今後も、委員ご指摘の趣旨を踏まえて、きちんと適切に対応していきたいと思います。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問・要望","question":"総合点数について少し確認させていただきたいのですが、各施設の方には、伝わっているのでしょうか。総合点数ではなくて細かい点数です。","respondent":"佐藤（憲）企画調整課長","answer":"個別の採点に関しましては、情報公開の請求等が出た場合はその都度判断して、公開できるときはしています。ご本人様からの情報公開の請求があればという取扱いになっているところです。","id":"exchange-016"},{"speaker":"松澤委員","kind":"意見","question":"そういうものがしっかり施設の方に伝わると、施設のレベル自体も底上げされてどんどん上がっていくのかなと考えております。いずれそういった部分で区と施設がうまく、施設のレベル自体が上がるような取組ができればと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そうではなくてその期間内に組織再編行為があったら、そういう期間内で行われるのか、その点の確認が１点です。最終的に品川区が十分確保されているというふうに判断するのか、そこら辺を確認させてほしいと求めました。","respondent":"佐藤（憲）企画調整課長","answer":"８の組織再編ですが、実際に再編が起きたときというふうに考えております。区としてその引継ぎ期間で十分にサービスの継続性が図れるかというのは、その辺は調整して決定したいと考えているところです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"区の公募をかけるかどうかの判断の時期によって、何か結果が見えてしまうような、そのような仕組みになってしまっているのではないかと思うのです。あらかじめ事業所の変更を可能にしてしまう、そういう仕組みに見えてならないのですけれども、その点はいかがか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"その施設がどのぐらい継続的に行われているのか、様々な面から、所管のほうで事業者等と相談して決めることだと考えております。こちらに書いてあるとおり、適切に区民の方によりよいサービスを継続的に行う趣旨で、改定しているものです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"日頃からどういう事業をやっているのかというのを区が十分に把握すること、事業の中身を見るというのが、監視のようなチェックであってはいけないと。先ほどの説明だと何か、品川区が上に立つ者みたいなイメージを持ってしまうのですけれども、その点だけご説明ほしいと求めました。","respondent":"佐藤（憲）企画調整課長","answer":"指定管理者の提案する事業を選定しながら、何が目的かというと、区民の方によりよいサービスを継続的に提供するです。指定管理者のモニタリング、第三者の目、いろいろな手法を使いながら透明性、公平性を確保しながら、事業を進めていきたいと考えております。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"皆さんの質疑を伺っていて、私も実は同じように思っています。これについては、もし何かそういう問題意識について見解があれば伺いたいと思いますが、いかがか尋ねました。","respondent":"佐藤（憲）企画調整課長","answer":"今、業務委託との比較の議論になっているのかなというところもあります。公表内容の充実を図るなどして、分かりやすい形で区が適切に行っていくというところも明確に示していきたいと考えております。","id":"exchange-021"},{"speaker":"吉田委員","kind":"意見","question":"今、申し上げました件については、それぞれのモニタリングの際とか、一つ一つ私たちとしてもきちんとチェックしていきたいと思います。これは意見だけで結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-03","title":"議題順を入れ替えまして、先に、(7)新庁舎整備に関する検討状況","agenda":"議題順を入れ替えまして、先に、(7)新庁舎整備に関する検討状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"質問は、１テーマ何回行うのか、伺いたいと思います。ぜひそういう説明会を開いていただいて、幅広く区民の意見を集めてほしいと求めましたが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"今後何回やるか、どういった形でやるかというのは、状況等を鑑みながら検討を深めていきたいと考えています。説明会という形ではなくワークショップは、説明に伺うといった形で、やっていきたいと考えているところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういうふうにやっていくのか決まっていないということなのか、どのテーマをどこで、そのスケジュールを伺いたいと思います。地域で求めがあればやるということですけれども、コロナ禍ですから感染症対策は当然前提ですけれども、ご説明ほしいと求めました。","respondent":"濱中庁舎計画担当課長","answer":"今後検討していきまして、また今回検討支援に入る業者とも打ち合わせしながら、お示しできるのは少し先の話になるかと考えています。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域で求めがあればやるとおっしゃっていた説明会ですけれども、そういう場合でもやるということなのか、ご説明ほしいと求めました。後日にまた文書で意見をもらったり、丁寧にやっていく必要があると思いますけれども、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"庁舎機能のまとめに関しましては、説明を丁寧に行いたいと思いますが、あらゆる会合に出席するというのは難しいかと考えています。テーマごとにご案内をしながら、やっていくような形、全てに対してそういった説明に伺うというようなことは難しいものかなと考えております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど地域で求めがあればやるとおっしゃったのですけれども、いるのか、そこをはっきりしてほしいと求めました。結局、やると言っても、いつもと同じではないかと思ってしまったのですけれども、いかがか尋ねました。","respondent":"榎本総務部長","answer":"庁舎機能検討委員会の答申がまとまりましたので、まずはそれをどういうふうに説明していくかという段階でありまして、説明してきておりますので。まん延防止措置というような状況もありますので、その辺の状況も十分加味した上で、検討を進めていきたいと考えています。","id":"exchange-026"},{"speaker":"吉田委員","kind":"確認","question":"確認なのですけれども、これは第４回が書面開催になったので、議論にかわって出された意見という解釈でよろしいのでしょうか。この第４回の意見の扱いについては具体的にどう生かされたのか、伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"そちらの意見のまとめと質問のようなものがございましたが、事務局の回答といいますか、調査結果としましてお示ししています。第４回のテーマであります「共通機能」と「長く使われる庁舎」におきまして、答申案を作らせていただいたところです。","id":"exchange-027"},{"speaker":"吉田委員","kind":"確認","question":"この２点も修正点として出ていたと思うのですけれども、答申には反映されなかったけれども、この後の資料とかに生かされることなのでしょうか。出してそれで終わりということはないと思うのですが、どう生かされているのか、もう一度確認させてください。","respondent":"濱中庁舎計画担当課長","answer":"「将来の変化に対応し、第４回にご意見をいただきまして、そちらを付け加えさせていただいています。第５回におきましては、その他の検討事項という項目が答申案にはございまして、そちらに明記させていただいたところです。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"その点について、ご見解を伺いたいです。その案の中に、そういうことを踏まえた案にしてほしいというようなことがあるべきだと思うのですけれど、その点についてはいかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"検討委員会の議論の仕方ということで、第４回は書面開催になったのですが、たくさんの意見が出せるのではないかです。ベースのものができたと考えておりますので、こちらを活用して基本構想、基本計画の策定を進めていきたいと考えています。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"７月末までに、これはどういうことなのだろうかという問題意識で、質問をしたのです。これは強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"求められる庁舎機能、あるべき姿を、私は推察します。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-04","title":"冊子「人権を考える」","agenda":"冊子「人権を考える」","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"多言語化対応の取組をさらに進めていただきたいと思うのですけれども、その点伺いたいと思います。多くの国籍や地域の方々が見られる環境を整えていくということは、引き続き大事だと思うのですけれども、その点だけお伺いしたいです。","respondent":"島袋人権啓発課長","answer":"宣言文も、内容等々も、多言語化するのはとても困難な状況かと思いますので、まずは宣言全体の文章を、英語化、中国語化、韓国語化いたしました。ご要望があるようでしたら工夫をしてまいりまして、検討していきたいと考えるところです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"この報告書の使い方といいますか、その辺についてどのようにお考えか、それから７,０００部という数はどういうところから出てきたのかを説明を求めました。","respondent":"島袋人権啓発課長","answer":"このような中から、５年間でどのぐらいの部数が必要かということも検討しまして、今回は７,０００部とさせていただいたところです。必要に応じて配布しておりますし、１２月に行います人権啓発課の大きなイベント、「人権のひろば」のときに配布しています。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。今、内容からいってもこういうことを考えるような年齢というのがあるのかなとも思うのですが、その辺についていかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"人権尊重都市品川宣言も、小学校５年生のときに学ぶということがあります。副読本として差し上げてもあります。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"対応していることがわかる表示を求めたのですけれど、ほとんどがやはりこの３言語、とりあえずこの３言語というのは妥当かなと思います。その辺についての対応は今後、この３言語でよしとせず、考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"湯澤委員","kind":"質問","question":"実際にどういった問題が起きているのかとか、この冊子を手に取った人が、より差別をなくそうと思っていくのではないかと思うのが一つです。例えば私が見て、どの世代がどういった人権問題に対して関心を持っているのかというのが分かると思うのですけれども、その辺はいかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"こちらの冊子も経年的に見ておりますので、前回もこのように取り組んでいる部分がございましたので、同じように掲載しています。年代別に考え方が違ってくるというところは非常に、実際に１２ページの左下ですが、少しずつトピック的に新たな記載をさせていただいてあります。","id":"exchange-036"},{"speaker":"湯澤委員","kind":"意見","question":"「ある」と書いてある３.８％と、「無回答」の２.６％、これは明らかに誰が見ても、「ある」のところがかなり広いなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"確かにこれをまとめられているのはいいと思うのですが、そういうことを載せなくていいのでしょうか。それとも載せては駄目なのか尋ねました。","respondent":"島袋人権啓発課長","answer":"委員のお話ですが、国レベルの問題となりますと、やはり難しい問題が生じる可能性もあります。これをもってまた一つ、人権啓発課としましても啓発を進めてまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"須貝委員","kind":"意見","question":"どうだというのでなく、こういう状況が世界にはありますということぐらい、区としても取り上げていますと。今、課長と議論するという話ではないですけれど、一応意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"松澤委員","kind":"質問","question":"ホームページで周知するという形ですか、さきほど、小学校５年生でこういうことを学んでいるという話をお聞きしました。そういった教育でもこういう冊子を使って学習させているのか、説明を求めました。","respondent":"島袋人権啓発課長","answer":"教育のほうになりますと、教育総合支援センターが独自のカリキュラムを作りますので、どの場所で、どのものをというところまでは。見て知る、そこから深めていっていただくというところを、しっかりと啓発してまいりたいと考えているところです。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問","question":"教育委員会とは別かもしれませんが、そこはもっと踏み込んで勉強させてあげる機会をつくってほしいという思いがあります。いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"もう一つ、人権啓発課にあります男女共同参画センターに講座等ありますので、様々な時代に合わせた講座等も考えていく予定です。少しずつ今進めているところなので、状況に応じまして検討してまいりたいと考えているところです。","id":"exchange-041"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ親子でこういうことを学ぶ機会をつくっていただいて、家庭内でも人権に対する考えが広がっていくように要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"新妻副委員長","kind":"確認","question":"今日は冊子の報告ですので、中の細かいところまでお伺いするのもどうかと思いますが、やはり指摘しないといけないと思いました。今回は２２.１％ということで、この２７年間の中で何回か調査されていると思うのですけれど、確認させてください。","respondent":"島袋人権啓発課長","answer":"平成２０年のときは２７.６％、平成２６年は２６.９％、そして今回の令和元年度の調査は２２.１％という数字です。やはり様々な手段を使いまして、知っていただくように努力してまいりたいと考えているところです。","id":"exchange-043"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"中学生は、中学は小学校を卒業すれば中学でも当然知っているわけですから、そのぐらい徹底して教えていくことも必要なのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど品川区の窓口は３言語でほとんど対応できるということだったのですが、そのほかにどこか欄外でいいので、何かそういう対応があればいいかなと。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-05","title":"補助１６３号線（東急大井町線ガード下区間）電線共同溝等整備工事請負契約","agenda":"補助１６３号線（東急大井町線ガード下区間）電線共同溝等整備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"補助１６３号線については、周辺の新たな再開発を進めるためのインフラ工事としては、実施すべきではないと考えています。東急大井町線ガード下区間ということでありまして、現在のガード下は歩道も車道も狭いですから、事故なく安全に工事を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"品川区東五反田一丁目、三丁目付近再構築その２工事請負契約","agenda":"品川区東五反田一丁目、三丁目付近再構築その２工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"とても単純な質問なのですけれども、そもそもこの五反田の辺りは水が出やすいという言い方をしていいのでしょうか、どれぐらいを想定しての工事なのか教えてほしいと求めました。","respondent":"東野経理課長","answer":"東五反田付近につきましては目黒川流域ということで、都の下水道局と連携をしながら、区のほうで整備を進めてきている状況です。詳細につきましては、本日、建設委員会のほうでも報告をしているということで、そちらで確認されているものと思われます。","id":"exchange-047"},{"speaker":"須貝委員","kind":"質問","question":"課長のご見解として、今、品川区内の業者の仕事内容、実態、ボリュームなどもそうですが、今、どのように感覚的には思われていますか。説明を求めました。","respondent":"東野経理課長","answer":"配置予定技術者につきましては、辞退理由というふうにお書きになっているのだと思われます。そういうところを考えますと、具体的には、品川区の案件に手を挙げていただいているというところまでしか把握できてございません。","id":"exchange-048"}]},{"id":"topic-07","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"会計管理者のほうではそういう報告だけでここに載せているのですか。それとも全体として今、福祉部のほうから、だんだん厳しくなってきていますというような報告も上がっているのか尋ねました。","respondent":"中山会計管理者","answer":"ただ、令和元年度なのですけれど、収納額としましても、弁償金では９,０００万円ぐらいの歳入もしっかりあるところです。ただその返し方については、十分に相談をしながら、分割というようなことも生活福祉課のほうでは対応しています。","id":"exchange-049"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"営業時間の制限をしても、昼間飲んだら結局飛沫感染になってしまうのですから、何か対応がおかしいと僕は思います。質問ではないのですけれど、それだけ言いたいと思いまして、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて夏の東京２０２０大会の開催については、国に対して中止を求めていただきたいと。ただ、その後どのように対応していくかは、ぜひアスリートファーストの精神で議論していただきたいと、要望だけしておきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2194#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":37689,"voices":148}},{"id":"r03-20210420-14","meetingId":"r03-cm04","date":"2021年4月20日","dateIso":"2021-04-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時２４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"（４）、もう少し日常的なやり取りができればいいというような話だったと思うのですが、とにかくこの文言ではすごく分かりにくいという感じです。（６）が、どう修正すればいいか私もよく分からないのですけれども、何か修正していただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そうしたら、執行機関と、これは議会ではなくて、議員というふうに変えたらどうかと思いました。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"予算や決算だったりとか、議会が開かれているというイメージがしたと思うのです。議員個人という、それぞれの議員がというところで、議員としたほうが分かりやすいかと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その中で結局は黒田人事課長が言われているのは、新規採用の時点から区民のための区の職員の仕事はどうあるべきかについて。多分、そのようなことの中身が（６）なのかと思うのですが、どんな組織風土をどう改善していくのかというのが示されていないので……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"大沢委員","kind":"意見","question":"組織風土の改善という点がありますよ、そこにおいて組織風土の中で意識改革に取り組むというような捉え方を私はしているのですけれども、違いますか。どうでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あくつ委員長","kind":"確認","question":"今、昨年８月２０日の議事録を確認しました。〔「効率化しようというのがない組織になっているという……」」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"私の言った「おいて」という部分には、この場において意識改革が必要なのではないのですかということです。それに対して向き合う、意識を変えた、幾らかずつか変えたほうがいいのではないのでしょうかというような形を……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"ＩＣＴについて」の（２）、「この取組みに当たっては、いかがでしょうか。例えば、ネット申請だけで困った区民の方のお声を何度か聞いているので、そういう一文を盛り込んでおいたらいいのではないかと思った次第です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その意見のまとめを基にして、行財政改革特別委員会として提出するまとめをどのような形にするかという、今回初めて出されたものですよね。今回、そのまとめに対していろいろと意見を言うことは、今日言ってもいいことではないかと思うのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私も（２）の「書かない窓口に向けた取組みを推進」というのは、結局、オンライン化をどんどん進めるという意味ですよね。そういうオンラインでの申請だったりとかというのをどんどん進めるという、そのような趣旨でこれはまとめられたということではないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区民が行政の窓口に行ったら相談にも応じてくれて、そして、対応も丁寧にやってくれるという意味での書かない窓口ということで捉えていいのか尋ねました。","respondent":"あくつ委員長","answer":"その話を繰り返すと長くなってしまうので、また一から説明するということになってしまいますから、でも、大筋ではそういう意味です。オンラインというのは別です。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/444693?Template=document&Id=6106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":7730,"voices":44}},{"id":"r03-20210421-18","meetingId":"r03-cm04","date":"2021年4月21日","dateIso":"2021-04-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時２１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"東京2020オリンピック・パラリンピック聖火リレー","agenda":"東京2020オリンピック・パラリンピック聖火リレー","exchanges":[{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれど、オリンピック聖火リレーについてですが、どなたが走られるかというのは、先ほど未定とおっしゃったのですけれど、未定ですか。それは決まったらいつ発表されるのかとか、何かあれば。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、一般的に公表は、まだされていないです。今のところは私どもも、どなたが走るかとか、どこを走るかということは分かっていない状態です。","id":"exchange-001"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、７月２１日に、しな助のボランティアを募集されているのでしょうか。その応募状況ですとか、そのようなことをちょっと教えていただきたいのですが、お願いいたします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"職員も連絡調整役として必要ですので、一定程度は職員も従事するということで、ほぼ予定どおりに協力していただいているかなと考えています。","id":"exchange-002"},{"speaker":"こんの委員","kind":"質問","question":"セレブレーションについて少し伺いたいと思います。どんなイメージで、この沿道の密集を避ける態勢をとっていらっしゃるのか、少しイメージをお知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"もう既に、その聖火リレーのルート上に、この辺りに１人とか、今、マップ上には想定では一応落として検証しているところです。例えばそこを５０ｍ置きに人が要るとか、初期の段階での設定ということで、これからまた改定を重ねるというように聞いております。","id":"exchange-003"},{"speaker":"こんの委員","kind":"質問","question":"そこの直接予約の窓口というのは区で、ということなのでしょうか。システムはつくって、区がその予約を受け付ける窓口になる、こういう理解でよろしいですかというのが一つ。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ご自宅でライブ配信をお楽しみくださいというようなことを打ち出したほうがいいのかなと、今、内部では話しております。そこを守れるような態勢というのを、これから７月までいろいろ、他所の状況も見ながら考えていきたいと考えています。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"交通規制について伺います。いつの時間帯が通れなくなるとか、そういったことなどの情報はとても必要だと思うので、そういった周知についてお知らせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"決まり次第、チラシをつくりまして、沿道およびその近隣の地域の方にはポスティングをする予定です。こういうところを気をつけたほうがいいよとか、ここにも声をかけておいたほうがいいよというようなアドバイスもいただきながら進めしています。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"ただ、なるべく早めの周知がいいかなということを思います。バスであったり配達の車など、そういった方たちへの周知というのがどのようにされているのかも併せて伺いたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば東京バス協会ですとか、鉄道の団体ですとか、そういった大きなところには東京都がお知らせすることになっております。は事前にも、この日のこの時間は通れません、みたいな立て看板は東京都が立てるということは聞いております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"日本の世論調査、共同通信調査でも、７２％が中止・再延期を求めるというような状況だと思います。ちょっと伺いたいのは、国に求めることこそ、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今の私たちが課せられたものというのは、開催することを前提に、安全に安心してどうやって楽しんでできるかということを構築していくことです。今現在、その開催の可否について私どもが意見するという立場にはございませんので、それをするつもりはございません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう１００日を切りましたから、一刻も早く一日も早い決断が私は必要だと思いますので、ぜひお考えをちょっと改めてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"集団回収事業の団体支援","agenda":"集団回収事業の団体支援","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"雑がみ回収なのですけど、取り組んでいる団体の全体の何％ぐらいの団体が取り組んでいらっしゃるのか伺いたいと思います。１,０００円の協力金ということですが、この額の根拠についても説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"雑がみの回収につきましては、大体ですけど６割前後の団体にお金を出しているという状況です。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"６割というのは、もう少し引き上げることで、さらに雑がみ回収に取り組んでいただける団体は増えるのではないかと思うのです。もう少し引き上げて、そういった取組にできないかなと思うのですけれど、いかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"大体どこの区も６円程度ということで、昨年までの金額が２３区の中での基本的に平均的な金額ではないかというように思っております。そういった意味では、８円に上げているということで、この件に関しましては、品川区は先進的に進めているというものです。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党としてもこの報奨金は前から要望していた部分なので、今度上がったことによって、各団体も非常に喜んでいるというのを聞いています。これ、７円が差額が出た場合ということですが、現在の段階ではまだそんなに影響はないということでいいのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"これは令和２年度から、やはりコロナ等の関係で、この紙の引取価格がかなり下落をしております。現在のところ、７円を下回っておりまして、その分について昨年度、やはりその分を補う助成等をしています。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"金額、今が７円にどのぐらい乗っかっているのかちょっと分からなかったのですが、うまく対応していただきたいなと思います。区の対応を、今もやっていらっしゃいますけれど、今後の見通し的なものを改めてお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"行政回収につきましては、行政の負担分を減らしていくという効果もありますので、こういう集団回収の団体をやはり増やしていきたい。非常に効果があると考えておりますので、そういった面も見ながら、集団回収が少しでも向上していくように考えていきたいと考えています。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"見回りをやっていると思うのですけれど、まだまだその業者が出ているということに対して、区としてどう考えているか。そこら辺の今後の対応についてお聞きしたかったのです。","respondent":"品川品川区清掃事務所長","answer":"なかなか、その場で指導をしても、やはり引き続きやってしまうというような傾向もあるかというように思います。それから、全体としては、やはり常習犯が大分いらっしゃるみたいで、こういったところも集中的に指導を強めて、今後もやっていきたいと考えています。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"お話があったマンションの管理組合の方たちの状況をちょっと参考までにお聞きしたいのですが、小規模、状況が分かりますでしょうか。活用していただきたいという動きの中で、呼びかけて、その団体を増やしているのかというところの取組状況を説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"新築のときに一緒に説明をするだとか、それから順次回って呼びかけをしていくだとか、いろいろな方法が考えられるかと思います。どういう方法が効果的かというところも検証しながら、今後その辺も考えていきたいと考えています。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"大きいところでも、されているところはどういったきっかけでこれを始めたかというようなところを押さえてみるのも一つかなというように思うのです。今後そうしたその集団回収の品目を拡充していくというようなお考えは、どのようか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"品目についてですが、今のところは紙類それから古着、缶等、基本的なところは回収できているかと思います。ただ今後、より協力をしていただくというような方向性はあるかと思いますので、そういった部分も考えていきたいと考えています。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"脱プラの関係で、やはりそうしたことを考えていかれると、今伺いました。こうしたものも入れていくことが必要かなというように思いますので、今後ご検討いただきながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"集団回収のグループということで、町会・自治会、マンション、ＰＴＡというところなのですけれど、その集団回収の作業をしているときに何らかの事故等、けがとかトラブルとか、そういうことが発生したときの保険のようなものというのは、どういう待遇になっているのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"こういったところの保険ですが、現地点で、この集団回収に対しての保険というところは、区としてサポートはしてございません。それから集団回収団体によってもいろいろ、別々だとは思いますが、そういうところでの対応という形になるかとは考えております。","id":"exchange-017"},{"speaker":"つる委員","kind":"確認","question":"先ほど鈴木真澄委員からの話があって、そういえばそういうことがあったなということで、ちょっと改めての確認なのです。そういう積極的な支援と、そうなってしまったときの対応という部分では、どういう対策になっているのかを確認させてください。","respondent":"品川品川区清掃事務所長","answer":"ある種、団体活動の一環という考え方からすれば、その団体等で保険加入をどうするかというところが一つの考え方というふうになってくるかと思います。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった形のときにも適用できるということを明確に、清掃事務所のほうでもはっきりと分かるような形で確認等をしておいていただきたいなと。いずれにしてもトラブルのないよう、けがのないよう、事故のないようにというところで、引き続きの支援をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"このキャナルアートモーメントのほうは、２回目でも予算は普通に変わらずつくというものなのでしょうか。これらの、こういう共催プログラムという予算についても、東京２０２０大会の開催総予算に含まれるという考え方でよろしいのか、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから私どものＳＮＳやホームページ等でも周知の予定です。委員ご指摘のとおり、キャナルアートモーメントに関しましては、去年も実施しております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"一度実施しているキャナルアートモーメントですけれど、２回目をやるということになるのですけど、１回目の開催を踏まえて、２回目というのは何かこう変化というか、工夫というのでしょうか、そこら辺はどういう考えなのか、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大会自体は延期になってしまいましたが、これ自体は世界に発信できるものだということで、去年、実施をいたしました。かなり多くの方に視聴いただけまして、今回、いよいよ東京２０２０大会に合わせてもう一度開催しようということで企画しているものです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"では今回はオンラインだけではなくて、そういうことも実施するということですね。ちょっと先ほど質問したのですけれど、今回の場合はどうなのでしょうかという質問をしたので、そこだけ聞かせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"中止になった場合の取り扱いですが、今時点での決定ということはございませんが、大会の有無に関わらず、こちらの世界に発信できるものということでは、やっていきたいなと考えております。","id":"exchange-022"},{"speaker":"田中委員","kind":"意見","question":"区民観戦は実施をするとのことだったのですけれど、その観戦の方法と観戦できる方というのはどうやって選ばれるのかといったところもちょっとお知らせいただければと思うのですがとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"まずキックオフであるのですけれども、口コミや、その団体からいろいろなところに周知がいくかなと考えています。それから観戦ツアーについてですが、これは広報しながわでメンバーを募集しまして、抽選で決まるというものです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"どちらがどんな目的でどんな話し合いを、いつ、何回ぐらい重ねて移転が合意決定されたのでしょうか。ちょっと伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"品川区大井一丁目２０番６号とどちらも同じ住所ですが、一般社団法人のしながわプロスポーツ振興協議会という団体が立ち上がりました。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"そういって、このプロスポーツチーム区内移転のこの２チームのメリットについて区はどういうふうに考えて承諾したのでしょうか、伺いたいと思います。デメリットと言うとちょっと言い過ぎかもしれないですけれど、そういったところについてはどういうふうに考えていらっしゃるのか尋ねました。","respondent":"石田（ち）委員長、中元スポーツ推進課長","answer":"区民委員会でも報告をされている内容ですけれども、私としては、この場でお答えいただける内容ですので、お答えいただけたらと思います。 ホームゲームですが、現在、総合体育館の主競技場は大変利用頻度が高いので、実際にはなかなか難しいかなと考えております。決して区民の利用枠を圧迫するということでは考えてございません。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一つ伺いたいのは、やがてアリーナ建設を考えていますよという話を、それぞれの団体との話し合いの中で出したのでしょうか。ちょっとそこだけ確認させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-04","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今のこの感染症が広がっている状況があるので、文言については気をつけていただきたいなということを思っております。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"渡部副委員長","kind":"質問","question":"委員会を１年やってきた中で、その７月２日時点での委員会で調査した内容で、これはそのままでしようがないのかなという。しようがないというよりも、そういう議論があったわけですから、そこを変えることはできないのかなというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"ご承知のように、共産党としては、やはり今年夏のオリンピック・パラリンピック開催は中止をすべきだという立場には変わりありません。すみません、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"田中委員","kind":"確認","question":"ちょっと確認なのですけれども、この状況の中で区民が見たときにどう思うのか、提出することは構わないのですよね。やはりこの「前向き」というような文言はちょっと消したいとか。","respondent":"石田（ち）委員長","answer":"そうですね、ご意見や修正案はご提出いただいて構わないです。そして、その上で正副委員長でまた検討するということになりますので。","id":"exchange-030"},{"speaker":"こんの委員","kind":"確認","question":"体裁というところでちょっと確認なのですが、これ、やはり項目別に、１枚、１枚、この記の上のこの文章は、こういう形でということだったのでしたか。これ、何というのでしょうか、その冒頭とその下の部分というのは、どこにもついている文章なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"これは１枚、１枚のほうがいいのですか。そこら辺のところはどうなのでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"こんの委員","kind":"意見","question":"なるほど、分かりました。ちょっとそれが気になったので、どうなのだろうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"もう一つは、機運醸成に関することのまとめに書いてある、先ほども話が出ましたけれども、「７月２日時点のものですが」という日付が入っていますが、それ以外の各調査事項の調査の日付はどうなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"渡部副委員長","kind":"意見","question":"すみません、ちょっと考えます。田中委員が先ほど言ったものも含めて、また、それは統一したような感じで次の委員会に出するということでご了承ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"ここで発言しなくても修正案を出すのは可能ですよね。ここで発言しなかったから駄目だとか、そんなことはないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"田中委員","kind":"意見","question":"今の「さっき言ったじゃないか」とかいうものは、議事録に残りますか。そういった発言は副委員長としていかがなものかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/343398?Template=document&Id=6592#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25757,"voices":113}},{"id":"r03-20210428-10","meetingId":"r03-cm04","date":"2021年4月28日","dateIso":"2021-04-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":6587,"voices":39}},{"id":"r03-20210514-10","meetingId":"r03-cm05","date":"2021年5月14日","dateIso":"2021-05-14","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"東京都後期高齢者医療広域連合議会議員の選挙における候補者の推薦","agenda":"東京都後期高齢者医療広域連合議会議員の選挙における候補者の推薦","exchanges":[{"speaker":"本多委員","kind":"意見","question":"この選挙にあたりまして、品川区議会からの選出方法なのですが、議長経験者の中から品川区議会を代表する候補者を出すべきだと思います。今までの慣例もそうでしたけれども、やはり品川区議会を代表してのということで、選出方法については議長経験者でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はやはり立候補したい人が、自らまたは会派から推薦をして、やりたい人が出るというのがよろしいかと思います。しかも東京都後期高齢者医療広域連合議会での意見や態度については異なる部分もあるだけに、しっかりと立候補をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"今言ったほうがいいですか。共産党からは、石田ちひろ議員が立候補したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"私だけが耳が遠くなったのか、そう言われるとそれまでなのですけれども、一応、藤原議員にも確認をしたら、聞こえにくいと。その辺、もし工夫できるようでしたらご対応をお願いしたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5410#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":7867,"voices":40}},{"id":"r03-20210517-6","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"区民委員会","time":"午後 １時００分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"の順番を入れ替えて、２、その他","agenda":"の順番を入れ替えて、２、その他","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"１つだけ確認させていただければありがたいのですが、行政としてその辺はどう考えているのか、聞ければ幸いなのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"令和２年度町会・自治会活動活性化促進調査の中間報告書","agenda":"令和２年度町会・自治会活動活性化促進調査の中間報告書","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"そこに関しては、アンケートの結果をいただけなかったところからその後追加で何か情報をいただけたのかという確認が１つと、その配付の際に。この報告書に添えていただきたいと思うのですけれども、そこに関してどうされる方針なのか、まずその２点伺います。","respondent":"川島地域活動課長","answer":"こちら、９ページに出てくる表を見ていただけますと、そうしたデータが出ておりまして、八潮地区の回答率が４６.４％になってあります。最終報告には組み込めるとは思うのですけれども、多分これ以上のご回答をいただけることはないのかなと考えています。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"八潮の回答率４６.４％の部分について触れていただいたのですけれども、回答がなかった１５の自治会ですか、そこに関してのお考えを伺いたいです。","respondent":"川島地域活動課長","answer":"こちらはあくまでも推測ですが、現役で働いている方も多くいるようですし、忙しくてなかなか活動の時間が取りづらいような方も多いと聞いております。今回のアンケートは非常に項目が多く、回答も負担になったのかなと私どものほうでは分析しています。","id":"exchange-003"},{"speaker":"くにば委員","kind":"質問・要望","question":"これは要望です。これが大井地区が２.９％、ほかの地域は０％ということで、例えば具体的にどのようなものがあるのか説明を求めました。","respondent":"川島地域活動課長","answer":"子育てに関する支援という形になりますと、子どもの集まる場や親御さん同士の交流も含めて子育て支援につながるようなものではないかという形です。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問","question":"具体的にアンケートをお聞きするときに、それぞれの活動がどれに該当するかということはどのように説明をなさって、このアンケートを取ったのか尋ねました。","respondent":"川島地域活動課長","answer":"きっちりした正確な数値が出てくるということではないのですけれども、大まかな活動の内容については傾向というか、それは反映されるだろうというところになるのかと考えています。","id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"２６ページにあります、もう少しこの活動もしたほうがいいのではないかというような結果というのは、何か見えてきたのでしょうか。そういった時期的なものもあるとは思うのですけれども、それぞれこの具体的な活動実績についての分析は何か伺えますか尋ねました。","respondent":"川島地域活動課長","answer":"なかなか各町会ごとの分析、何ができていて、何ができていないというよう活動診断のような形での分析はしていないところです。","id":"exchange-006"},{"speaker":"くにば委員","kind":"意見","question":"最後に、今現在、町会・自治会に関するヒアリング調査で、既に行われたのが女性会長であるとか、マンションに関してのヒアリング結果だと思うのですけれども、これから行っていくヒアリングが残り幾つかあったと思うのですが、それらの進捗状況だけ最後に説明を求めました。","respondent":"川島地域活動課長","answer":"残りのヒアリングを３つぐらいのカテゴリーでやりたいということで、次が５月中に、準備しています。そのほかの２つのカテゴリーは、これから検討していくところになっております。","id":"exchange-007"}]},{"id":"topic-03","title":"期限切れマイナンバーカードの紛失事故","agenda":"期限切れマイナンバーカードの紛失事故","exchanges":[{"speaker":"くにば委員","kind":"確認","question":"はその担当の方がどのような部分を必ず確認をしてやるべきだったのに、そこを確認をしていなかったがために起こってしまったか、もう一つが。マイナンバーがついているとどういった問題が想定できるのか、そういった問題についてはどのように今回は回避をする予定なのか、その２点伺います。","respondent":"木村戸籍住民課長","answer":"住所や名前などを使って何か悪用であるとか、嫌がらせであるとか、そのような部分というものは考え得るところです。警察のほうとも連携をいたしまして、すぐ１１０番をしていただく、被害者の方とはご連絡を取ってあります。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"１点目、それを区民の方や国民の方が見たときに、これはなぜ起こったのだ。最後に１点、複数の職員で確認の上、現在行っている流れというものを何か確認した上で参考にしたのか尋ねました。","respondent":"木村戸籍住民課長","answer":"今回このことに関しては、他の自治体の動向などというよりも、まずそれが最善であろうというところで、私どものほうで進めたものです。その後も他自治体の状況については確認はしておらないところであります。","id":"exchange-009"},{"speaker":"くにば委員","kind":"意見","question":"今回勉強するという形で、他自治体でどのようにして流れをやっているかということは聞いてみたらいいのかなと思います。最後は所感ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"藤原委員","kind":"確認","question":"確認なのですけれども、警察署から保護者の方に、このようにカードが落ちていましたよという電話があったのですよね。その辺についてはいかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"ご指摘のとおりで、なかなか言えるところ、言えないところはありますけれども、ただこの警察署につきましては、埼玉県の警察署に届けられたです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう少し原因、しつこいですが、遠いところまでカードが行ってしまうわけないではないですか。全体として、きちんと押さえていていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"なくしたことすら分からないというような状況を防ぐという意味でも、この再発防止、その場で破砕をするというような形を取ってまいるところです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"探して探して、そうしたら警察署から連絡があったということなのか、警察署から連絡が来たことでなくしたということが分かったということでいいのか尋ねました。","respondent":"木村戸籍住民課長","answer":"まさに後者でございまして、警察のほうから連絡があって分かったということです。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かれば教えていただきたいのと、要はシュレッダーなのですか、そのようなことでいいのか尋ねました。","respondent":"木村戸籍住民課長","answer":"時間帯ごとで柔軟に対応しているところもあるのですが、この４月からそのような形で強化をしてそのぐらいということです。４月から採用をされた職員、通常ですと考えられない動線なのですけれども、そのようなことが発生してしまったです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"土曜日もやる、来年の２月までやるというご報告もありましたけれども、本当に職員の皆さんにも大きな負担になってくるなと感じています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"小芝委員","kind":"質問・要望","question":"やはりその辺広く、また、なぜそれが不慣れな環境であったのかをしっかり検証していただいたほうが再発の防止につながると思います。その一方で当然に区民の、その辺しっかりとそれ相応の職員の方を充てて対応していただきたいということを意見して終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ちょっと確認で、それを求められているという緊張感というものは、関係ないわけです。今後も含めて連携して、カードを拾っていただいた状況で１点確認で、カードだけが単体で落ちていたのか尋ねました。","respondent":"木村戸籍住民課長","answer":"先ほども申しましたが、後で持っていこうとそのときは思っていたというところではないだろうかというところまでしか、よく分からないです。なかなか裏づけあってこうですというところでご説明できないのがちょっと苦しいところなのですけれども、今のところはそのような形で。","id":"exchange-017"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そのようなことではなくて、やはり改善をしていかなければいけないわけですから、そのような部分でのことをどこまでやるのかと。区の行政サービスというところでは、より一層の向上を図るというところでの改善策と緊張感を持ってやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2896#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":17157,"voices":55}},{"id":"r03-20210517-7","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"品川区立大崎高齢者多世代交流支援施設（大崎ゆうゆうプラザ）","agenda":"品川区立大崎高齢者多世代交流支援施設（大崎ゆうゆうプラザ）","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今、委託でやっていて、何か課題が出てきて、それで指定管理に変えられるのでしょうか。何かそういったことで変えられるのかなとかいろいろ私としては思ったりするのですが、そこら辺のことをご説明願えればと思います。","respondent":"菅野高齢者地域支援課長","answer":"どちらか適切な運営方法を検討するために、そのように規模に応じて委託、指定管理というふうに分けた次第です。平成２８年度の開設から利用者数を伸ばしておりまして、特に課題等、利用者にも親しまれる事業運営をしていただいている次第であります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、大規模あるいは複合云々に関わらず、要するに指定管理のほうが管理上効率がよくなるということなのか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"私、先ほど最大のメリットとして管理上の効率性のことをお話しさせていただきましたが、それだけではなく、今後、高齢化が進む中、積極的な事業展開が期待できるということで、他のゆうゆうプラザと運営形態を統一化したいと考えた次第です。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"それから、基本的に区が求める業務内容の変更は業務委託から指定管理になることで変わることはないのか。今の業務委託の委託料と指定管理になったときの指定管理料というのはどう変わっていくのかという点についてもお聞かせほしいと求めました。","respondent":"菅野高齢者地域支援課長","answer":"７００m2ということで、いろいろ考えた結果、今回につきましては指定管理に移行することが適切であると判断させていただいた次第です。そちらが約４００万円ちょっとあるということで、さらにそれがプラスされて、指定管理料となっていくのかなと思っています。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"基本的に区の支出が変わるということではなく、同じ経費で運営ができると考えていいのでしょうかということを確認させてほしいと求めました。それから、外部委員は何人ぐらいで、それから区の職員としてどういう部署が関わっていくのかについても教えてほしいと求めました。","respondent":"菅野高齢者地域支援課長","answer":"予備委員会と選定委員会という２段階方式にして、その基本方針に沿った形で、選定委員を選んでいきたいと考えています。６月に入りましたら公募を開始させていただいて、先ほども説明させていただきましたが、６月下旬に説明会をして。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"透明性・公平性・公正性・客観性が担保されるような形での選定ということでぜひお願いしておきたいと思います。ボランティアの組織などはスムーズに行われたのか、また、課題とかが何かあれば教えてほしいと求めました。","respondent":"菅野高齢者地域支援課長","answer":"基本的には週１回させていただきまして、定員１０名ということで行っておりまして、評判がいいと伺っております。ボランティアを集めてということですが、その辺のノウハウを活かしてボランティアを募ったと聞いております。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、これから引き継がれるところに対しても、総合事業の地域ミニデイはゆうゆうプラザの事業として行ってくださいということで業務の中に入っていると考えていいのか、その確認だけお願いします。","respondent":"菅野高齢者地域支援課長","answer":"は事業者が決まった際に、継続していく中でお願いしていくなど、いろいろと考えていきたいと考えています。","id":"exchange-006"}]},{"id":"topic-02","title":"食品衛生法の改正に関する事業者への周知","agenda":"食品衛生法の改正に関する事業者への周知","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"猶予期間もありますから、何かそういうお気づきのところに網を張っておいて、地域からもお声をお寄せいただいたりとかで、漏れのないように進めてほしいと求めましたので、確認だけさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今、品川区内での変異株の状況の調査とか把握というのはどういうふうになっているのでしょうか。お伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"およそ４割の検査をしていると聞いておりますけれども、現在までのところ、何割というほどではございません。何人かは変異株ということを確認しておりますけれども、全体に対する割合がすごく多くなっているという状況までには至っておりません。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"何人かというところですが、品川区の陽性の方の中でどれくらいの方が、変異株の検査をされているうちのどれぐらいかというのは分かるのでしょうか。若い方への感染とかなんかもどんどん広がっていたり、品川区の感染状況の中でそういう実態があるのかについても説明を求めました。","respondent":"鷹箸保健予防課長","answer":"そういった対応も必要な場合に実施しておりますが、幸い学校で５人以上のいわゆるクラスターが発生しているという事実は、４月以降はございません。日々の対応を聞いていますと、３０代でより重症化しているというような印象は、現在のところはまだ持っておりません。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"クラスターは４月以降は４施設で全て企業だということですけれども、では、４人とかそういうことで休校したということだったのでしょうか。感染対策、その濃厚接触者の考え方というのは、現実にはどういう形でＰＣＲ検査がされているのかについてもお聞かせいただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"もう少し感染が広がっている可能性もあると考えて、５人以上、たくさん感染者が出ているのでということではございません。ただ、その施設で例えばそのフロアの全従業員・全入所者を検査するとか、検査については幅広く実施していくことになります。","id":"exchange-010"}]},{"id":"topic-04","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"その辺が今どうなっているのかというところと、１時間遅れというのは変わらないのかというのを教えていただきたいのと、ではネットで予約するよと。電話でオペレーションをする人はその画面で予約をきちんと管理できるのですよねというのを聞きたい、確認したいです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それで対応いたします。電話の方が電話対応中に埋まってしまうことがないように、あらかじめ枠を調整しておいて対応するということで、１９日を迎えたいと考えております。","id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"ワクチンは安定的に入ってくるという話で、私も院長先生にお話を伺ったりする中で、多分この量があれば６５歳以上の方までいってしまうわけです。予約してとか、今、少し先のことまで見据えて品川区として考えていっているのかどうなのかというところの途中報告を説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"各掲示板等々に最新の情報をポスターという形で、情報が更新されたら都度貼るということで、現在既に対応しております。もちろん引き続き検討はしていますが、７月末あたりから、何かしらの形でうまい方法を検討して進めていければと考えております。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"課長に説明していただいたようなやり方で十分だとは思うのですが、できれば、月２回の回覧板があるではないですか。いつがご希望ですか、１人１０分や１５分では終わらない話になるわけですよ、電話の予約が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"確認","question":"４日で、いいのでしょうかという確認と、知的障害者の育成会の方からもお問い合わせをいただきました。その辺についてもう１回確認、さっき、そこについてどういうふうにされるのかというのをまとめてお伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"これは現在検討しておりまして、一般の方の予約開始日よりも先に、６月１４日のように分けて設ける形で現在検討を進めております。なので、基礎疾患の方と一般の方が用意ドンで同時にという形にはならないようにしたいなということで現在検討を進めているところです。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"例えば港区や世田谷区にそういう書類を求める場合にはどういう手続きを取ったらいいのか、特に世田谷区は非常に分かりやすかったのです。いかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"約４万６,０００人おりますけれども、その段階で４万６,０００以上の枠を用意して１９日を迎える予定ですので、そこは現時点では考えておりません。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問・要望","question":"逆にいうと、品川区は先週の段階ですか、相当な苦労があって前倒し郵送をある意味達成したと。最初にお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"全庁の皆様のご支援をいただきまして、約７０名ほどの人を集めていただいて、本当に我々も大変助かりました。恐らく電話は、もしくはＷｅｂに接続していただくということで十分対応できると考えておりますので、ご協力のほどよろしくお願いいたします。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問","question":"想定よりも優しく対応できる、例えば電話にしても、希望日時があったとするではないですか。ではこの日ならどうぞ、この日ならどうぞと、いかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"委員ご指摘の今のお話、コールセンターとすぐに連絡を取りまして、対応させていただきたいと考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"電話にしてもＷｅｂにしても、品川区の２５台のコールセンターの電話台数というのは、やはり２５台でいくということなのかということと……。〔「さっき５０台に増やしたって言っていた」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから、品川区としては７月末までにできる自治体ということで回答されたのか、その点についてもお聞かせほしいと求めました。品川区は歯科医師の協力についてはお願いしないで、医師会との協力でできるという状況なのか、その点について教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"７月末でできるか否かということですが、７月末でということで回答はしています。使わない、入っていただかないということではなくて、幅広く調整を進めているです。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"６月をめどに個別接種会場、品川区内にクリニックとかは２００近くあるのですかね、かなりあると思うのですが。そういうことで高齢者が接種を受けやすくしていただきたいなと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"とは言え、その辺りは電話対応になろうかと思いますが、ホームページ等々で明記するようなことは現在考えておりません。移動支援につきましても、区として検討の俎上には上がりましたが、タクシー券を配布するような支援については現在考えておりません。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これも６月中旬からということなので、移動の支援は本当に必要ではないかと思うので、検討している中身についても教えてほしいと求めました。先行して行った高齢者施設での接種で特に課題になっていることはないのか、その点についてもお聞かせほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その辺りで、６月のしかるべき時期が来たら病院、クリニックで接種を始められる方向で現在検討を進めております。これからだよ」と呼ぶ者あり〕 ただ、医師会を通じてお話を聞いているのは、今週末あたりに大体医師会で把握している１回目の接種が終わりそうと聞いております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高齢者施設で１回目が終わった人数は何人かというのが分かったら教えてほしいと求めました。巡回接種とかの体制も必要なのではないかなと考えるのですが、その点についてはいかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それから在宅の方についての接種ですが、現在、こちらも医師会と調整というか相談というか検討を進めているところです。ただ、もちろん行ける方と行けない方がおりますので、その辺りどういうふうにしていくかということの検討を現在進めている段階です。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"様子を見るというのは在宅でどういうふうにしたらできるのかという思いもしているのですけれども、１５分とか３０分とか様子を見ますよね。〔「３０分」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"３０分、そういうことも含めての巡回接種ということで、区としてできないかということで検討しているのか。検討の中身について教えていただきたい。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"在宅の方ですので、訪問でできないかということで、打ちにいくことができないかということで現在検討、それから協議を進めている最中です。現在検討というか協議を進めている最中です。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そして、かなり切実な思いで質問を受けたので、その点の検討の体制と検討の状況についてもお聞かせほしいと求めました。それからもう１つ、それから予約をどうしていくのか、そういう連携の体制はどう取られているのかについてもお聞かせいただけたらと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長、鈴木（博）委員長","answer":"実際にできるかどうかということを含め、現在、検討・協議を進めているです。やはり医師がいないと当日の予診ができませんので… すみません、ちょっと飛んでしまいました。申し訳ないです。 介護につきましては、在宅介護支援センター等の協力が得られるように今話を進めておりますので、できるように進めてはおります。 まだ始まるばかりで、決まらないことが多くあるところなので、答えられるところだけ答えていただければ結構です。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"なので、きめ細やかな、様々なところとの連携も取りながら、支援の体制をぜひ取ってほしいと求めました。保育園とか学校職員とかなんかも含めての優先接種についてはどういうふうに考えられているのかについてお聞かせほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"高齢者の次は基礎疾患を有する方であったり高齢者施設等々の従事者ですので、その枠で打てるようにこちらのほうで準備を進めるというものです。施設を回っているときに、余った分のワクチン等々で先に打つことは認められておりますので、その辺りについては接種を進めているです。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"様々な課題もたくさんあると思うのですけれども、様々なところと連携をしながら、スムーズにいくように取組んでほしいと求めました。どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問","question":"１点だけ、すみません。１つ、こういったことを品川区でももしできればと思ったのですが、いかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"見やすくなる一覧表みたいなもの、現在検討を進めておりますので、うまくいくように進めてまいりたいと考えております。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから、これは私よく分からないのですけれども、もし接種会場が停電とかになったら、冷凍の機械とかは大丈夫なようになっているのですか。あるいはコールセンターに車で行っても大丈夫ですかとか駐車場はありますかとか、そういったことについての対応はどういうふうに考えるのか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"どこの病院かというところは、申し訳ありません、分からないところです。やはり４番スタンドまで確かに距離がありますので、ですので、ご承知の上ご来場くださいということでご案内したいと考えております。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこはどうなのでしょうか、どなたかが外にいるのかとか、そういったところは気をつけたほうがいいのではないかと。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そこのところは１回目のときに予約できてしまうのが一番いいのではないかなと思うのですが、６５歳以上７４歳までの人はもう１回取り直すという形になるのか、その点だけ確認をお願いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"結論、会場で２回目の予約についてはお取りするというか、取った状態でご案内をする方向に変更いたします。できれば３週間後の同じ会場、同じ曜日、同じ時間でご協力くださいということでご案内する方向で現在運用を固めました。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3594#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":35099,"voices":91}},{"id":"r03-20210517-8","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"建設委員会","time":"午後 １時００分～午後 ４時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件整理しています。","topics":[{"id":"topic-01","title":"令和３年陳情第１４号、コミュニティバスの運行に関する陳情","agenda":"令和３年陳情第１４号、コミュニティバスの運行に関する陳情","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"これに併せて要望もしてしまうのですけれども、ほかの２ルートについても、やっぱり運行を開始してほしいということを思います。資料を先に見せていただきたいと思ったのですけれども、そのように判断された理由をお知らせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"田中委員","kind":"意見","question":"たったの１枚だけで、とても分かりやすい資料だったと思うので、ぜひ配付していただけたらなということを思いました。これは意見として発言させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"１１時台、約３０分間歩いていかなければいけないということになってしまいますので、交通の不便さがあるというふうに思います。この南大井の住民の交通の不便さを、区のほうでは認識しているのかどうかというところで伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"１３地域それぞれで、大井第一地域センター管内に限らず、地域センターごとで行ったワークショップでも様々にいただいているところです。１１の指標を点数化して、各１３地域を比較して最終的な候補ルートを、より導入効果の高いルートを選定したという区としての認識です。","id":"exchange-003"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"どうやってルートを決めていったかというのは分かりましたけれども、そうではなくて、南大井の住民の不便さを、区はどのように考えているかということでお聞きしましたので、その答弁をほしいと求めました。","respondent":"鈴木都市計画課長","answer":"そうした中で、この大井ルートは、多少大井第一地域の南大井六丁目のほうも地域センターをまたいでルートを設定していると。そうしたところには、大井第三地域センター管内ですべてのルートを完結せずに、そうしたルートの設定も１つには配慮をしています。","id":"exchange-004"},{"speaker":"のだて副委員長","kind":"質問","question":"伺いたいと思います。利用率も上がっていくということで、利用しやすいルートになると思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"こうした声は、先ほどからの繰り返しになりますが、１３地域でそれぞれでいただいております。１３地域においてワークショップを実施した大きな視点は、ワークショップを受けて、ルートにも反映してきているです。","id":"exchange-005"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"反映すべきところは反映してきているということですが、反映させなかったということには、どういった理由があったのか。実際にこの南大井を通るルートを検討したのかということで質問をいたしましたので、そのご答弁もいただきたい。","respondent":"鈴木都市計画課長","answer":"冒頭の説明の中でもご紹介したとおり、いただいたご意見の中で当然検討はしましたけれども、ルートに反映するという形では行っていないです。","id":"exchange-006"},{"speaker":"のだて副委員長","kind":"質問","question":"伺います。やはりこうした利便性が上がっていくルートにしていくべきだと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"やはり１３地域ごとで補完という意味合いで、大井第一地域の中を通って、やはり近傍に民間のバス路線があるというところで検討から外れているです。","id":"exchange-007"},{"speaker":"のだて副委員長","kind":"質問","question":"大崎ルートでは検討して変更したということですけれども、それがこの大井ルートではなぜできないのか、伺います。","respondent":"鈴木都市計画課長","answer":"やはり同様のルート、大井町駅へ向かうルートが近傍にありますので、そうした観点から設定をしていないです。","id":"exchange-008"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"ほかのルートをやらないのかというところの質問で、判断の１つとして、コロナ対策のために試行運行を１本に絞ったということなのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"この場でご紹介することはできませんが、６月上旬の事業者選定に向けて、プロポーザルを実施しています。それのみをもって３本を１本にしたということではございませんで、やはり３つの候補ルート案のうち、適時適切に判断していきたいです。","id":"exchange-009"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"コミュニティバスの試行運行を１本に絞りながら、再開発、超高層などは変わらず進めていくという区の姿勢はおかしいと思っています。１ルートをやって判断をしてやめてしまうということはないようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"３ルートにはそれぞれ地域特性があって、ＰＲの仕方ですとか、そうしたほかの２ルートに全く反映できないということではないと考えています。","id":"exchange-010"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"陳情の要旨の２項目目なのですが、京急バスの八潮－大井町駅路線の復活を求めているのと、どのようにお考えなのか。いかがでしょうかということと、八潮－大井町駅路線が廃止になった理由を事業者から聞いていましたら教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"陳情にあります八潮－大井町駅路線の廃止ですけれども、こちらにつきましては、昨年の３月末をもって京急バスが廃止しています。説明があったのは、ただ、大きくはやはり利用の実態がなかなか上がってこないというところも並行して説明があったところです。","id":"exchange-011"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この京急バスについて復活と増便を求めているわけですが、区としてのお考えを伺いたいと思います。私は、ぜひ住民の利便性向上のために区としても動いていただきたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"民間バス事業者の実施体制といいますか、営利的なところも踏まえて検討されるですので、例えば補助２６号線が開通した場合のバス路線の新設ですとか。すべて行っているというところはございませんが、声としては業者にはしっかり伝えているというような状況です。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"やっぱり民間ですから、福祉という観点がどうしても入らざるを得ない状況になるので、そことの兼ね合いですよね。は民間事業者の方々との意見交換の在り方とかというのは、今後どういうふうな形で進めていこうとされていますか尋ねました。","respondent":"鈴木都市計画課長","answer":"非常に長い時間バスに乗っていなければいけないということも考えることから、まずは、民間バスルートを補完する形でルートを設定しています。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな見方も出てくるかと思うので、今後も継続的にお話し合いがされるということですから、それに期待したいなと思っています。広くやっていかなければいけない、そういう方向だと考えていますので、そういう視点で収集しながら進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"確認だけさせていただきたいのですけれども、区民の声を受けて区が判断をするという捉え方で大丈夫ですかという確認をさせてほしいと求めました。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"試行運行開始後、これも先の建設委員会の中でご説明させていただいたかと思うのですが、そうしたものを立ち上げて。この収支率５０％というのは、これはこれまでもご説明しておりますし、いろいろご意見をいただきながら検討していきたいです。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"区民の方が求めているのであれば、この収支率５０％ではなく、そういった運行をしてほしいと求めました。今回のこの陳情、まだ少なかったのだろうなということを思いますので、常々聞く機会を設けていただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"コミュニティバス、これまでも様々な、数多くの陳情が出される中で、まさに様々なご要望が地域から出されているという中だと思います。今日の個別のルートも含めて、様々なルート、要望をまた１つ捉えられたというふうに私どもは理解をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと、やはり要望と現実とは大分違うところもあります。個別の案件について、要望を取り入れて変更するという作業は非常に大変な作業になりますので、このところは承服できない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"のだて副委員長","kind":"意見","question":"結論を出すということで、採択を主張します。やはり住民の方々が交通不便を感じているというこの困難を改善していくためにも重要だというふうに思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"コミュニティバスの個別の判断というのはなかなか難しいなと、それぞれの要望を聞いていると、そのルートもどんどん広がっていってしまうので。やはり話し合いの場が少なかったと思うので、ぜひそういう機会をこれからももっとつくっていただきたいということで、趣旨採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり住民の皆さんの気持ちもあるので、こういう地域はこういう不便さがあるのだなとかというのは、大きな情報の１つだと思うのです。今回は不採択という形にしましたけれども、情報として区議会に提出していただいたということは本当にありがたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"品川区営住宅・品川区立区民住宅指定管理者候補者の公募","agenda":"品川区営住宅・品川区立区民住宅指定管理者候補者の公募","exchanges":[{"speaker":"田中委員","kind":"質問","question":"選定委員会のことでお伺いしたいのですけれども、「（６）その他委員長が必要と認める者」という記載が委員会構成の組織の中にあるのですが、どういった方がいたのかということをお伺いしたいのですけれども。","respondent":"竹田住宅課長","answer":"しかし、今年度につきましては、一定、選定委員会の形の見直しを行いまして、二段階で選定委員会を開くことを予定しております。その中で選定したものについて、さらに外部委員を含めた選定委員会にかけまして、最終的に候補者を選定する予定です。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"そういった委員の方たちが、これからは組織の一員になるのかなと思ったのですけれども、いかがでしょうか。その辺をお知らせいただけますか。","respondent":"竹田住宅課長","answer":"総務委員会でご報告させていただいた内容に沿いまして、今回、区全体で選定委員会の方式を改めて、今年度より開催する予定です。有識者の方は、２名参加していただくのですが、できるだけ福祉に造詣のある方を選定していきたいと考えております。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"これはどうやって評価をするのでしょうか。数値が一番いいのでしょう、分かりやすいと思うのですが、これはどうやって選定していくのか尋ねました。","respondent":"竹田住宅課長","answer":"選定基準ですが、こちらには掲載しておりませんけれども、具体的な選定基準を定めまして、それを点数化しまして、総合的な点数で評価します。あるいは社員教育などを具体的に計画、ヒアリングしまして、審査して総合的に決めたいと考えております。","id":"exchange-024"},{"speaker":"西本委員","kind":"提案","question":"ある程度分かりやすいものが必要かなというふうに思いますので、今後、改善していただきたいと思っています。それともう１つは、提案をしていただいたりということが必要だと思うのですが、どういうことを要求していきたいのかというのはいかがか尋ねました。","respondent":"竹田住宅課長","answer":"今までの指定管理者で行われました内容ですが、例えば、地域づくりとか、それから居住者間のトラブルの回避等々をやっていただいております。今後も区民サービスを的確に捉えた満足度の高いサービスをしていただける指定管理者を選定していきたいと考えております。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"それが本当に生かされているのかどうかというのは、区として何をしたいのかというのをもう少し明確にしていただきたい。そういうものも含めて評価をするという認識でよろしいか尋ねました。","respondent":"竹田住宅課長","answer":"このプロポーザル方式による公募の趣旨ですが、民間企業の能力やノウハウを活用して、満足度の高いサービス、あるいは経費削減をするものが今回の趣旨ですので、新たなる提案等をしていただきまして、よりよい指定管理にしていきたいと考えております。","id":"exchange-026"},{"speaker":"のだて副委員長","kind":"質問","question":"そうした中で、株式会社というのはなじまないのではないかなというふうに思っております。１つの目的としては、直営にしていくべきだと考えますけれども、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"区営住宅につきましても、平成１８年度からこの制度を実施して一定の成果を上げているところです。直営に戻す考えはございません。","id":"exchange-027"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"戻す考えはないということですが、やはり私は、直営にすべきだということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"品川区耐震改修促進計画の改定","agenda":"品川区耐震改修促進計画の改定","exchanges":[{"speaker":"田中委員","kind":"質問","question":"１つずつ伺っていきたいのですけれども、２５ページの、「区の助成制度を知らない」という回答が半数近くあったというのがあります。ブロック塀についても、どうやってこれから浸透させていくのかというところを伺えればと思いますが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"今はコロナの影響で昨年度はできませんでしたが、いろいろなイベントの中で、耐震化に関しての事業周知を行ってまいりました。１つは戸別訪問を引き続き、または事業周知については戸別のポスティングという形が１つ考えられるのですが、今後の課題として捉えております。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"今ありましたように戸別のポスティングとかで、ぜひこれからもお知らせをしていっていただきたいと強く要望いたします。私ちょっと勉強不足で、あと、液状化が懸念される箇所が品川区内にあるのかといったところをお知らせほしいと求めました。","respondent":"長尾建築課長","answer":"一般的なお話としては、海側のほうが埋立地とかがやはり多いですので、そちらのほうは内陸側に比べると可能性はあるのかなと考えております。そういったところを確認いただきながら、また、液状化への対策を個別にご検討いただくというところが必要かなと考えております。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"１点だけ。助成してくれるのかなと期待してしまったのですが、先ほど個別対応というふうに言っておられましたけれども、それはどういう状況か尋ねました。","respondent":"長尾建築課長","answer":"直近で言いますと、今年の３月頃に、改めて道路沿いに塀をお持ちのお宅に、啓発の文面と併せて助成制度のチラシを投函しております。今、そういったところは蓄積はしているのですけれども、ちょっと分かりづらいような配布になってしまったところはございました。","id":"exchange-031"},{"speaker":"西本委員","kind":"意見","question":"民地なのでこれはちょっと難しいだろうなと思いますけれども、そういう可能性も含めて検討していただければありがたいなというふうに思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"２点ほど忘れていました。今後対応すべき施設が２棟残っているということなのですけれども、この２棟というのはどこなのでしょうかということをお知らせいただきたいのと、今。","respondent":"長尾建築課長","answer":"荏原第一地域センターにつきましては、武蔵小山駅前に新しく建ちました建物のほうに７月に移転予定ということで、１つは解消予定となっております。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"１つは、それもなくて、今あるものはそのまま残すのですか。どうするのでしょうかというのがちょっと疑問に思ったので、お伺いしてもよろしいか尋ねました。","respondent":"長尾建築課長","answer":"もし使われるということになって、また計画の更新時点の耐震化率の算定のときには、こちらの建物はまたカウントされる形になるかと考えます。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"今後、耐震工事を行って活用していくとか、そういったことでしょうか。何もせず、そのまま置いておくということはないですよね。","respondent":"長尾建築課長","answer":"区有施設としての地域センターは耐震化が図られた建物に移転しますので、それでまずは１つ耐震化が図れたというようなカウントになります。その出た元の建物の耐震化の話につきましては、区有施設ではなくなるので、そのカウントのところからは外れるという状況です。","id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"今の荏原第一地域センターについて。その間、どのような状況があって荏原第一地域センターがここにカウントされてきたのか、説明を求めました。","respondent":"長尾建築課長","answer":"水神児童センターの１棟だけをお伝えしていたのですけれども、もともと耐震化が図られていない建物としてカウントはされておりました。今年の７月に移転するという予定がその時点で立っておりましたので、私がご説明をしていなかったのですけれども。","id":"exchange-036"},{"speaker":"のだて副委員長","kind":"確認","question":"では、確認を１点。区有施設ではなくなるということでしたけれども、そういうものは区有施設ではないということになってしまうのか、そこを伺いたいと思います。","respondent":"長尾建築課長","answer":"所有権のお話と、地域センターのような施設として、区有施設として活用するかというところは切り分けて考えておりますので、この耐震化率の算定の中では、実際に使っている施設を対象としてカウントしている状況になっております。","id":"exchange-037"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"ブロック塀の隣地の対象について、これはぜひ助成の対象にしていただきたいということで、私のほうでも求めておきたいと思います。目標が曖昧というのですか、数値ではなくなってしまったというのはなぜなのかということと、伺いたいと思います。","respondent":"長尾建築課長","answer":"もともと平成２９年度時点の計画の中で、緊急輸送道路沿道建築物は９５％と設定されておりましたので、それをそのまま記載しております。令和７年度までに１００％を達成するというところで、こちらの目標値については、令和２年度の目標をスライドして記載しているところです。","id":"exchange-038"},{"speaker":"のだて副委員長","kind":"質問","question":"どういうことかということを伺いたいのと、この多数の者が利用する一定規模以上の建築物では９５.１％になっておりますが、伺いたいと思います。そして、住宅は、先ほどの説明の中でも木造住宅が大きく前進をしたというお話でしたけれども、前進をした理由を伺いたいと思います。","respondent":"長尾建築課長","answer":"総数としては１,８５６棟ありますので、それで耐震化率が９５.１％というふうに算出されているということになっております。建て替えの助成であるとか、その効果がこういう耐震化率の向上というふうな数値で出てきていると捉えております。","id":"exchange-039"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"２０２５年度までに１００％ということはできないという区のお考えがあるのか、あと、そこの促進もぜひ進めていただきたいというふうに思います。そうすることで耐震化率も上がってくるというふうに思いますので、そうしてほしいと求めましたが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"区の主体的な取り組みの部分になりますので、１００％というような目標値の書き方というのは、なかなか現実的には難しいのかなと感じております。","id":"exchange-040"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"２０２７年度は１００％を目指していくというつもりで取り組んでいくという区のお考えでいいのかというところを確認させてほしいと求めました。１００％を目指していくということになると思いますので、そこの取り組みがあるのかどうか、伺いたいと思います。","respondent":"長尾建築課長","answer":"これは本編の４ページに記載しておりますけれども、これから、今年度策定予定ということになっております。今回、特に木造住宅と緊急輸送道路沿いの耐震化を課題として認識しておりますので、耐震化をさらに進めていきたいと考えております。","id":"exchange-041"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"これまでも制度を拡充してきたということです。そうすると、その後も拡充をしていくということだと思いますので、ぜひ耐震化率１００％を目指して進めていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういう１つのプランをつくって、どこかの機会でちゃんときっちりやりたいと思っているので、そのときはぜひよろしくお願いします。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-04","title":"しながわECOフェスティバル２０２１の開催中止","agenda":"しながわECOフェスティバル２０２１の開催中止","exchanges":[{"speaker":"西本委員","kind":"意見","question":"環境という、エコということをキーワードに何かできないかと、本当に区民の皆さんは考えておられたと思うのです。ですので、けじめはけじめで早くしていただいてもよかったかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"今ご説明いただいた説明会については、机上配付の資料とかも特にはないということですか。口頭だけの説明なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"説明会の実施については、どのように住民の方たちにお知らせをするのか、周知方法についてお伺いします。","respondent":"中道まちづくり立体化担当課長","answer":"今、区としましては、今ご説明した内容を広報しながわ６月１日号に記載をしていくというところで調整をしています。まだ検討中というところで、今回は、まず速報という形で入れさせていただいたです。","id":"exchange-046"},{"speaker":"田中委員","kind":"意見","question":"広報しながわの６月１日号ということなのですけれども、これではちょっと遅いのかなということを思います。この大ホールで５００名ということだったのですけれども、申込みとかが必要なのかとか、そういった点についてもお知らせいただければと思うのですがとの意見を述べました。","respondent":"中道まちづくり立体化担当課長","answer":"区のホームページでの開催案内ですが、区としましては、ホームページに掲載する予定はございません。特に何か事前に申込み等が必要ということは聞いてございません。","id":"exchange-047"},{"speaker":"田中委員","kind":"意見","question":"このリニアの問題も、やっぱり区全体に影響があるので、特定の地域の方たちだけではなく、周知はしてほしいと思います。区のホームページでは広報しないということだったのですけれども、その理由についてお知らせいただけますかとの意見を述べました。","respondent":"中道まちづくり立体化担当課長、塚本委員長","answer":"範囲等をまだ把握はしてございませんが、ＪＲ東海のほうも周知ビラ等を使って周知をしていくというところを聞いてあります。ＪＲ東海が考える対象者にまず照準を絞って… 先ほどご説明にもありましたけれども、説明会が６月８日ということで、本当に生煮えの情報ということがあるのです。ですので、今はあまり確定的なことを答えられないと思いますので、そういうことを踏まえた上でのご質疑でお願いします。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問・要望","question":"ＪＲからのお知らせが先週末ということで、区としても、ちょっと急だったというのはとても分かるのです。ただ、区民にとっては、この情報は積極的に区として出していただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そこの確認と、ＪＲ東海のほうにも要望していただきたいというふうに思いますけれども、いかがでしょうか。関連してくるとは思うのですが、そういったことも説明すべきだと思いますので、そのこともぜひＪＲ東海に要望してほしいと求めました。","respondent":"塚本委員長、中道まちづくり立体化担当課長","answer":"口頭での説明ということであえてしていただいていますので、答えられるところは非常に限られてきてしまうところがあるとは思うのですけれども、答えられる範囲で答えていただければと思います。まだ横穴の工事を開始するということは聞いていないというところでのこの説明会ですので、さらに安全性を高めているというふうに区は認識しています。","id":"exchange-050"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"周知の件ですとか、その辺の回答がなかった。地上への影響についての説明をしてほしいということで、それを要望していただきたいということで、それをご答弁ほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"今、ＪＲ東海も、関連する影響範囲とか、そういったことを踏まえて周知範囲を検討しているということですので、まず、そこの部分について、ＪＲ東海の見解を確認していきたいというふうに考えてあります。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"ＪＲ東海のホームページでも今後は説明会についての記載がされるのか。もしＪＲ東海でもそういった周知をされるのであれば、それを区のホームページでも貼りつけていただきたいなと思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"ＪＲ東海のホームページの活用方法ですが、今までの流れでいきますと、説明会をした後に、説明会で使った資料などをホームページに記載をしています。繰り返しになりますけれども、区のホームページにつきましては、特に周知等という考えは、今のところはございません。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"説明会の開催の周知についても求めてほしいですし、区としても区のホームページでもお知らせをしてほしいと求めました。区も情報が入り次第、きちんと区内全域に情報が届くように、ぜひ積極的な姿勢を取っていただければなということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっとお伺いしたいのですけれども、「羽田空港のこれから」というご意見カードについて、５月１２日に区のホームページで報告されました。拡充をしてほしいなといった方向から質問したいのですが、区に届いたのか、まずお知らせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"なぜ報告されなかったのかというところを疑問に思っていまして、有効に活用してほしいなといった趣旨で、質問したいなと思ったのですけれども。品川区から国に求めて配布されたのか、これまでの経緯について伺いたいのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"区内１３地域での説明会ですとか、情報発信拠点での説明会場ですとか、そうしたところで説明会ごとに作成をして。国として改めて本格運用開始以降もこのご意見カードをもって多くの方のご意見を集めたいということで、まず配置部数についての照会があったです。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問・要望","question":"この１００部を区から求めたのか、ぜひ１００部以上、区として国からいただいて配布すべきだと思います。例えば学校の子どもたちから、ぜひそういったところにも配布されてほしいなと考えるのですが、その辺の拡充についても伺いたいと思います。","respondent":"塚本委員長、鈴木都市計画課長","answer":"学校に関しては教育委員会なので、これは答えられないと思います。踏み込まないようにお願いします。今年の４月末になりますでしょうか、直ちに国のほうに３００部の追加の申し出を行って、図書館に配布をしたです。","id":"exchange-056"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"今回６月１日に説明会をやるということですので、先ほどちょっと説明がありましたけれども、ぜひそういった柔軟な対応をしていただきたい。２回目が３２８名ということですから、できる限り参加できるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"今までの説明会は、南側ゾーン、中央ゾーンとやってまいりました。今、大人数となった場合には、二部制もしくは大きな会場に変更することも視野に入れながら工夫をして開催することとしてまいりたいと考えています。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、説明会のことから外れてしまうのですが、１つだけ要望を言いたいと思います。要望だけ申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"その積極的な説明会を行っていく姿勢は本当に歓迎したいと思います。もうちょっと広く考えた何かを、もし検討されているのであれば、お知らせほしいと求めました。","respondent":"高梨公園課長","answer":"説明会のほか、利用している子どもたち、大人も含めた利用者の声といったところをしっかり吸い上げるといったところをしてまいりました。","id":"exchange-059"},{"speaker":"田中委員","kind":"質問","question":"すみません、ここでいいのか分からないのですけれども、その他の取り扱いについて伺いたいと思います。その他の運用というのですか、取り扱いについて伺いたいのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"田中委員","kind":"確認","question":"申し合わせ確認事項とかで確認をしたのですけれども、特にその他の扱いについて、おかしいなと思ったのです。会議規則のほうということで確認をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"報告事項の中で議論させてほしいというのは、委員長にお願いをするとか、依頼をするという。ちょっと今日は引継ぎも何もできる状況ではないなということを率直に思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"やはり委員の関心のもとで質問ができる機会が設けられているということですので、質問するということは保障していくべきだと私も思います。今回の議題も関心が高い、私自身も興味のあるところでしたので、そこはぜひ保障していただきたいと、私からも意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"石田（秀）委員","kind":"質問","question":"別にその他で質問を止めているわけでも何でもなくて、今日の場合では、ちゃんとその他の扱いの中で、それを踏まえてやってくださいねと。それだけのことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"大沢委員","kind":"意見","question":"比較的そこでも合理的に終わろうという委員長のお考えのもとに委員会は進められているわけだから、そういうことでは私は決してないと思います。さっき田中委員がおっしゃったような遮っているというお考えには、私は当たらないと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"田中委員","kind":"確認","question":"各配布場所にそれぞれ何枚ずつ配布されたのかというのを確認したかったので、もう最後の質問だと言ったので、もう駄目ですとなってしまったのです。答弁が足りなかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"田中委員にぜひお考えいただきたいのは、どこに何枚、委員として判断をしてくださいということを委員長がその前におっしゃっているわけです。それもその他の中でやっているという大前提があるわけですから、そういうことを言っているということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"今回のこの件に関しては、生活者ネットワークとして、担当の部課長にも、その他で取り扱いをするようにということも求めています。きちんと議事録に残すという、公の場に残すということは大事だと思うので、そういった議会となってほしいなという要望も併せて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"今日の流れでいうと、二、三回質疑をやっている状況で、これはもうちょっと深い議論が必要だなと思うわけではないですか。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-06","title":"品川区営自転車等駐車場指定管理者候補者の公募","agenda":"品川区営自転車等駐車場指定管理者候補者の公募","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"指定管理者候補者の選定について伺います。組織、「（６）その他委員長が必要と認める者」というものがありますが、どういった方が選定されたのかということをお知らせいただきたいです。","respondent":"川口交通安全担当課長","answer":"過去の指定管理者の候補者の選定に関して、特に必要と認めて要望したものはございません。","id":"exchange-070"},{"speaker":"田中委員","kind":"確認","question":"４月１９日の総務委員会で指定管理者制度活用に係る基本方針の改定が報告されたのですけれども、今回、この選定委員会の中で、その基本方針改定のものが生かされるのかどうかといったところを確認したいのと、どういったところが生かされるのか、生かす部分についてお知らせほしいと求めました。","respondent":"川口交通安全担当課長","answer":"こちらにつきましては、委員長の防災まちづくり部長をはじめとした各委員を指定して書面審査を実施いたします。これから具体的に人選を行う予定ですけれども、そちらのところも適切に対応してまいる予定です。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"「人的能力」、「十分な能力」と書いてあるのですけれども、何の能力ですか。この選定基準の中で非常に曖昧なので、どういう能力を差しているのかというのをお示しいただけますか。","respondent":"川口交通安全担当課長","answer":"具体的な選定基準のお話です。一定の自転車等駐車場における規模に応じた対応をできるスキルを持っているのかということと、これぐらいの有人配置とか、巡回施設の対応とか。","id":"exchange-072"},{"speaker":"西本委員","kind":"質問","question":"ただ、住民サービスを考えたときには、そういう方々のほうがありがたいわけです。どういうふうに図って、区民サービスに対しての考え方とかというふうに基準をつくっているのか尋ねました。","respondent":"川口交通安全担当課長","answer":"もっと広い意味ですと、具体的に、そういうところのいろいろなサービスの能力的なものも１つは含まれているのであろうというところだと思います。","id":"exchange-073"},{"speaker":"西本委員","kind":"意見","question":"ですので、そこら辺がちゃんと評価できるようなことをぜひお願いしたいと思う。危険性がないようにお願いしたいところがあるので、ぜひ評価の中にはそういうことを重視した形でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"のだて副委員長","kind":"質問","question":"前回、公募をしたときに、最終的に応募したのが１者ということになってしまったのですけれども、そういうことがないようにということで、区としては、この改善点といいますか、取組などがあるのか、伺います。","respondent":"川口交通安全担当課長","answer":"委員ご指摘のとおり、前回は１者でございました。そのような形で、広く公募の期間も設けて、何とか１者にならないような対応をしていきたいというふうに考えております。","id":"exchange-075"}]},{"id":"topic-07","title":"道路通報システムの試行","agenda":"道路通報システムの試行","exchanges":[{"speaker":"田中委員","kind":"質問","question":"予算について伺いたいのと、あと、この通報システムの周知方法について伺いたいのと、あと、損傷や不具合といったことなのですけれども、例えば車椅子やベビーカーでつまずく道路の段差についてなどもここで報告ができる、その対象となっているのかといったところもお知らせほしいと求めました。","respondent":"溝口道路課長","answer":"５月２０日になりますけれども、プレスリリース等をかけて周知を図っていきたいというふうに考えているところです。そういった形が今後の道路行政に生きていくものだというふうに考えておりますので、ぜひ投稿していただければというふうに思っているところです。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問・要望","question":"どうしようかなというところがあったりしたので、ぜひ積極的にそういった報告もしてほしいとお知らせをしてほしいと求めました。しながわパパママ応援アプリのほうでも、ぜひ連携して周知いただければと思うのですが、いかがか尋ねました。","respondent":"溝口道路課長","answer":"今回、試行といいましても、やはり使っていただく、それが一番大事だと考えていますので、様々な形で周知は図れればと考えています。所管課と調整して、周知がかけられるかどうか、その辺は調整をさせていただければというふうに考えているところです。","id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"子育てアプリのほかにも、また障害者福祉課のほうにも、ぜひお伝えいただいて、周知ほしいと求めました。要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"これは、チラシを見ると、「都道」になっているのですけれども、品川区内の全道路という認識でよろしいのでしょうか。そのエリアを説明を求めました。","respondent":"溝口道路課長","answer":"さらに今回、６月１日からは区道もという形になりますので、都道、区道を含めて。国道については、このシステムを使って投稿できるような形に、６月１日からはなるということになっています。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"というふうにちゃんと限定して言わないと、全部入ってきてしまうとちょっとなというふうに思っているのですけれど、区分けの仕方。その情報をどういう流れで、どういう形で、していくのか尋ねました。","respondent":"溝口道路課長","answer":"すぐ対応できないことがありますので、その際は、すぐ連絡を入れてくださいという注意書き等も入った形でのアプリケーションになっております。","id":"exchange-080"},{"speaker":"のだて副委員長","kind":"質問","question":"実際の取り組み状況を伺いたいのと、実際、具体的にはどういう形で検証していくのかというところを伺いたいと思います。","respondent":"溝口道路課長","answer":"ユーザー登録としては１４０人、周知をしっかりかけて利用していただく、そういったことが必要になってくるのだというふうに感じているところです。そういったところも動かしてきていますので、そういったところも含めて総合的に判断しながら、本格導入に入っていきたいです。","id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4320#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":55966,"voices":212}},{"id":"r03-20210517-9","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"文教委員会","time":"午後 １時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"令和３年度新入学学校別増減要因一覧","agenda":"令和３年度新入学学校別増減要因一覧","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１点目が、この理由というのは、区教委はどのように分析しておられるのかというのが１点です。中学校で２３名なのですけれども、おおよそどういう方が指定校変更ということで入ってこられるのか、その内訳や内容などを伺いたいと思います。","respondent":"勝亦学務課長","answer":"指定校変更につきましてお答えいたします。こちらについては、様々な要因によりまして、保護者のお申立てを受けて教育委員会が指定校を変更するものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々な事情で学区というのを変わらなくてはいけない方というのはいると思うのです。そういうやむにやまれぬ事情で指定校変更というので変わらざるを得ない方に対して制度上は担保されているわけですから、推移というか、その辺。","respondent":"勝亦学務課長、有馬庶務課長","answer":"ＰＲを通して、制度の形が違いますので、同じように扱うのは難しいかと考えています。指定校変更の時期ですけれども、この４月５月頃に転居等が出てまいりますので、選択制が終わってからの実施になります。抽選結果は１１月下旬に行いまして、その前の１月から指定校変更は受け付けますけれども、判断はそこから行うです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域との関係もうまくいかなくなるという面もありますし、様々な面から、改めてこれは見直しをすべきということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"区教委としてどのようにその数字を捉えていらっしゃるかを教えていただきたいというのが１点と、小学校、中学校とも転出超過の数字に見えます。だから教育委員会としてどうこうというのはないかもしれませんけれども、今後の予測も含めて、この数字をどう捉えていらっしゃるかを説明を求めました。","respondent":"勝亦学務課長、有馬庶務課長","answer":"選択制の始まる前の指定校変更の考え方ですけれども、それから指定校変更につきましては、考え方としてはまた別のものかと考えています。今年、直近の話としてはそういう状況になっているのかと考えています。ただ、転出される方もいるし、最終的には今日説明した１４.何％というところで数字が落ち着いているということなのだろうと思っています。","id":"exchange-004"},{"speaker":"あべ委員","kind":"意見","question":"制度は若干違いますけれども、指定された学校以外に行きたいという希望というのは、大体人口の２割ぐらいはあるのかと捉えております。今後、３５人学級の話もありますし、人口動向というのはそういう視点からもしっかりと見ていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-02","title":"令和４年度品川区立学校教育職員採用候補者選考日程","agenda":"令和４年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"固有教員の実際の仕事とか配置について伺いたいのですけれども、それと、独自採用の教師の方というのは。あるとしたら、どんな業務なのかとか、そこら辺についてまず伺います。","respondent":"工藤指導課長","answer":"管理職として任用している者は現在１名でございまして、あとは教育につかさどる者ということで配置しています。業務というところではありませんが、やはり区固有教員だけの研修が予定されていて、あるいはそういった体験をするような制度を設けているです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"その独自の研修の特徴というのですか、どんな感じの特徴があるのかというのをお伺いしたいのと、これは全額単費ということでよろしいのでしょうか。それとも何らかの補助金などは少しあるのかということもお伺いします。","respondent":"工藤指導課長","answer":"やはり今年度も６回組む中では、例えば、品川区をより理解するための研修などを中心に行っているところです。費用につきましては、単費で区で負担しているものです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"３５人学級の小学校の全学年前倒しですとか、そのために配置していくということが必要だと私は思うのですけれども、いかがでしょうか。それで、品川でそれを行わない理由というのですか、それは何なのかを改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"他区におきまして、いわゆる固有教員を採用しているという事例については認識をしておりますけれども。固有教員を採用、配置していますので、引き続きその目的に沿って配置していくです。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"それから、管理職の方が１人ということだったのですけれども、私も最近、制度を追い切れていなくて、これは校長にはなれるようになったのですか。２７人の方の年齢構成を説明を求めました。","respondent":"工藤指導課長","answer":"今準備を進めているところでございまして、今、それは具体的に条例改正等ができるよう進めているです。３０歳代が１２名、４０歳代が３名、５０歳代が３名という年齢別の内訳です。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"スケジュール的な見通しというのは何かあるのでしょうか。と同時に、これ、そもそも教員人事権についての議論というのはどこかで行われているのか尋ねました。","respondent":"工藤指導課長","answer":"本年度中にはというところの予定で進んでいるところではありますので、そのようにご了承いただければと存じます。現状あまり進捗がないのですけれども、引き続き都教育委員会に対して、私どもでいえば要望をしていくという段階です。","id":"exchange-010"},{"speaker":"あべ委員","kind":"提案","question":"せめて独自教員の方々には、本来であれば全員に持ってほしいぐらいの思いですが、そこの働きかけと目標について教えてください。そこについてもお考えを説明を求めました。","respondent":"工藤指導課長","answer":"併せて特別支援教育に対する理解に関する研修などを行っていきますので、これまでも特別支援教諭の免許を取得している者もおりますので。指導室課長会等も通じながらも、また、都教育委員会に対しては引き続き働きかけをしていくという段階です。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問","question":"１点目なのですけれども、３番の選考区分（年齢要件）とあるのですけれども、そもそもの受験年齢制限があるというところの理由が分かりましたら、教えていただけますか尋ねました。","respondent":"工藤指導課長","answer":"今回設けさせていただいている一般選考等の要件ですが、いわゆる区の行政職の職員の募集要項と合わせて行っているものです。経験年数等が比較的、現状３１歳になる者というところでかけておりますので、大体大学を卒業して１０年ぐらいというところを勘案しながら定めたです。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問","question":"全国で捉えますと、様々な地域状況があるかと思うのですけれども、年齢の緩和とかをされているようなところがあると考えています。４０代３名、５０代３名ということで、今後どのように考えていくのかというところを教えていただけたらと思います。","respondent":"工藤指導課長","answer":"委員ご指摘のように、年齢要件等を定めつつも、また、優秀な人材を採用するという意味では、私どもも検討を要しているところではあります。採用３名程度というところで、目途の３０名に達した場合には、そういったところで考えたところです。","id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"そういったところでリーダーシップを取れるような優秀な人材というのを積極的に、要件の緩和等も含めて検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"２点ほどお聞きしたいのですが、採用予定人数３名程度ということで、そこら辺はこれからのお考えとかがありましたらお聞かせください。質問させていただきましたが、やはり先ほど特別支援学校の免許を取る方を増やしていってほしいというのも、そこら辺のお考えも説明を求めました。","respondent":"工藤指導課長","answer":"３０名を目途に今進めているですが、その段階でまたさらにその後どうするかというのは検討の課題であると認識しておりますので、まずは３名。その後また引き続き検討をしていきたいと考えています。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"サービスコーナーの概要についてもう少し伺いたいのですけれども、これ、全て図書取次に使うということなのでしょうか。今後ずっとその形で、あの場所の建物が取次センターということなのか尋ねました。","respondent":"吉田品川図書館長","answer":"図書取次施設として引っ越す部分が、約２０平米から４０平米ぐらいのところが図書の取次部門となります。残りの部分につきましては、男女共同参画センターが、工事の間、入る予定で進めているところです。","id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"これは当面、一応、現在では無期限でこの場所を使うという理解でよろしいでしょうか。その確認と、何か基幹的なものをつくっていくとか、そういう考えというのは持っていらっしゃるのか尋ねました。","respondent":"吉田品川図書館長","answer":"今のところ、特にいつまでということはなく、図書取次施設として継続していく予定です。なかなか同じように、もしくはそれ以上の場所を確保するというのは、場所のところからの制約がございまして、難しいものと考えているところです。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問・要望","question":"ここにとまでは言いませんけれども、どこか基幹的なといいますか、中心になるような図書館というのも構想していただきたいと。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"３つなのですけれども、あと、新しい荏原第一地域センターのほうに移れない理由というのを伺いたいというのが２点目です。どこがやるのかというのを、３点お願いします。","respondent":"吉田品川図書館長","answer":"返却につきましては、約３００冊程度扱っているところです。職員と会計年度任用職員のほうで対応しているところなのですが、今後につきましては、業者に委託することで対応を進めてまいります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"これまで区職員と会計年度任用職員でやっていたということですけれども、これが業者に委託ということですが、その辺は少し安易かと思います。ぜひ図書館に詳しい、あるいは利用されている方々の意見も伺いながら、そこら辺は今後検討、研究してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"電子図書館・音楽データベースの導入","agenda":"電子図書館・音楽データベースの導入","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"だけれども、電子化をすると、人気のものなどは複数の方が同時に貸し出して見られるという考え方なのですか。そうすると、それは予算がついていますけれども、この中にそういう権利みたいなのが予算でついたという考え方でいいのか尋ねました。","respondent":"吉田品川図書館長","answer":"１点目の１,０００冊の考え方なのですけれども、Ａという本があった場合、こちらの何冊分の権利を有するかというところがまず問題になります。そういう情報を、例えば品川区史だとか、そういうのを情報として電子化したい。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"意見","question":"そうすると、そこからの印刷はできるのかどうか。音楽なら当然コピーできないのでしょうけれども、その辺がもし分かればとの意見を述べました。","respondent":"吉田品川図書館長","answer":"単純に画面上に表示をして、そこから、場合によってはそこも印刷すらさせない、できないというような制限がかかるものです。は初期導入費が７７万円となっているところです。","id":"exchange-022"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、児童・生徒が使っているｉＰａｄタブレットからというのは使えるのでしょうか。周知方法なのですけれども、例えば、品川区のアプリ、パパママ応援アプリですとか、そういったアプリでのご案内というのはあるのか尋ねました。","respondent":"吉田品川図書館長","answer":"ＩＤとパスワードの交付を受ければ、インターネットに繋げられるｉＰａｄであれば、それは見ることが可能であります。それから、パパママ応援アプリ、これにつきましても、紹介媒体につきましては、使えるものは使ってまいりたいと考えています。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"区民の方々の要望に応えつつ、何かそういうものを、要件という考え方があるのか。何かあったほうがいいだろうと思っているのですが、その辺りの考え方を教えてほしいと求めました。","respondent":"吉田品川図書館長","answer":"実際に今考えているのは、利用されているものを一定程度、目安としては取り組んでまいりたいと考えております。はとりあえず１,０００冊でございまして、まずはそのような利用状況等を鑑みながら、導入状況を考えていければと今は考えているところです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"ナクソスというのは、そういう具体的なサービスがあるかどうかは別としてですけれども、そちらのほうもぜひ目を配ってほしいと求めました。日本の音楽に逆に、特に伝統音楽に接する機会がなかなか少ない中で、そこについてお考えをお伺いします。","respondent":"吉田品川図書館長","answer":"電子のこういうものというのは、図書館を含めまして始まってまだ日が浅いところがありますので、今後、いろいろなサービスが出てくると思います。そういうものがいろいろと出てきたときに、またいろいろなサービスを選んでいければと考えているところです。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうですね。サービスは今後また広げていただきたいのですけれども、１つ、そこだけ誤解のないようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"システム会社、サービス提供会社を介してやられると思うのですけれども、具体的にどういったお名前の会社なのか。全国で比較的に使われているような会社なのかということを、まず１点お伺いします。","respondent":"吉田品川図書館長","answer":"そのうちの３社は、ほぼ大学とかの専門書を中心に扱っているところが３社でございまして、そのうちのこの会社がほぼ独占しているようなところです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"そうした音楽の電子サービスで定評があるというか、それなりの実績があるところなのでしょうか。それをお伺いします。","respondent":"吉田品川図書館長","answer":"この費用が月６万６,０００円の１２か月分、これが予算化されている費用です。２３区ではそのようなところで使っているのと、やはり音楽のデータベースについてのシェアというのも、こちらの会社が広く取っているです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"紙の現状の図書館でも、選書というのは現状ではどういう仕組みで誰が行っているのか。ある意味、そういう選書の仕方の仕組みというのが必要だと思うのですけれども、そこら辺についてのお考えをお伺いします。","respondent":"吉田品川図書館長","answer":"まず１,０００冊で始めたところがありまして、そのためにそこの連携までを含めてシステム化した場合、そこで交付するという形を取った次第です。たしか先月末か今月の頭に発表があったのですけれども、そうなりますと、全館で希望が７００冊ぐらい集まってまいります。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"選書の件ですが、最後にお伺いしたいのは、現状では誰がどういう形で決定するのか。そこら辺、誰がどういう形でいつ決めているのかということだけ最後に説明を求めました。","respondent":"吉田品川図書館長","answer":"指定管理者の中から、このような本の希望があるので入れてほしいというものが上がってまいります。そして、図書館として、これだけの本を入れようというのを、毎月決定しています。","id":"exchange-030"},{"speaker":"芹澤副委員長","kind":"確認","question":"通信が発生するということなのですかという部分の確認と、これから導入というのは、普通のいわゆる本よりも少し安いものになるのですか。半年間は３冊分の権利を買います、その後は１冊分でとか、そのような柔軟な契約になっているのか尋ねました。","respondent":"吉田品川図書館長","answer":"一回ダウンロードしてしまって、そうではなくて、あくまでもインターネットがつながっていない限り見ることができないという仕組みです。","id":"exchange-031"},{"speaker":"芹澤副委員長","kind":"提案","question":"先ほど来館する必要があるということで、これも確認も含めて教えていただきたいのです。身分証とかの確認が必要なので、ＩＤ・パスワード発行にもやはり来館の必要があるのかというのを教えていただきたいのと、読み上げ機能というのはとの意見を述べました。","respondent":"吉田品川図書館長","answer":"３点ご質問いただきまして、そのような対応ができるかどうかは、そちらは今後の研究材料とさせていただければと思います。イメージがついてしまうというような考え方を持たれる作者もいらっしゃるようで、その関係で、読み上げをやっていないものもあります。","id":"exchange-032"}]},{"id":"topic-04","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"認識しているのですけれども、１点伺いたいのは、区教委の子どものオリ・パラ観戦についての最新の方針というのですか。児童・生徒や保護者には、どういう内容をどのように伝えていらっしゃるのか、お伺いしたいと思います。","respondent":"工藤指導課長","answer":"その日程に従って準備をするようにという都教委からの連絡に応じながら、準備を進めているということです。安全・安心に配慮しながら行うというところで学校にお伝えしていますし、学校からは、保護者等へ保護者会などを通じながら説明いただいているです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は一日も早く中止を決断して、五輪そのものの開催の中止も教育委員会として申し入れていただきたいのですが、いかがでしょうか。矛盾しているのではないかと思うのですけれども、いかがか尋ねました。","respondent":"工藤指導課長","answer":"組織委員会も都教育委員会等も進めていると認識していますので、これまで進めてきたオリンピック・パラリンピック教育の集大成という意味では、それに向けて準備を進めていくというところでやっているところです。","id":"exchange-034"}]},{"id":"topic-05","title":"に戻りまして、(5)子ども若者応援フリースペースの移転","agenda":"に戻りまして、(5)子ども若者応援フリースペースの移転","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"やはり物理的に２つの目が必要といいますか、今回、そうしたことは行われたのでしょうかというのが２つ目です。大井町や大崎からも来られるので、そこら辺の施設の案内表示というのは工夫が必要だと思いますが、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"これまで別々の場所で行っていました学習支援事業であるとかを総合的に実施するような形で、学習支援とフリースペースが行ったり来たりであるとか。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、いろいろな経緯があったとはいえ、スタッフ、逆に増えるということなので、やはり福祉は人ですし、そういう意味ではよかったかと思います。下神明駅には少なくとも地図、案内板みたいな、そういった工夫もぜひしていただきたいと改めて要望しまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこら辺、どのように把握されていますでしょうか。これ、大崎駅からが多分一番分かりやすいかと思うのですけれども、なぜか道がつながっていない地図になっていて、一応、確認させてください。","respondent":"廣田子ども育成課長","answer":"まとめてサインについては検討しているので、もう少しお時間をいただければと思います。分かりやすく作ろうという気持ちは十分ありますので。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"そのイメージを、コロナですぐにスタートできないかもしれないというのは踏まえた上で、どういう展開を今後考えていらっしゃるのか。それから、同じ場所になるぐんぐんスクール、キッズドアとのサービス、具体的にどう連携させるイメージを持っているのかを説明を求めました。","respondent":"廣田子ども育成課長","answer":"さらに出口支援ということで、キャリア支援を高めるための仕様を今、検討しているところです。こういう話を定期的に、状況によっては保健センターであるとか教育総合支援センターとの連携会議をつくっていくという、そんな予定をしております。","id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"今後の展開は、通ってくる子どもたちの実態に合わせて、少しずつまたつくっていくのかと思います。それがプレッシャーになり過ぎないように運営してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"お聞きしたいのですけれども、１階から４階のトイレの配置の状況はどのようになっているのでしょうか。説明を求めました。","respondent":"廣田子ども育成課長","answer":"トイレはついているのですけれども、１階にだれでもトイレを造りまして、間口も車椅子でも入れるような形で造っております。基本、各部屋に１つずつトイレがあるという形となっています。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"１階にだれでもトイレで、また、各部屋に１つずつあるということで承知をいたしました。私はトイレに生理用品をぜひ置いてほしいと思っているのですけれども、移転後、どのようになるのかというところを説明を求めました。","respondent":"廣田子ども育成課長","answer":"今のフリースペースで生理用品を置いているかは分からないのですけれども、子ども家庭支援センター等と連携をしながら、必要があれば置くことは可能だと思ってあります。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"もし必要な子がいたらお渡しできるようにはしていますと確認していたところなのですが、しかも今度、ぐんぐんスクールですとか。こちら、ピンポイントでしていただくというところをぜひ検討していただきたいと思うのですけれども、現在のお考えを説明を求めました。","respondent":"廣田子ども育成課長","answer":"状況に合わせて検討していきたいと思います。","id":"exchange-042"}]},{"id":"topic-06","title":"子育て支援団体への助成","agenda":"子育て支援団体への助成","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"新しい支援がいろいろと誕生するところなのですけれども、まず、２番の育成支援助成、これはこれからつくる団体に対する支援に限られるのでしょうか。それから、前後しますけれども、開始時期とあるのは、これは申請受付開始時期という意味でよろしいのか尋ねました。","respondent":"廣田子ども育成課長","answer":"６月１日は申請の受付開始で、６月から分かるようにご案内も予定しております。説明会を求められていて、勉強会以外の場でもご要望があれば説明会を開こうと思っておりまして、順次。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"６月９日の勉強会というのは、クローズドなものなのですか。併せて３番のほうは、これは令和３年度から前期・後期の２回募集とありますけれども、同じ団体が前期・後期２回ということも可能なのか尋ねました。","respondent":"廣田子ども育成課長","answer":"ただ、もし申込みが多くて漏れた場合は、助成金の説明を希望する方には、別途、機会を設けて説明しようと考えています。自主グループ支援のほうなのですけれども、前期の申込みが実は５月でもう終わってしまっていて、後期は９月頃を予定しています。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"それからもう一つ、新規の事業として、今回新規と拡充が出てきているのですけれども、これと反面で、なくなった事業というのはあるのでしょうか。その設計について説明を求めました。","respondent":"廣田子ども育成課長","answer":"どんな出し方なら助成が可能なのかというのを今後検討していくので、新たな支援ができるかどうかというのは、ニーズを把握してからと考えています。これらは、新規に加わったもので、これまでこういう類いのものはなかったので、丸々できたということです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"１番の区内で子育て支援活動を行っている団体というところと、３番のお子さんを持つ保護者が会員となり学習を進めている団体というところですけれども、実際にどのような活動をされているのかというのをご紹介ほしいと求めました。","respondent":"廣田子ども育成課長","answer":"自主グループの支援の学習会については、１万円ぐらいずつ、申し訳ありません。今、実態というのを全部把握していないのでご紹介できなくて残念なのですが、またその回数を重ねていった中でご案内できればと考えています。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問","question":"質問なのですけれども、まず１点目が、特に２番の新規の部分なのですけれども、成果というのはどのようにはかっていく予定になっていますでしょうか。２番目なのですけれども、活動の中で何か相談があったときというのは、今どのように対応している状況か尋ねました。","respondent":"廣田子ども育成課長","answer":"説明会もするのですけれども、子ども家庭支援センターのことが聞きたいとか、勉強会というか。説明会も、何人か集まれば説明会として開くのですけれども、ご案内をする予定です。","id":"exchange-047"},{"speaker":"横山委員","kind":"質問・要望","question":"なかなか中間支援というのですか、行政のほうに来てしまうと、うまく自走していけるような仕組みづくりというのをぜひ今後お願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-07","title":"令和３年４月入園申込状況等","agenda":"令和３年４月入園申込状況等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その理由についてどのように考えているのか伺いたいのと、今回の報告では９９６人ということで減っているのですが、これはなぜなのですか伺いたいと思います。","respondent":"立木保育課長","answer":"その前の年と比べると、今年は若干増となっておりますので、去年が比較的多かったということが一つあるというところはあります。それから、不承諾数が以前ご報告した数字から減っているところですが、こちら、辞退等があった関係で減っているものです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"報道等では、少しでも安心・安全に通えるような環境を整えてほしいと求めましたけれども、いかがでしょうか。それぞれの数を伺いたいと思います。","respondent":"立木保育課長、若生保育支援課長","answer":"今後、情勢等が変わりましたら、きちんと見ながら対応することになるかと思います。現状としては以上です。区としてこの文教委員会でご報告申し上げるに際しては、昨年度と同様の内訳になってしまうのですけれども、取りまとめた数値をご報告します。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"報告や公表のあり方について、事業部として検討したのでしょうか。そこら辺について併せて伺いたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"かつ１園希望者という方がいらっしゃった場合に、１園希望者のほうに計上していたというところでしたが、育休延長希望者のほうが大幅に増えていると。そういった事情です。申込みの段階で今回、令和３年の４月の申込みに当たり、育休を希望しているかどうかというところのチェックをつけていただくようにしました。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこについてきちんと、具体的な不承諾の内訳を、事実をありのままに発表すべきなのではないですかということを求めていたのです。求職活動を休止している人も６６人いらっしゃるということでしたけれども、これは具体的にはどういうケースを指しているのかについても伺います。","respondent":"立木保育課長、若生保育支援課長","answer":"区の中でも、何が一番いいのかということを検討し、今回はこのような形を取らせていただいたです。求職関係で６６名というような形でお答えしましたが、令和３年５月の入園申込みを継続してされなかった方、今回。 国の基準等々の話で、自宅から３０分以内、これは通える範囲でというところがということですが、こちらについては、ご指摘のとおり、そういった基準で算出しているものです。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"改めて、待機児童数５人という報告になったのですけれども、区はこの数字をどう評価しているのか伺いたいと思います。それも伺いたいと思います。","respondent":"若生保育支援課長","answer":"今年度それから来年度の増設予定ですけれども、認証から認可への移行も含めますと、９園開設しています。来年度の令和４年４月の開設、こちらの予定ですけれども、それを含めますと５園を開設していく予定です。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろと伺いましたけれども、２歳児というのは、２４名と３０名の空き枠しかないわけではないですか。最後に質問とご要望ですけれども、今年の９月と来年を合わせて５園増やすということなのですけれども、なぜこれからこんなに増やすのか尋ねました。","respondent":"若生保育支援課長","answer":"立会川のところが１園と、武蔵小山のエリアが１園ということで、期中開設を考えていると。それ以外の３園というのは、今後若干増えていくというところも見込んで、３園というふうに見積もったものです。","id":"exchange-054"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字の数え方について教えていただきたいのですけれども、先ほどのご答弁の中で、３６８名という数字でよろしかったでしょうか。数字の処理の上ではおかしいのではないかと思うのですが、いかがか尋ねました。","respondent":"立木保育課長","answer":"なかなか希望どおりのところに入れず、別の形を選択している方もいらっしゃるということで、それは私どもも認識しております。ただ、これまた一方で事実ですので、そういった形で対策を取らせていただいているです。","id":"exchange-055"},{"speaker":"あべ委員","kind":"意見","question":"Ａ保育園には１個空きがあるわけですけれども、Ｂさん、Ｃさん、Ｄさん、Ｅさんの全員が入れるわけではないですよね。Ａに１個空きがあったら、ＢさんもＣさんもＤさんもＥさんも、空きがあるのに入れなかった人数にカウントされてしまいませんかとの意見を述べました。","respondent":"立木保育課長","answer":"算出している時点では、そのような形で順に算出しているものです。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問・要望","question":"とすると、３６８人以上の定員がこの人数で空きが現在あると考えていいのですか。やはり現実を把握して、そこに何ができるかという発想で取り組んでいただきたいと思うのですが、再度答弁をお願いします。","respondent":"若生保育支援課長","answer":"ほかの自治体ですとか国の考え方というのは、こういったものを使えば、確かにおっしゃるとおり３０分でどこでも通えてしまいます。ですので、そういったところでより現実的な拾い方をしているということは言えると思います。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"片道２ｋｍくらいでしょうか、品川区は縦横４ｋｍ四方ですから、それをぜひやっていただきたいということを要望しまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"横山委員","kind":"質問","question":"８ページの調整指数の１５番のところなのですけれども、プラス１点の加点というところで、それぞれどのような形になっているのでしょうか。今後、詳しい検証というのはされていくのかと思いますが、現時点でどのように評価されているのかというところを説明を求めました。","respondent":"立木保育課長","answer":"全体の約２.３％、加点対象８７名ということで、今回分かったところです。その中でも、多くの方が内定が決まったというところでは、一定程度効果があったと感じております。","id":"exchange-059"},{"speaker":"横山委員","kind":"確認","question":"今、数字を伺いまして、政策の効果がしっかりと出ているというところが確認できたかと考えています。もともと６％程度という予想をされていて、応援できるような形にできたらいいと思いますので、引き続き続けていただけたらと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"時限的なものであるということと、それから、医療関係者の範囲を医師と看護師の２職種ということにしていたと思います。それが１点と、ご要望が多かったのは、その検討というのはされたのか尋ねました。","respondent":"立木保育課長","answer":"やはりまだコロナが落ち着いているとは言えないところがありますので、まだ当面の間は現状で引き続き行くということで考えております。１９９名の方が加点対象になっているというところでは、そういったところも含めまして、今のところは現行を引き続きと考えているところです。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":55716,"voices":155}},{"id":"r03-20210517-5","meetingId":"r03-cm05","date":"2021年5月17日","dateIso":"2021-05-17","committee":"総務委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"そして、その本部会議での話合いも踏まえて、関係機関に東京２０２０大会の開催中止を改めて求めるべきだと思いますが、いかがでしょうか。改めて本部会議の中で、ぜひ話し合っていただいて中止を関係機関に求めるべきだと思いますが、いかがか尋ねました。","respondent":"古巻総務課長","answer":"確認をするような場ですので、特段オリンピック・パラリンピックに対してというような形での検討をしたことはないというふうに認識をしております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"開催中止を求めるべきだと思いますし、区として、つまりは区長が関係機関に開催中止を求めるべきだと強く求めたいと思います。コロナ関係だと聞いたので、この場で伺うのですが、庁舎前に立っている白いテントは何か説明をしてほしいと求めました。","respondent":"古巻総務課長","answer":"電話対応といいましょうか、スムーズな予約に対しての支援、電話回線も十分に確保した上で。順次開設の回数ですとか、会場についてはしっかり拡大をした上でスムーズな接種につながるような対応をしたいというふうに考えています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"２つだけもう一度伺いたいのですけれども、お年寄りが、各自治体で職員が隣について予約をサポートする仕組みが既に２３区でも始まっています。感染拡大が広がる中、東京２０２０大会開催の中止を関係機関に求めることを重ねて、これは要望させてほしいと求めました。","respondent":"古巻総務課長","answer":"ご予約のご支援に関しましては、ご説明はしっかり丁寧にやるとか、できるだけの支援をしていきたいなというような状況です。移動の支援については、タクシー券をというようなお話のところについても十分な検討はしておりませんし、移動については会場の拡大等を含めまして。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"予約を取るときにスムーズに予約が取れるのだろうかというご心配の声が来ていて、恐らく混乱は多少、どうしてもやむを得ないかなと考えています。先ほどそのようなことがないように、区民の皆様に私たちからもお答えできるような情報があるとありがたいのですが、その点についていかがか尋ねました。","respondent":"古巻総務課長","answer":"回線の増強の具体的な数字までは、今持っていないのですけれども、ワクチン接種に関する専用の窓口について設置をしています。専用回線、専用のコールセンターがありますので、お待たせしないような対応をしていきたいというような形で対応させていただきたいと思います。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"先ほど対策本部会議の議論についても質問がありましたけれども、その辺についてどのようになっているのかということを伺いたいと思います。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ区としてはその辺のことも踏まえた、今後に資するような議論と、それの公文書としての作成というものを今から求めておきたいと思います。これについて何かお考えがあれば伺いたいと思います。","respondent":"古巻総務課長","answer":"ご指摘いただいたとおり、今後に活かせるような形でしっかり記録を残し、整理を今後進めていきたいというふうに考えております。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"記録としてきちんと残してほしい、今後に活かしてほしいという意見は、総括質疑のときに所管のほうに求めたのですけれども。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"このように同時に２つ行っていったら、両方予約していいわけですから、私は対応してほしいと求めました。その前に国がしっかりしてほしいということを申し述べて、今後対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ検討してほしいと求めましたので、要望として終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"拡大してくれるというと、この１１会場で２回目もやらなければいけないかという、ちょっと街を歩いて聞いているとそのように感じているのです。何といえばいいのですか、混乱が起きないような周知の仕方という、何かそのような考え方というものはあるのか尋ねました。","respondent":"古巻総務課長","answer":"会場拡大の周知でありますとか、様々なことについては、なるべく早く正確な情報をということになると思います。周知の仕方につきましては、十分に今いただいたご意見を所管にきちんとお伝えしまして、周知が進むような形で段取りをしていきたいなと思います。","id":"exchange-010"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"公明党も度重なる緊急要望をさせていただきまして、荏原地域などでのタクシーによる移動支援等々を要望していますので、どうぞよろしくお願いします。もう１点が、ホームページに出ているのかどうか、ちょっと教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"新妻副委員長","kind":"意見","question":"ふれあい掲示板に載せていますということも含めて、掲示板はここにあるのだということも含めて、ぜひ周知をお願いできればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-02","title":"新庁舎整備に関する検討状況","agenda":"新庁舎整備に関する検討状況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"公募区民ですけれども、何人の応募があって結果４人になったのか、その申込みの件数を伺いたいと思います。前回伺ったときはまだ決まっていないということでありましたが、いよいよ第１回の日程が決まったので、お伺いしたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"２点目のワークショップですが、こちら具体的にはまだ未定という形になっております。新型コロナウイルス感染症の状況を踏まえながら、ワークショップの時期、また対象、方法等を検討してまいります。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"第２回、第３回があって、第４回目が基本構想案のまとめの確認となっています。テーマごとの分科会を設けてしっかりと議論を尽くすという進め方をしていただきたいと、重ねて求めたいと思いますが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"今後状況も踏まえながら検討していって、また基本構想や基本計画に役立たせるタイミングのほうを検討していきたいと考えています。構想段階で５回、計画段階で５回ということで、適切な回数で審議のほうをしていただければと考えています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に要望ですけれども、この委員会で進め方やその詳細については確認されるものだと私も理解しておりますが、十分な議論を保障していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのような方たちの中から、もう一人でも２人でも、別に参加を求めたらどうなのかなと思います。いつもあったと思うのですけれども、もしくは公募区民の中にも当事者の方いらっしゃったらいいなと思うのですが、その辺についていかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"まずは庁舎機能検討を昨年度やりましたので、そちらのほうをテーマに、ワークショップ等でもやらせていただくということは考えております。こういったところはちょっとまだ未定ではありますけれども、そういったところも含めて検討していきたいとは思っております。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"きちんと区から見えた形で、この人に任せておけば大丈夫というような人がいるのか、その辺については確認されたのでしょうか。そちらが当然主たる目的だと思いますので、もう少しきちんとスケジュールも見直してほしいと求めましたが、その点についていかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"今検討業務の支援業者との事前の打合せということで詰めておりまして、その内容によって支援の仕方等も今後調整をしていくという形になっております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ検討してほしいと求めました。もし何かご答弁いただけるようでしたら伺います。","respondent":"榎本総務部長","answer":"機能の検討をしてきたことに対しての説明を行い意見を求めた上で、それを基本構想のほうに活かしていきたいということが第１段階かと認識しています。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"私たちも説明会を求めてまいりましたけれども、その答申についてご説明の予定があったということは大変評価をしたいと思います。ぜひそのように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"そのような職場環境をつくっていただきたいということと、相談しやすい、そのような構造にしてほしい。そして長寿命化に対応できるような、区民のシンボルになるような建物、構造にしていただければありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいことは、この総務委員会に報告をしてほしいと求めましたが、これは質問したいと思います。十分な議論を保障して、回数についても十分に保障することを改めて求めたいと思いますが、最後にいかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"時期等は検討しておりまして未定ですけれども、パブリックコメント中に開催をしていくというような考え方もありますので、今後詰めてまいります。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり十分に課題も抽出し、それに見合った庁舎にするのであれば、時間をかけて議論すべきだと重ねて求めたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"東京都議会議員選挙（品川区選挙区）における執行要領","agenda":"東京都議会議員選挙（品川区選挙区）における執行要領","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"２つお伺いしたいのですけれども、できない理由について、どのような事情があったのかご説明ほしいと求めました。１日も早く配布が終わる、そのような体制を組んでほしいと求めましたが、この点もいかがか尋ねました。","respondent":"齋藤選挙管理委員会事務局長","answer":"３日間でも場所をお貸しすると、やはり密になるということでございまして、お断りをされたです。７月３日までと、可能な限り全戸に早めに配布ということで、今回お願いしたいと考えています。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2196#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25058,"voices":68}},{"id":"r03-20210520-14","meetingId":"r03-cm05","date":"2021年5月20日","dateIso":"2021-05-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/444693?Template=document&Id=6108#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":2153,"voices":11}},{"id":"r03-20210521-18","meetingId":"r03-cm05","date":"2021年5月21日","dateIso":"2021-05-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時２７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"日本ブラインドサッカー協会とのパートナーシップ協定再締結","agenda":"日本ブラインドサッカー協会とのパートナーシップ協定再締結","exchanges":[{"speaker":"田中委員","kind":"確認","question":"１点確認したいのですけれども、近隣からのお声があって、場所を移動せざるを得なくなったという経緯があったと思います。そういった障害者理解の促進が本当に十分に図れるようにしていってほしいということを強く思うのですが、今、何か考えていること。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"オンラインを通じてやるということは、今、引き続きやっているところです。いろいろな形を取りながら、さらに混ざり合う社会ができるというのが理想だというのはお互いの思いですので、その形で進めていきたいと考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"「このような取り組みを全国に拡大したい」と理事長が語られたということですが、どれくらいあるのかというのを、もしご存じでしたら教えてください。そういったところと何らかの情報交換とか経験交流はされていらっしゃるのか、そちらも併せてお伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"担当課長会等でお会いしたときには、何かできればいいですねというような、その程度の話はしています。ブラインドサッカー協会は、企業のいろいろなところと一緒に連携して、いろいろなプログラム展開ということはやっているように聞いております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういった障害者スポーツを通しての相互理解、障害そのものの理解の促進というのは非常に重要だと思いますので、様々な横の連携なども、情報交換など、経験交流などもしながら、いろいろ地域にさらに広げていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区は特別共催ということなのですけれども、特別共催の品川区としてはどのような役割を担っているのでしょうかというのが１点です。選手自身と、大会関係者、あと一部招待される観客の方もいらっしゃったと思いますけれども、それぞれについて伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"一定程度の期間、外部との交流はシャットダウンするということで、そういう方しか選手との交流やピッチに下りることはできないようになっております。","id":"exchange-004"}]},{"id":"topic-03","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"ただ、理由は先ほど伺いました。伺ったのですけれども、やはりこれから区に求めていくといった中で、このような文言が書かれているのはどうなのかと違和感を持ちますということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"感染対策と両立できないことはもう明らかなのですから、区としてもそういうものとして受け止めていただきたいと考えています。そういうことで、あえて反対するものではないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"(4)のところの「積極的に」の部分を、生活者ネットワークとしては削除してもいいのではないかという修正案を出させていただきました。なくても文章が通じるので、これに関しては、生活者ネットワークの修正案が反映されなかった理由についてお知らせいただけますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"現にこのときの判断であれば、それは積極的にやっていこうという判断がこの会でもありましたので、一応文章はこのままです。ですから、そこはしっかり正副委員長でも最大限のことをさせていただいたつもりなので、そこはご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"積極的に求める委員の意見とともに、今、区としては感染症に関する情報発信だといった区とのやり取りも議事録の中でも確認できていましたし。でも今回このように案を示されたということで、特に反対をするわけではないですが、意見はさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/343398?Template=document&Id=6594#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":8846,"voices":31}},{"id":"r03-20210526-10","meetingId":"r03-cm05","date":"2021年5月26日","dateIso":"2021-05-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"自民・無所属・子ども未来を見解の違いから退会いたしまして、品川区議会自民党へ入会させていただきたいと考えております。私が委員としてここにいるのは違うと思いますので、これにて退出します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"常任・議運・特別委員会の構成","agenda":"常任・議運・特別委員会の構成","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"確認ですが、この委員会については、会派は変わるので、第３会派はいらっしゃらないと。文教委員会の中にはいらっしゃらないということでよろしいですね。","respondent":"工藤区議会事務局長","answer":"名簿の順番につきましては、後で入れ替えしますが、当該委員につきましては変更ございません。以上です。","id":"exchange-002"}]},{"id":"topic-03","title":"附属機関等・各種団体評議員における議会選出委員","agenda":"附属機関等・各種団体評議員における議会選出委員","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"私どもはご辞退するというような形を取らせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"こんの委員","kind":"意見","question":"私どもからは、たけうち委員をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"後ほど可及的速やかに報告をさせていただきたいと考えています。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"若林副委員長","kind":"確認","question":"本日は、前回、候補者が２名示されましたので、議案を提示するにあたり、各候補者の議案の提出者になるかどうか。各議案への態度を確認したいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"前回の議運でお話しさせていただきましたが、石田秀男議員で進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"こんの委員","kind":"意見","question":"会派としても検討いたしまして、石田秀男議員というところでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"皆様のご意見を伺いまして、この場では石田秀男議員が多数ということを受け止めさせていただきました。今日の議論も踏まえまして、議案には反対の立場をもって、石田ちひろ議員の議案は提出しないということでご対応ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"若林副委員長","kind":"確認","question":"先ほど各会派の態度を確認いたしましたので、本案については、共産党などを除く議会運営委員会のメンバーを提出者とすることでよろしいでしょうか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林副委員長","kind":"提案","question":"本議案の提案説明は、私からでよろしいでしょうか。〔「はい」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"若林副委員長","kind":"質問","question":"資料No.５－２の日程第１０の議案説明者に若林の記入と、採決については起立採決の記入をお願いします。","respondent":"工藤区議会事務局長","answer":"その後、日程第２、第３の両特別委員会の設置動議について、こちらを２件一括議題に供しまして、簡易採決の予定となっております。こちらの設置動議につきましては、本会議では２件一括議題で、簡易採決の予定という流れになってあります。","id":"exchange-012"}]},{"id":"topic-04","title":"議事日程(1)、追加議事日程および追加議事日程(2)","agenda":"議事日程(1)、追加議事日程および追加議事日程(2)","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"５月７日に役職届等を出すということで、一応一定のルールの下に出され、それ以降、様々な事情があって変更せざるを得ない。会派として今回の議案について検討しました結果、会派から出されたそうしたものについて進めるということから、賛成としたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ついては、横山議員の議案に賛成したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは受け止めさせてほしいと求めましたが、この間の流れというのは、やはり改善すべきところは改善していかなければいけないなと。態度といたしましては、第３会派ということで反対をするものではありませんので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"これはやはり品川区の財政に対して監査をするということですから、送り出すということが、私は建前だと思います。今この場においてどうするということについて、もう少し熟慮させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":15913,"voices":104}},{"id":"r03-20210527-6","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"区民委員会","time":"午前１０時０９分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"マイナンバーについてですけれども、マイナンバーカード申請件数の激増ということで、窓口を増やすということですけれども、激増の理由、その状況について、今、交付がどれぐらい進んでいて、申請がどれぐらいあるのかというのと、あと、増えている理由が何かというのを伺いたいと思います。","respondent":"木村戸籍住民課長","answer":"それから、交付件数につきましては、３０％強という形でございまして、区民の３人に１人の方が既にカードをお持ちになっていると。国のほうで昨年末から３月にかけまして、当時は国民の約８割でしたけれども、これらの要因が考えられると。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今までがどういうもので、それがどうなるのか。配送管理の負荷を軽減できるということは、何をどうするとそうなるのかというのを詳しく教えてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"それも容易に、キャンセルをしたらそこへすぐ予約が入れられるようにという形で、すぐ対応ができるような形で考えています。そういうシームレスでつながることで、いわゆる交付に至るまでの時間短縮が図れるというような意味合いでございまして、導入を検討しています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"区内中小店舗でということなので、キャッシュレス決済のシステムがある店舗というのは、どれぐらいあるのでしょうか。結構あるのか、そこら辺を伺いたい。","respondent":"遠藤商業・ものづくり課長","answer":"今回やるに当たって、いろいろ業者からお話を伺ったり、検討させていただいたところで、どこの会社というのはお話しできないのですが、５,０００店舗あるというふうに、こちらのほうでは聞いているところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、その５,０００店舗というのは、区内中小店舗の大体何％ぐらいになるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"見込みとしては、紙のほうの商店街のプレミアムのほうが２,０００店舗ですので、それよりは必ず多い数字にはなるのかと思っているところです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"キャッシュレス決済ができるシステム、機器というのですか。そこについて伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"例えば、今のところ、ＱＲコードがいいかと思っているところです。恐らくＱＲコードでと考えていますが、もう少し様子を見て、場合によっては違う方法でという形も余地を残しています。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"住民生活サポート事業２件ということで、もしこれを超えてきた場合はどうなるのかというのと、新たに始めるということなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"それを見込んで一応１５件という形でしていますので、もしオーバーした場合も、全ての商店街に助成をさせていただければと考えているところです。例えば、一回物品などを買われた場合には、恐らくそのまま引き続き毎年やられているような商店街もあるかと認識しています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"地域清掃事業とか、交通マナー向上事業というのが例で書かれていますけれども、こういうことを商店街は今までやっていなかったのですか。新たに始めなくてはいけないというか、新たに始める商店街が多いのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街のいろいろ考えもあろうかと思いますけれども、特にお金を使わなくてもやっているというのが実情かと考えています。申請はなかったのですが、おととしも２件ほど申請をいただいておりまして、ぜひ活用していただければというところの助成金と考えているものです。","id":"exchange-007"},{"speaker":"松本委員","kind":"意見","question":"マイナンバーのところに絡みまして、会計年度任用職員増員ということで、１０名、結構大きく増員になっているのだけれども、これ、たまたまここに載っていて、これよりも前と人数がそんなに変わらないのか、純増なのかというところをお願いいたしますとの意見を述べました。","respondent":"木村戸籍住民課長","answer":"基本的には純増という形です。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"これもやはりこれまでよりも交付の規模を拡大するからという趣旨と受け止めてよろしいか尋ねました。","respondent":"木村戸籍住民課長","answer":"その趣旨です。","id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"交付の申請だけで５０％というのは、それはやむを得ないというか、必要な経費かと思います。東京都の１００％負担でやっていた、まだ理解できていない部分があるので、お願いいたしますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街に対しての助成という形で、消耗品だとか、いろいろアピールする費用が１０分の１０という形でたしか出ていたかと考えています。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"都が１００％やっていたものを、助成率で３分の１は区が負担するとなっていますから、その辺りはどのようなやり取りがあったのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"区としてはどうしようかと、別の部分の支援でと考えたところなのですが、東京都のほうでこういう補助メニューを用意しましたと。やり遅れたとか、追加の部分ということで、こういうスキームでもある程度しようがないのかと思っているところです。","id":"exchange-011"},{"speaker":"松本委員","kind":"意見","question":"厚労省とかＷＨＯでは、効果があるかと言われたら、明確にあるとは言えないと。物によっては、消毒液等の中に空間除菌に関するものが含まれ得るのかどうか、お願いいたしますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"二重の審査になりますけれども、そういう中で、効果の高いものと。効果が認められないものは難しいかです。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"マイナンバーカード交付強化について、土曜交付窓口開設と、荏原第一地域センター、目黒行政サービスコーナーが増えることで、どのぐらいの件数が処理できるようになるのかという数を教えていただきたいので、お願いします。","respondent":"木村戸籍住民課長","answer":"現在は月間で約６,０００件交付の能力、これが土曜日と２か所拡大して約１万２,０００件という、倍の交付能力という形で運用してまいりたいと考えております。","id":"exchange-013"},{"speaker":"大倉委員","kind":"確認","question":"今まで使っていたところもまた使えるのかという確認と、総額１０万円だと割り切れないとかという大きいところもあったりとか、その点について説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"それから、１０万円の根拠ですけれども、消耗品ですので、あまり高額にといいますか、貯めておいてもというところがあるのかと考えております。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"いろいろあるではないですか。１社に決めていくのか、それとも何社か選んでやられるのか、どのような検討がされているのでしょうかというところを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"この還元額５億円を有効に使うという観点から、一応１社でどこかの事業者でやらせていただければと考えているところです。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"１社でやると、その１社のＱＲコード決済ができる何かアプリとかをダウンロードして使っていくという認識でいいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そのように考えてあります。","id":"exchange-016"},{"speaker":"大倉委員","kind":"意見","question":"そのアプリを片っ端からダウンロードして、１人で何回も使えてしまうというところもあるのかという懸念はあったので、１社ということで分かりました。周知をしっかりしていただいて、多くの方が利用されるような取組をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"１点目が、大倉委員から質問がありましたが、１社とのご答弁でした。それを複数にできない理由というのが、何かあるのかどうかをまず伺いたいのですが。","respondent":"遠藤商業・ものづくり課長","answer":"複数社あったほうが、確かに使う側は利便性があるかという部分があろうかと思います。どうしても５億円がうまく活用できないとか、他区の状況などをいろいろ検討させていただいた結果、まず１社でやらせていただければと考えています。","id":"exchange-018"},{"speaker":"くにば委員","kind":"質問","question":"５,０００店と先ほどおっしゃっていましたけれども、基本的にどの事業者、どの店舗でもできると思うのです。これは５,０００店というところと関係なく、５,０００店という縛りであるとか、そこを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"結果として、５,０００店よりは、５％とか１０％とかそのような形で増えるのかというところがあると考えています。導入に関して新たなものをいろいろと設置しなければいけないというところがありますので、今のところ、ＱＲコードを考えているところです。","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"ただ、それを１回で購入すると、上限２,０００円しかつかないから、この商品、５回に分けてレジで打ってという。逆算すると、６,０００円を５回に分けて買うみたいな形で、同一店舗で同じ日に５回買物をしても問題がないというような説明になるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"私どもがお話ししている事業者ですと、それができてしまうというところがありますので、期間内の上限が１万円という形で設定させていただいて、両方の部分で歯止めをかけて、１人頭につきましてここまでという形で考えているところです。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問・要望","question":"では、今おっしゃった中では、結局は１店舗で同じ日に５回買物をしても問題がないという形の説明はあらかじめしておくのでしょうか。今おっしゃった形で、結局できてしまうという部分、ここをどこまで制限をするのかというのを教えていただきたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"できませんという形で案内しても、その辺は利用者の方にそういう趣旨はご理解いただければというところで、事業者にはそういう形で案内するようになると思ってあります。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問","question":"実施の枠組みづくりに慎重に、じっくり時間をかけて詰めていっていただいて、また委員会のほうで途中で報告いただけたらと思います。１人当たり最大幾らまで申込みができるという形で書いてあったと思うのですけれども、１人当たりのマックスが書いていなかったのですが、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"まだ商店街連合会と詰めているところではないのですが、これまで１０冊までという形でやっております。今回、１０％の商品券については８冊までという形になりますが、恐らくは８冊か１０冊かという形になろうかと思っているところです。","id":"exchange-022"},{"speaker":"くにば委員","kind":"質問","question":"もしまた８月、実際に販売期間が９月下旬または１０月上旬、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"販売時の並びの列とかを指定をする、販売を指定するような形で、春のほうはこのまま引き続き実施をするというところで考えているところです。今回のスキームの中で実施させていただいて、あるいは別の方法、いろいろな形で検討させていただければです。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"あくまで販売がもう少し後の時期になります、延期になります、まだ未定ですという段階なのでしょうか。そこに対して細かい周知であるとか、説明の部分とか、もう一度伺いたいのですが。","respondent":"遠藤商業・ものづくり課長","answer":"当初、５月の中旬にやる形だったのが、緊急事態宣言で少し遅れますというようなご案内をさせていただいて、恐らく６月に販売を開始する形になります。そちらをご確認いただければ、そういうことだったのかということで、ご判断いただければと思っているところです。","id":"exchange-024"},{"speaker":"くにば委員","kind":"意見","question":"ということは、実際、春のプレミアム分１０％申し込んだ人も、まだ結局、お金を払っていません。次、２０％のものを申し込んだほうがいいということになるような気がするのですけれども、そこに関して何か事前に検討というのはとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"今回、春のご購入を１か月ずらすことによって、使う有効期限、こちらも１か月延ばすような形で考えています。２０％のほうがまた抽せんという形になり、１０％のほうはできれば１０％で夏の期間使っていただいて、私どもは考えているところです。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"もしくはキャンセルをしたらどうなるかであるとか、分かりやすく伝えていただけるようにお願いしたいと思うのが、要望で終わります。アクリル板をつけていない事業者のところに、つけてくださいとか、区のほうからどれぐらい事業者に言っていっているのか伺いたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、そういう部分で、個店につきましては、新型コロナウイルス対応の、個店宛ての２０万円の助成という部分をやらせていただいたところです。商店街は比較的自由に使うことができますので、そういう部分での活用を考えているところです。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問","question":"ちなみにカラーコーンというのは、ガイドラインの中に、こういった人を整理するためのカラーコーンは含まれますみたいなことで例示されているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"ガイドラインのほうを詳しく確認していないところですけれども、今回のこちらの助成金の要綱の中に、そういう部分での具体的な例として、カラーコーンみたいなものも入っているので、恐らく入っているのかと思っているところです。","id":"exchange-027"},{"speaker":"くにば委員","kind":"質問・要望","question":"どういうものが実際使えますというのは、これはオーケーなのだというのでどんどん活用していただけると思うので、具体的な例示というのをたくさんしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"小芝委員","kind":"確認","question":"確認というか、お聞きしたいのですけれども、周知をどのようにされているのか。だから、この周知方法がどのようにされているのか疑問に思いましたので、お聞きします。","respondent":"遠藤商業・ものづくり課長","answer":"その方に対してこれをお送りして、商店街の中で周知なり、あるいは使う使わないみたいな判断をしていただくという形を取っているところであります。ですので、個別の店舗に送るということは今のところないという形です。","id":"exchange-029"},{"speaker":"小芝委員","kind":"質問・要望","question":"その辺ですごく区役所との交渉ではないですけれども、何度もやり取りをして、ようやく助成金がおりたと。その辺、ぜひ今回の事業について対応していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そうすると、丁寧に説明させていただいたところではあるのですけれども、なかなかうまくいかない部分が正直あったというのは事実です。そういう部分では、分からない部分は当然丁寧に説明するところですけれども、トラブルみたいなものは少ないのかと考えているところです。","id":"exchange-030"},{"speaker":"小芝委員","kind":"質問・要望","question":"このコロナの状況でなかなかお店も開けないという大変厳しい状況ですので、ぜひともきめ細かにフォローしていただきたいと強くお願いしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"時期がこれだけの期間で、もう２０％に変わってしまったのですか。やはり２０％、１年２年たっていないではないか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"前々回の区民委員会のところで、１０％のご説明をさせていただいたところです。キャッシュレスが３０％で並行して進めていく中で、紙のほうが１０％ということに対してどうですかという話をさせていただいたところがあったのです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"消費者としては、今さら変えられないといっても、２０％のほうがいいではないですか。今回コロナ禍ということで、本当に特別なことになっていますので、やはりこのプレミアム率というのをもっと考えていっていただきたいと思うのです。","respondent":"遠藤商業・ものづくり課長","answer":"昨年３０％でやったときに、還元額が５億円という形になりますので、緊急経済対策としてはしっかり機能するのではないかと考えているところです。１０％の部分につきましても、春の１０％という形で、検討させていただこうと考えております。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３度目の緊急事態宣言が延長されて、やはり中小店舗が緊急事態宣言下で一番必要としているのは、直接支援なのではないかと思うのです。ぜひ国や都にも求めていただいて、こうした直接支援を強力的に進めていくということをしていただきたいと思うのですが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"区の財源というところで直接支援をやるとなると、昨年ですと、家賃支援の上乗せ助成という形での対応をさせていただいたところです。現行におきましては、あるいは昨年度の補正予算で用意させていただいた新型コロナウイルス感染症対応特別助成など。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ求めたいですし、事業主は、自宅の家賃の支援策である住居確保給付金の対象者ではないのです。そこはぜひ拡大、充実、復活等々していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"つる副委員長","kind":"提案","question":"まさにこの生活応援事業を活用して区内経済の活性化を図るべきだということで提案をさせていただいて、推進をしていきたいと考えています。分母が大体５,０００店舗ぐらいあって、それをやるということはできるという理解で私はいたのですけれども、その辺を確認させてくださいとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"この２つ、一体のものとして考えているところですので、いろいろ試行錯誤させていただければと思っているところです。店舗宛ての説明会といいますか、新規の加入についての説明会みたいなもの、広く周知したいと考えております。","id":"exchange-036"},{"speaker":"つる副委員長","kind":"質問・要望","question":"その使用期限をどう考えるかというのも併せて伺いたいのと、その確認と、若干かぶりますよね。キャッシュレスが１１月頃となっているので、その１か月というところ、その辺のところをどのようにやっていくかということを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"恐らく店舗のところにも貼り出すような形で今考えているようですので、混乱のないように延びた部分については対応できればと思っているところです。１０％の券と２０％の券と、店舗側が困ることのないよう、トラブルが起きないよう進めていければと考えています。","id":"exchange-037"},{"speaker":"つる副委員長","kind":"質問・要望","question":"秋以降分として使う、いろいろ柄が違うのかどうかあれですけれども、その辺は混乱のないようにやってほしいと求めました。今回のように積極的に活用していくという区の姿勢を、また今後も示してほしいと求めましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たち共産党は、安全性が確保されていない下での推進はすべきでないと反対をしてきているものですけれども、在留カードとの一体化も進めると。そして、さらに拡充、拡大していっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2898#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":29422,"voices":90}},{"id":"r03-20210527-7","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"厚生委員会","time":"午前１０時０９分～午前１１時１２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今後も、こういう方針で今後もやっていくように考えられているという理解でよろしいのでしょうかというのが、第１点です。せっかく補正予算を組むのですから、東京都がやっているように週１回の実施とすればよかったのではないかと、その辺は検討されたのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"それから２点目の、東京都が実施する週１回の検査というのは、こちらと一律に比較をして検査頻度を論じるのはいかがなのかなと考えています。週１回の検査が正直、そういった声も大切にしながら、今後検討していくものと考えております。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"莫大な額がかかるわけではないのですから、タクシー代も品川区内での話ですから、伺いたいと思います。会場を１つでも増やすという観点から、そういうご検討はなされなかったのか、その点も同時に伺っておきたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２点目の、ご家庭に打ちに行く形でできないかということで、これも併せて医師会の皆様と調整を進めているところです。以前の厚生委員会でもご説明していますが、会場の確保は引き続き努めておりますので、ご承知おきいただければと考えております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"電話で予約を申し込んでいる７５歳以上の方にとっては、もう空いていないから大井競馬場を予約しろと言われたように受け取ってしまうわけです。このようにしたらいいのですよという説明、情報の提供というのは、何とかできないものか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"こちらも会場の確保に毎日努めて、医師会と調整を進めておりますので、そういったことが今後も増えていくであろうとは思います。随時させていただきたいと考えておりますが、全くこちらで開示ができる状態ではなかったので、その辺りはご容赦いただければと考えております。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"タクシーのところについてお伺いしたいのですけれども、私どもは要望をさせていただいていましたので、こういう制度をされるということなのですが。タクシーがなかなか通っていないところもあるということで、そこまでお願いができないかというところなのですが、まずはお伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その辺りは会場ごとの対応ということで、運営会社、委託会社にも話は進めさせていただいているところです。お迎えにつきましては、今いただいたご意見を基に、急いで検討させていただきたいと考えております。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう少し教えていただけることが、そのことについて教えていただきたいことが一つと、品川医師会がいつ開くのですかということで。補正とかとずれてしまうかもしれないですけれども、教えていただける範囲で、どれぐらい調整が進んでいるのか教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"医師会館については、調整を進めております。６月中に何とか開けるように、６月中ということで、決まりましたらご報告させていただきたいと思います。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"委員長がおっしゃったようなことも伺っていますし、地域ごとのことについても、ぜひよろしくお願いします。それともまとめてお考えになっているのか、この辺りのお考えについて、いただける範囲で教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"早く打てるよとおっしゃって、少し前倒しで進める病院も幾つかあるかとは思いますけれども、その辺りも含めて現在調整をしております。基本的には、一括してというか、ある程度まとめて公表できるような形で準備を進めているところです。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ要望なのですが、そういう先行事例を見ていただいて、一番混乱のない方法でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２週間に一遍ということなのか、その確認をお願いしたいと思います。介護サービス２,４００人となっているのですけれども、介護サービスの中で対象とならないサービスというのがあるのかについても伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"ただ、東京都もこの先について、全く予定がないということではないと。ですので、そういった意味で、人数は少し余裕を見たというか、十分な人数を今回、要求させていただいているところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域密着型の２９ベッド以下の特養ホーム以外の特養ホームとか、既にＰＣＲ検査を行っていると思うのですけれども、把握をされているのでしょうか。その点をまず説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"こちらも東京都の補助事業で、都のスキームに従って行われているものですので、こちらは特段、把握はしておりません。ただ、東京都がこれをやるとなったときに、積極的にこれを活用するようにという要請は、各施設・事業所に出させていただいているところです。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、東京都にも求めてほしいと求めましたし、区としても積極的に行っていただくように要望をしておきたいと思います。もしならない場合は、どう考えられているのか、その点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"ご不安の声はご家族の方からお聞きしておりましたが、現実問題として、こういった事例というのはございませんでした。福栄会からは、児童も受け入れるという答えをいただいているのですけれども、事業者と協議していきたいと考えています。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この５,０００人という方は、障害者の対象をどういう形で５,０００人という人数にしているのかについて、伺いたいと思います。そういう支援とか、それから障害者の相談支援事業所などとの連携というのが、どうなっているのかということについても伺いたいと思います。","respondent":"松山障害者福祉課長、宮尾高齢者福祉課長","answer":"１点目の、障害者の対象者の考え方です。それと愛の手帳１・２度の方、あとは精神１級の方と、見込んです。 私から、介護保険サービスとの関係についてお答えします。この商品券の事業の形ができて、お伝えするようになったところで… 地域拠点相談支援センターと連絡を取りながら、対応を円滑にしていくようにということで、協議をしている段階です。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"視覚障害３級の方は対象になっていないのですけれども、そこに視覚障害３級の方がプラスされたという形で考えればいいということでしょうか。精神の方も。","respondent":"松山障害者福祉課長","answer":"視覚障害者の３級の方、あるいは精神の１級の方が加わったという形ですが、新たにこういう方を想定したものです。高齢者や精神の方と重複している方もいらっしゃいますので、数字としては５,０００人ということで、大きく概算で見込んでいる次第です。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"接種がいつから始まるのか教えていただきたいのと、そういう情報をすごく地域の方が求めていまして、お聞かせほしいと求めました。他区の状況で伺っているのですけれども、どういう形でそういう困難をなくすような手だてを考えられているのか、その点についても伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もともと当初の予定では、次のワクチンの供給が入ってきたらと見込んで計画を立てていまして、区の方針を立てて進めてまいりました。説明会を行いまして、どのように皆様に公表していくかということを決めていく予定になっておりますので、調整中です。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"６月下旬からはうちの診療所でも始めたいと思っているとか、おおよそ６月の下旬から、その辺についてもお聞かせほしいと求めました。国ではまだしっかりとできていないということで伺ったのですけれども、または、その点についても併せて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"確認","question":"ほかの委員の方からも質問があったのですが、具体的にどういうところに周知して、説明できるような体制はどのようにするのかということの確認です。やれますという回答をしたとお聞きしているのですが、現在の状況から、国の回答との感じはどういう感じになっているのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１点目の周知につきましては、ホームページ等々で、まずは周知を進めていく準備を進めているところです。６月も順次予約枠を空けられるような、現時点では７月末の完了を目指して、各種調整を進めさせていただいているところです。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"何度も繰り返しますけれども、いいことをされているわけですから、ご本人に伝わるようにしてください。時間外勤務も多いと思いますが、ぜひ実現するように進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"１点だけ、すみません。今後のことですので、ご要望で終わりたいと思うのですが、ご検討いただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19916,"voices":57}},{"id":"r03-20210527-9","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"文教委員会","time":"午前１０時０９分～午前１１時４３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"第３２号議案、専決処分の承認を求めること","agenda":"第３２号議案、専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今のところ何名に支給したのでしょうかというのと、具体的にはチラシですとかポスターとか、いわゆるどのような工夫をしたのかというのを教えてほしいと求めました。","respondent":"伊東子育て応援課長","answer":"それと、５月２６日に申請を受けての支給ということですけれども、そちらについては２２世帯、３７名分の支給です。５月６日の時点で案内を送付ということですけれども、資格がありそうだという方に対しては、その中でダイレクトにご案内をしたという状況です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"数はお伺いしましたけれども、２,３３６名にはまだ届かないということですが、これから増えていくという理解でよろしいのでしょうか。私が伺ったのは、去年の実績にある方に送付ということは前回も伺いましたけれども、そういうのはやっていないということなのか尋ねました。","respondent":"伊東子育て応援課長","answer":"これからの見込みですけれども、当然ながら家計急変等で申請ができるということで、数値的には上がってくるという見込みになっております。そういう意味では当然庁内の連携ということで情報提供はしていますが、これから申請の具合を見ながら考えていこうと思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"チラシやポスターといってもそれほどかしこまったものでなくてもいいですから、気づかないで申請できなかったということがないように、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字等を確認させていただきたいのですけれども、２２世帯３７人分、これは支給が終わった数と受け止めていいのでしょうか。既にどのくらい、何世帯何人分の申請が出てきているかというのは、現段階で把握されていますか尋ねました。","respondent":"伊東子育て応援課長","answer":"それと、もともとの児童扶養手当の受給者というところで、１０件１９名分が同日５月２６日の時点で支給されております。トータル２２件で３７名分というような形です。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"私が伺ったのは、５月２６日に支給された方、申請が出てきてある程度まとまったところで支給日に間に合うところが支給になっていると思うのです。とりあえず申請が上がってきている数というのが現段階で何世帯何人分なのでしょうかという質問をさせていただきました。","respondent":"伊東子育て応援課長","answer":"５月６日にご案内をさしあげて、それで５月２６日に間に合ったというところが先ほど言った数字でございまして、ちょっと今数字は持っておりません。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうした意味では、申請数にもう少しアンテナを立てていただきたいと思うのですが、いかがでしょうか。それからもう一つ、この該当しそうな人というのはどういう基準で選んでいらっしゃるのですか、説明を求めました。","respondent":"伊東子育て応援課長","answer":"いずれにしても５月の分は時間がなかったので確かに少ないのですが、今後はもっと数字的には、次回辺りは結構数字が上がってくるかと考えています。これらの方に案内を送ったというような形です。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"この方々には送っていらっしゃるのですか。それともこの方々というのは既に、当然に受給対象になっているということなのか尋ねました。","respondent":"伊東子育て応援課長","answer":"もともとの大きなところというのは児童扶養手当、令和３年４月の児童扶養手当の受給者というところがこの給付金の対象です。その後の家計急変等々、それ以降の状況に応じて該当するかどうかということになりますので、申請をしてくださいというようなご案内をしたです。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"今の説明はあまりよくわからなかったのですけれども、別にその枠組みでは行っていないということなのか、どちらなのでしょうかという趣旨の質問です。それはお分かりか尋ねました。","respondent":"伊東子育て応援課長","answer":"それを含めて行っているということです。","id":"exchange-008"},{"speaker":"芹澤副委員長","kind":"確認","question":"２点だけ確認をしたいのですけれども、その支給までの手続きというのはそこまで難しくないということでいいのでしょうか。月１回の支給日ということでお話があったと思うのですけれども、５月２６日のが終わったので、次の支給が６月末頃になるということでいいか尋ねました。","respondent":"伊東子育て応援課長","answer":"審査をして、その翌週ぐらいに支給をしていこうというような考えでおりますので、大体毎月月末ぐらいに支給をしていこうと。日にちは固定しているわけではございません。","id":"exchange-009"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"ぜひ月２回とか、できればで結構ですけれども、前向きに早く支給できるような体制の整備というのを検討ほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３１号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"これは来年の３月に申請なので、子ども食堂によっては全くほぼできなかったというところは、その辺のところをざっくりと教えてください。令和２年度より継続実施となっておりますが、例えば感染防止対策の継続的にかかる費用は、なぜなのかということを教えてもらいたいです。","respondent":"伊東子育て応援課長","answer":"今回の補正は、その他世帯分ということで、先行して実施しましたひとり親世帯の部分とは対象は別となります。その中の見積もった数字ですが、１５か所に関してはやっているという形で１５か所と、あと配食のほうが……。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問・要望","question":"だから補正予算も必要だということでいいのでしょうか。それとも横ばいなのか、クラスターはないけれども増えているのか、その辺のところだけちょっと説明を求めました。","respondent":"立木保育課長、伊東子育て応援課長","answer":"昨年と比べますと、家族の中での感染等、そういった報告のほうは多少増えてきているのかなというところはあります。ただ、感染の予防も徹底されてきたところもありますので、大きく広がるということは、今のところないと認識をしていま… 子ども食堂に関しましては、ただ、ただ今後の状況を見ながら開設していこうというような話があるというのが１５か所というような形になります。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本来のあり方に戻っていただきたいという思いで、こういう上乗せをした補正予算を組んだという理解でよろしいですか。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"今後多分６月以降、それから、この「高校生のみ養育」というのが案内送付に入ってくるというのがどういう仕組みなのかということを教えてください。それから、１９歳だと若干児童からずれてきますけれども、要は手帳の有無が境目になってくるのかどうかということを確認させてください。","respondent":"伊東子育て応援課長","answer":"児童手当のほうが１５歳、それは年齢のほうで引っ張ってきて、高校生であろうというところの世帯にはご案内していこうと思っているところです。","id":"exchange-014"},{"speaker":"あべ委員","kind":"確認","question":"ということは、高校に在学しているかどうかではなくて１８歳まで、その部分が対象になるということでよろしいでしょうか。確認させてください。","respondent":"伊東子育て応援課長","answer":"高校生というところですが、いわゆる１８歳ですので、高校生限定という話ではございません。それと、特別児童扶養手当のことに関しては、２０歳未満ということです。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"そうしたらなぜ2)でさらに取り出す必要があるのでしょうか。そうすると2)で特出しする必要はあるのか尋ねました。","respondent":"伊東子育て応援課長","answer":"特別児童扶養手当の該当ということであれば２０歳未満という形ですので、それはいいのですけれども、所得要件、非課税要件がありますので、もともとの1)というのは年度末に１８歳までの子ということですので、そこは分けて書かれていると、対象者にしているです。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"体温計ですとか少し値の張るものも対象になってくるのか、あるいはどういうものが対象になってくるかというのは今後示されるのでしょうか。そこはどのように設定されたのか、もう少し詳しく説明を求めました。","respondent":"伊東子育て応援課長","answer":"感染症対策費ということでくくられてありますので、備品というか感染症対策としての備品ということであれば当然に認められると認識をしています。それと、この月は配食だけになってしまったというような場合でも、それはその中で申請をしていただければよろしいかなと思います。","id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"お金は出るけれども、まず１年間はちょっと前払い、自腹でやってくださいねという仕組みであるということを確認させていただきました。都度発表してほしいということは申しませんけれども、区内でどの程度、参考までに教えてほしいと求めました。","respondent":"立木保育課長、若生保育支援課長","answer":"今年度４月以降の数字となりますが、職員、園児とそのご家族からは、３１件ほど陽性の方が出ています。特に休園等の措置は、通常どおりの運営で… 休園になったところですけれども、私立保育園のほうが４月・５月で３園ございました。それから、私立幼稚園につきましては２園ございました。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"３１件と私立が２２件、私立園のほうが圧倒的に数が多いと思うのですけれども、これは何かたまたまということなのでしょうか。いかがか尋ねました。","respondent":"立木保育課長","answer":"濃厚接触と認定された方は、最終接触の翌日から１４日間自宅待機をしていただくというところも変わってございません。職員が２名、園児が７名という割合になっていますので、やはりご家族の方の感染が多くなっている形になってあります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"もし対象になる場合、収入認定はされないということでよろしいのでしょうかということを確認させてほしいと求めました。昨年も実施された事業ということですが、実績は何件くらいあったのかを伺いたいと思います。","respondent":"伊東子育て応援課長、若生保育支援課長","answer":"対象になるとともに、要件を満たしているかどうかというのがあるところです。それと、収入認定に関しては、収入認定しない扱いということで聞いてあります。東京都の設定、これは補助上限が２,２５０円ということになりますので、そこまでの負担は生じないと考えています。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜそういう予算を今回組まないのか、伺いたいと思います。これは中止すべきなのではないかという点についてお考えを伺いたいと思います。","respondent":"初貝保育教育運営担当課長、伊東子育て応援課長","answer":"今のところ保育の現場に対して一律でのＰＣＲ検査は予定しておりませんで、ただ、今後の情勢に合わせてまた考えていきたいと考えています。今のところ予定どおり考えていくというところではありますが、また… 国のほうも様々ホームページ等、首相官邸のメールマガジンですとか、あとは政府広報のＣＭとか様々な形で広報すると聞いております。その辺を総合的に考えまして、ひとり親の部分もありますので、今後考えていこうと考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"あるいは支援していくかというところで補正予算を組まれている中で、なぜ今一番求められているＰＣＲ検査をやらないのかということを伺いました。保育課として安全・安心の保育業務のために定期的なＰＣＲ検査実施の要望というのを、そこについてももう一度最後にお伺いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"無症状の陽性者の方々からの感染が広がっていってしまうというのが今回のコロナの最大の特徴なわけですから、無症状の陽性者の方がどこにいるのかと。保育現場の方々の声も聞いて、これは早期に予算化していただきたいと、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"横山委員","kind":"確認","question":"３点目なのですが、内容に関しまして、継続なので何か変更点等はあるのでしょうか。なければそこを確認だけさせてほしいと求めました。","respondent":"伊東子育て応援課長、若生保育支援課長","answer":"実施要項等の詳細がまだ来ていない段階ですので、区としては大体大枠の中ではこういうスケジュールで行こうかなとは思っているところです。大崎地区、品川地区、その１５か所は一応住所的に見ると満遍なくあると考えています。 ベビーシッター等の利用支援事業の継続に関して、特段都からの支援スキームにつきましては変更ございませんので、昨年度と同様の内容でやっていく予定です。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"できる限り間に合うようにお願いできればと考えていますので、こちらは要望とさせていただけたらと考えています。ただ、いつどこで開催しているのかみたいなところを区のほうでも確認ですとか状況把握をしていただいて、少し手薄なエリア。","respondent":"伊東子育て応援課長","answer":"子ども食堂のネットワーク事務局がありますので、その中でいろいろと意見交換をしつつ、地域バランス等を考えて要請的な話をしていこうと思っています。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"その範囲でどうぞというか事業所が物品の内容を決めるのか、それとも区からこのようなものが対象ですとかが示されているのでしょうか。そこら辺を説明を求めました。","respondent":"若生保育支援課長","answer":"こちらの物品購入につきましては、事業者あるいは園が独自に選んでいただいて購入したものの費用をご提出いただいて、区のほうで後でお支払いするというような形になってあります。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問","question":"小学校ではペーパータオルにする予定はないそうなので、そこの流れのところとか、今後どういった教育面での指導につながっていくのか。先ほど聞いたのは私立のほうもそうで、ペーパータオルとかを勧めているのか、そこのところを教えていただけたらと思います。","respondent":"初貝保育教育運営担当課長、若生保育支援課長","answer":"今のご質問で、ペーパータオルが環境面を考えると、確かに現状保育園に関してもペーパータオルを設置しまして、そちらで手を拭いているです。現状ですと安全第一というところで… 各私立の特性ですとか状況に合わせて、ペーパータオルのほうも購入する際の補助金に活用できますということで、そこは各園のご判断で活用していただいているところです。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"先生によっては、まだ自分のタオルを持ってきてポケットに入れていたりするのです。はもうやはり先ほどご答弁にもありましたけれども、今後を見据えていろいろと検討していただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"で区の独自財源による支援とか上乗せがないということで、先ほど少し言いましたが、現場とか区民の実態に照らせば不十分さはあると思います。ただ、計上された事業というのは全部コロナ禍で苦しむ区民の支援にとっては本当に大切な事業ですので、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":26513,"voices":98}},{"id":"r03-20210527-5","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"総務委員会","time":"午前１０時０９分～午後 １時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"第３３号議案、専決処分の承認を求めること","agenda":"第３３号議案、専決処分の承認を求めること","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"何点か伺いたいのですけれども、一体どういう事情があるのか、ご説明ほしいと求めました。３点目は、誰がどう行うのか、３点まとめて伺いたいと思います。","respondent":"提坂税務課長","answer":"金額的に言いますと７９１万円ほどで、台数的には約４００台ということで、令和３年度の予算額についても７８０万円で４１０台の見込みです。この見込みということなのですけれども、車の購入にどの程度影響を及ぼすかということで、なかなか推測するのは難しい面があります。","id":"exchange-001"},{"speaker":"吉田委員","kind":"意見","question":"専決処分となってしまったということについては、なるべく専決処分は避けるべきではないかという立場をとっております。ただ、今のご説明だと、今回についてはやむを得ないと考えますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで、受付電話は、現在５０台稼働していると伺っておりますが、これをさらに拡大していただきたい。こうした補正予算を直ちに組むべきだと思いますけれども、いかがか尋ねました。","respondent":"黒田財政課長","answer":"７５歳以上の方の接種が開始されておりまして、６５歳以上の方につきましては、予約開始が６月８日からという予定です。予約開始初日ということであれば集中するところもありますが、所管と連携して、必要なものを計上できればというふうに思っております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり都と同じく週１回にすべきではないのか伺いたいと思います。そして、７月以降もしっかり定期的に検査を行う必要があると思いますが、お考えを伺いたいと思います。","respondent":"黒田財政課長","answer":"その中で、今後、必要な対応がなされるのではないかというふうに思ってあります。入所施設については東京都が対応しますので、７月以降の対応については、必要な対応をとってまいりたいというふうに考えてあります。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"しっかり補正を組んで、直ちに実施すべきだと思いますけれども、伺いたいと思います。国および東京都に、東京２０２０大会の中止を求めていただきたいと改めて思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"しっかりＰＣＲ検査を行うと、この立場を感染が抑制するまで、しっかりと位置づけていただきたいと要望したいと思います。これをしっかりと打ち出していくことが、いよいよもって必要だと思いますが、最後にいかがか尋ねました。","respondent":"黒田財政課長","answer":"事業者への支援につきましては、東京都のほうで所管していまして、区のほうでは、いわゆる相談事業などを所管のほうで行っております。今回、キャッシュレス決済ポイントなどを活用して、今後も引き続きそういった面で努力してまいりたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"吉田委員","kind":"確認","question":"区民への情報のお知らせのことを確認したいと思うのですけれども、伺ったところでは、その辺について確認したいと思います。そういうことがきめ細かくされるべきだと思うのですが、広報広聴の分野とか、そういうところではどのようにお考えか伺いたいと思います。","respondent":"黒田財政課長","answer":"そういった形で申請不要で対応するというふうな制度でございまして、広報媒体を活用して行ってまいりますので、行き渡るような形で取り組んでまいりたいというふうに考えてあります。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"私はぜひ補正を組むときに、全体的にそういうことをきちんと検証することを求めていただきたいと思うのですが、いかがでしょうか。感染を広げることになるので適切ではないと思うのですが、その辺の検証を、区としてどのようにお考えか伺いたいと思います。","respondent":"黒田財政課長","answer":"広報紙やホームページのほうで、もしくはお電話等で問合せいただくという形で、情報が行き渡るようにしてまいりたいというふうに考えてあります。例えば洗浄剤の銘柄指定をしているわけではありませんが、当然、周知しながら事業を進めてまいりたいというふうに考えてあります。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは強く要望しておきます。これも、最後、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"見解だけお聞かせ願いたいのですが、積極的に進めるような対応はお考えなのかどうか、お聞きしたいと思います。は食事をしていただく、そういう施策をとるのが私は基本だと思うのですが、その辺についてご見解を説明を求めました。","respondent":"黒田財政課長","answer":"１点目のご質問のかかりつけ医等での接種につきましては、現在、所管で鋭意調整しているというふうに伺っております。両方合わせまして２０億円を超える形の区内消費というところも、区として、区内で消費していただきたいというところで補正予算を提出しています。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"どうしても国が主導で動いて、どうやって動いていいか、もう混乱をしていると思います。そして、区民に対する配慮をしていただいて、できるだけ多くの区民を助けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問・要望","question":"５月１９日でしょうか、これがどのぐらい解消されていくのかというのと、現在どのくらい募集などがあるのか分かれば教えてほしいと求めました。このマイナンバーカードの普及率の目標値があるようでしたら、教えてほしいと求めました。","respondent":"黒田財政課長","answer":"この４月までに結構申請が多かったというふうに聞いておりまして、そういった中で遅延の解消を図ってまいりたいというふうに思ってあります。約３１％の交付率となっておりまして、令和４年度末に、遅れず交付できるように対応してまいりたいというふうに考えてあります。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そういったものがスムーズにいくように、ぜひ区民の方々の生活や申請がスムーズにできて、サービスが向上するように努めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"パソコン上で暗証番号を入れて、そこまでたどり着くまでの作業により待ち時間が長く延びてしまっているというのは要因の１つだと思うのです。品川区の取組を知っていただきたいというのが、これは要望で終わりますけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"意気込みをちょっとお伺いしたいのですが、予約もなかなかとりづらい、そういうお声が多く聞かれております。何かそこら辺をぜひ教えていただきたいなということが、１点、お願いをしたいと思います。","respondent":"黒田財政課長","answer":"７月末までの接種を目指しているというところで、国を挙げて取り組んでいるところですので、今後も取り組んでまいりたいというふうに考えてあります。５月末までの緊急事態宣言の関係で、６月がどうなるか分かりませんが、お知らせしてまいりたいというふうに考えてあります。","id":"exchange-015"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"丁寧に周知もしてほしいと求めましたが、早めに、また春の商品券の販売をぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"個人情報を一括化し、個人情報を危険にさらすこうした制度は普及すべきでないということは述べさせてほしいと求めました。款別審査での提案、総合審査での提案もぜひ受け止めていただき、一層の対策強化を求めたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ感染拡大という視点からも、保育従事者、教員へのＰＣＲ検査の拡大は、今後の補正で計上していただきたいというふうに思います。この事業が有効に使われるような広報と、それから、その後の検証についてはやっていただきたいという要望を付け加えて賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"新妻副委員長","kind":"質問・要望","question":"区民の皆様が、情報をどうやって取ればいいのか、品川区のサービスは何なのかということを求めているのだなということを非常に感じました。この１年間、大変にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19996,"voices":57}},{"id":"r03-20210527-10","meetingId":"r03-cm05","date":"2021年5月27日","dateIso":"2021-05-27","committee":"議会運営委員会","time":"午後 ３時３０分～午後 ３時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5414#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":1325,"voices":8}},{"id":"r03-20210607-6","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"区民委員会","time":"午後 １時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そうしたサポートの周知について対応を伺いたいと思います。質問は、シンプルですけれども、それに見合った対応として追加対策をどのように考えているのかそれぞれお伺いしたいと思います。","respondent":"川島地域活動課長、遠藤商業・ものづくり課長","answer":"地域センターでのワクチン接種に関する相談対応については、インターネット上の入力もお手伝いしている事例もありますし、困ったことがありましたら。こちらはワクチン接種の相談対応というのは庁舎でやっておりますけれども… 景況調査なども行っておりますので、そういう部分も含めまして現況については把握していきたいと考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"何でも地域センターに相談できる関係も長年培ってきておりますので、ぜひそうした姿勢で進めていただきたいと要望しておきたいと思います。思い切ってそこへの直接支援をぜひ検討していただきたいと、この間も述べてきましたけれども、ご検討いただければと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"オリンピック・パラリンピックについて伺いたいと思います。ぜひ品川区として区と国と東京都に開催中止を要請してほしいと求めましたが、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"新型コロナウイルスがなかなか収まりを見せないような状況の中ですが、安全・安心を追求しながら、それをまず第一に考えて私どもも計画しております。今のところ、東京都や組織委員会にそういった申入れをする予定はございません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"この状態でできると思うのかどうか、改めて伺います。聖火リレーについては後で述べますけれども、やはり密を作るこういう状況は避けるべきだと思いますが、改めていかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"おっしゃるとおり東京２０２０大会は幾つもの競技が同時に行われるわけですから、今おっしゃった例が参考にはなっても。ぜひとも国や東京都に対して開催中止を要望するよう、重ねて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そうした中で、なぜわざわざ密になるようなことをやるのか伺いたいと思います。しかも公道を使って、事前に広報でお知らせまでして、こうした聖火リレーはリスクを伴うから行うべきではないと思いますが、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"先ほどご案内申し上げましたとおり、チラシのほうで沿道での観覧はご遠慮くださいと、東京都や大会組織委員会より一歩踏み出した案内をする予定です。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"いやいや、ここから先はだめです、２ｍ以上のソーシャルディスタンスを保ってくださいという呼びかけを区の職員が行うのですか。実際の開催そのものは少し直前でというお話がありましたけれども、例えば緊急事態宣言の下でも聖火リレーは行われるのか、改めて伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただし、委員のおっしゃるような状況としましたら、おそらく公道ではやらないような状況の場合かなと思います。その場合に、そこはもちろん区民の安全・安心を第一に考えてやりますので、ご心配ないようによろしくお願いします。","id":"exchange-007"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認なのですけれども、こちらは「沿道には来ることはご遠慮ください」と案内するということで、この資料には「ＮＨＫの特設サイトで視聴できます」とあるのですけれども、インターネットをお持ちでない方に関しては、何か見られるような手段ですとか、何かあるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今のところインターネットでは、リアルタイムで見られるというものなのですね。なかなかちょっと見るのが難しいかなということもありますので、そのあたりはまたいろいろ考えていきたいと思います。","id":"exchange-008"},{"speaker":"横山委員","kind":"意見","question":"もし何かしら行われる場合には、インターネットをお持ちでない方にも、リアルタイムではなくても、ご視聴いただけるような何か手段があるといいかなと思いますので、ぜひご検討をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"「ご遠慮ください」という言い方についてなのですけれども、基本的に密を作らないために沿道で観戦するのはやめてほしいというスタンスであれば、罰則つきでなくても、観戦は禁止しますという言い方ができないものなのかということを１点伺いたいのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"禁止までしてやるのかというちょっと難しいところもありますので、なかなか禁止という言葉を使うのはちょっと今の時点では難しいかなと思います。なかなか禁止というところまで踏み込むのは厳しいかなというふうに認識しております。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"区としては協力という立場なのはわかりますけれども、観戦は可能であればゼロが望ましい、来てほしくないという立場なのか伺いたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１０がいいのか、１００がいいのかという数値的にはなかなか表せませんが、全くゼロがいいというふうには思ってはおりません。先ほど申し上げましたとおり町会長会議等でもご説明差し上げますので、地域に浸透させていただこうかなというふうに思っております。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問・要望","question":"無観客開催と同じような意味合いで基本的に区として観戦はご遠慮いただきたいと、そういった無観客開催と同等のスタンスを取っていただきたいなと。それがひいては間違いなく確実に安全な方法と思うので、そういったスタンスを私としては要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"昨年と重なる部分はあるかとは思うのですけれども、やはり中小企業支援について新型コロナウイルス感染拡大による事業所への補償、支援ということは区民委員会としては引き続き行っていくことが私は大切ではないかなと思いますので述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"くにば委員","kind":"意見","question":"支援をどういうふうにしたら支援できるかというところを主眼に置いていたと思うのですけれども、令和３年に関しては、維持という部分を検討したらいかがかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"横山委員","kind":"意見","question":"スポーツを通していろいろにぎわいというか、そういったコロナ禍で難しいとは思うのですけれども、何か支援ができるのかというところが１点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"新妻副委員長","kind":"意見","question":"今年度マイナンバーの推進というところでの職員の配置も増やしていただいた上での体制が取れるのかなと思っておりまして、マイナンバーの活用または推進というところで１つ取り上げていただけたらと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"確認","question":"マイナンバーのことについて事業を確認したり、推進と入ってしまうと私は推進すべきではないという立場になりますので、推進という言葉はちょっと調整していただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"横山委員","kind":"意見","question":"マイナンバーの申請件数が昨年２倍以上になっているというところで、そういった時期に来ているかなと思いますので、そういった部分を含めて議論していけるといいのかなというふうに思いましたので付け加えしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":34812,"voices":89}},{"id":"r03-20210607-7","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"厚生委員会","time":"午後 １時００分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"関係される皆さんと議論を重ねてきたとも伺っているのですが、提案されるのが第２回定例会ということで、当事者の皆さんとどのような状況なのか。当事者参加で最後まで進めていただきたいと思って、伺いたいと思いますとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"これまでも何度もずっと意見交換を続けてまいりましたし、これからも同じように、それは変わらないものです。詳細につきましては、また上程のときに説明します。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"提案","question":"議論を重ねてきたことは承知しています。当事者の皆さんと確認し合っているのかというのをお聞きしたかったのですけれども、そこをもう一度お願いしたいのと、そこを伺いたいと思いますとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"１点目、その姿勢は変わっておりませんで、当事者ときちんと意見交換しながら進めていくということには変わりはございません。２点目ですけれども、品川区障害福祉計画推進委員会につきましては、計画の策定委員会とは別に設置する予定です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、策定委員会自体は、策定されたら解散ということでいいのか尋ねました。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、計画が策定されれば、策定委員会の役割はそこで一旦終了ということになります。それとは別に、品川区障害福祉計画推進委員会を新たに設置する予定です。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"その後はやられていないのでしょうかということと、あと、今後どのようなスケジュールで進めていかれるのか。コロナ禍ということもありますけれども、その２点、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"医療的ケア児等支援関係機関連絡会についてですが、準備会を実施した後、なかなか開会ができなかったということがあります。できることは進めていっておりますので、また感染症の状況を見ながら、開催に向けて実施していきたいと考えています。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、２回目の準備会議がいつかとかというのは、今のこの状況では出せないということか尋ねました。","respondent":"松山障害者福祉課長","answer":"医療的ケア児等支援関係機関連絡会の予定ですが、あるいは直接医療的ケア児に対しての支援をされている方が多うありますので、実施時期については決めていきたいと考えています。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、最後に、生活保護のところで、先ほど課長のほうからも、減少傾向にあるということでした。コロナ禍で生活が大変厳しくなっている方も多くいる中で、令和２年は減少しているという、この状況をどのように見ているか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"減少している主な要因といたしましては、申請自体が減っているということではないのですが、受給されている方で、残念ながらお亡くなりになられる方が年齢層的に非常に多いという状況でして、結果として減少傾向になっているです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、保護基準などもどんどん引き下げられていく中で、やはり基準に合うというか、苦しいのだけれども、要はそこに対象にならないという方もいるのではないかと感じるのですけれども、そういった状況は感じられているか尋ねました。","respondent":"櫻木生活福祉課長","answer":"生活保護制度自体の周知、または相談しやすいような状況というのは、我々、これからも努めてまいりたいと考えています。生活困窮者自立支援制度ということで、そのような制度が整っておりますので、そちらのほうも周知をしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"生活福祉課なのですが、９ページのところで、暮らし・しごと応援センターの職員体制というのはどうなっているのかを伺いたいと思います。厚生労働省が基準と言っている８０人を大きく超えている状況だと思うのですけれども、あと、最大の受持ち人数を教えてほしいと求めました。","respondent":"松山障害者福祉課長、櫻木生活福祉課長","answer":"今、職員は区の障害者福祉の向上のために日々努力をしています。業務に対して人員をどう配置するか等につきましては、区の全体の中、あるいは福祉部の中でまた検討していきたいと考えています。昨年までは４名体制だったのですが、今年度に入りまして６名体制で、体制を強化したところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう中で、ケースワーカーの方の支援というのも様々な形で求められることがすごく多くなっておりますので、改めて要望しておきたいと思います。常勤換算で６名ということでの職員体制ということになっているのか、区の職員として６名いらして、そこの実態を教えてほしいと求めました。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターにつきましては、いわゆる相談員という形で配置されている方は全て会計年度任用職員という形になっております。そのほかに、管轄するような者はまた別に正規職員としているです。","id":"exchange-009"}]},{"id":"topic-02","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２ページの職員の配置状況なのですけれども、昨年に比べたら、大井保健センターと荏原保健センターで１名ずつ増えているということなのでしょうか。保健予防課で３名増えているということなのかと思うのですけれども、どういう考え方で保健師を配置されたのか、その点について伺いたいと思います。","respondent":"柏木品川保健センター所長、鷹箸保健予防課長","answer":"その部分は強化されたと認識しております。そこは検討する余地はあると思いますので、今後の計画については、人事部門のほうとは相談をしていきたいと考えています。 保健予防課の保健師等について、ご説明いたします。派遣の事務職員が４名、東京都から常に応援職員が４名ということで、非常に大きな体制で対応しているところになります。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回２名、多分、２３区の中でもまだまだ低い配置人数になっているのではないかと思います。ここのところをしっかりと充実させるということでは、これからも引き続き保健師の増員をしていただけますように要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種準備状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ワクチンの７５歳以上の高齢者の接種は始まっていて、２週間ほど経ったと思うのですけれども、予約済みが６２％となっています。１００％にはならないのかなと思うのですけれども、区としてはここはどのように考えられているのかというのを伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"防衛省が設置している大規模接種センターに行かれた方、それから、高齢者施設での接種が既に終わっている方も含まれております。ただ純粋に予約をされていない方も含まれているのは間違いございませんが、それ以上のことは、現時点では我々のほうでは把握できておりません。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。７５歳以上の方へのサポートとして、ヘルパーや在支の方々の手も借りていることと思うのですけれども、そこの状況を伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご指摘のとおり、在支の方等々のご協力をいただきながら、予約は進めさせていただいているところです。検討から調整を進めているところですので、今、医師会とまさに調整中です。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"確認","question":"ぜひ受けたいのに受けられない人がいないようにというのは、お願いしたいと思います。６４歳以下の方には６月２９日から接種券を配布、７月上旬から予約開始ということで、もう一回確認したいのですけれども。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"おっしゃるとおり、６月２９日に発送、７月上旬より予約を開始です。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"６月２１日からスタートできるようにという説明だったのですが、今現在、何か所ぐらいされるのでしょうか。そこをお聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現在まさに調整中でございまして、数については確定した数字ではございませんが、６月２１日の段階では、５０以上の個別接種の会場から進めさせていただいて、順次増えていくということで、１００以上の会場になろうかということで、現在調整を進めております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。障害を持たれている皆さんへの接種のサポートというのがどのようになっているのかというのをお聞きしたいのですけれども、お聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"手話のタブレット、通訳も含めてですが、タブレットは配備しております。筆談具も配備しております。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"確認","question":"分かりました。今ある接種会場の全会場でそれが実施できているということなのかを確認したいのと、封筒に切り込みが入っていて、伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長","answer":"Ｕｎｉ－Ｖｏｉｃｅの切り込みを入れて、発送はいたしました。その後の予約ができているかできていないかというところにつきましては、現時点ではこちらのほうで１００％の把握はできておりません。 視覚障害者の方については、福祉部のほうから個別にご連絡をさせていただいて、予約を取るようなことをしています。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"きめ細かく対応していただきたいということで、お聞きしました。保育園などのところにも接種がと新聞にも載っていたのですけれども、そこら辺の状況を詳しく教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"各会場、数件程度のキャンセルはあるようです。施設従事者の方等々を派遣して打っていただくように、全庁を挙げてシステムをつくりまして、今現在それを稼働させているところです。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、ワクチンの廃棄というのは出していないという状況で進んでいるということでよろしいか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"廃棄は出ておりません。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"空いている時間、そういうものが出るようにしていただきたいと思うのですけれども、システム的にできないのでしょうか。伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"システム上で予約をする際に、会場名と日程を入れて検索していただくと、空いているところが出てくるような感じになっております。例えば、６月７日以降の旧荏原第四中学校の空いている時間枠と空いている日にちが時系列に出てくるという感じに今現在はなっております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこら辺の仕組みも併せて、具体的なところで教えてほしいと求めました。その点についてもお聞かせほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"広報しながわでもいたしますし、現在調整中ではありますが、全戸配布等々も考えて検討して動いているところです。クリニックのお考え等々もありまして、またシステム等々の説明に参りますので、その辺りでも詰めてまいりたいと考えております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"分かっているのであれば、教えてほしいと求めました。６５歳以上の方が１４日から始まるときには、スマホでもなかなか取ることができないという方は、そこの点についてはいかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、秋山保健整備担当部長","answer":"広報しながわについては、６月２１日号を予定しております。皆様が分かりやすいように周知するということで現在進めておりますので、６月１４日の予約には間に合うように周知いたします。５０といった数は、最低ということでお考えいただければと思いますので、５０という数にはこだわらないでいただきたいと思います。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"分かるようであれば、例えば１週間のうちにははっきりするとか、そのようなことが分かったら教えてほしいと求めました。それをお知らせするということで、そういう体制を取っていただくということで確認させていただいてよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"すごく不安で早くやってほしいという要望も受けているのですけれども、７月上旬からの予約の取り方については、どのように考えられているのか。それから、７月上旬からの予約の取り方、その点についても説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"どこまでということは現在、最後の調整を進めているところですので、いましばらくお待ちいただければと考えています。キャンセル対応というか、それはそれで一斉の予約枠とは別にそういった動きもしていきたいと考えておりますし、区としても支援をしています。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"６月２９日に６４歳以下の方に接種券を配布するというところでは、一斉に接種券が配布されるということで考えていいのでしょうか。このようなところの課題を乗り越えることが必要なのだとか、そのような課題などもありましたら、お聞かせいただけたらと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"訪問しての予防接種ですが、調整中です。お待ちくださいませ。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"今までにやったことのない、これだけのたくさんの区民の方へのワクチン接種ということで、本当にご苦労が多いと思います。でも、区民の方にとっても早くやりたいというすごく切実な思いもありますので、これからもいろいろ取組をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"確認","question":"これは確認なのですけれども、６５歳未満の方々も、それはシステム上優先して予約できるようになるのでしょうかということです。７５歳以上とか６５歳以上の方のところには、基礎疾患のあれはあったけれども、そういう仕事の枠がなかったと思うので、そこの確認です。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もしくは、先ほどお話しいたしましたが、調整している全戸配布等々で対応ができればと考えています。今現在検討して進めているところですので、現在、最後の調整を進めているです。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういう従事者の方に優先してやっていただくということをしていただきたいという意味で言っているのですけれども。行った先で、本当にそうですかというのを証明していくというやり方で、特に６４歳以下の方は進めていくということでよろしいか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"そのとおりです。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"７月中旬だとか、予約が取れて６月中旬に１か月早まったとか、そのときに言えるではないですか。これはぜひ６月１４日も含めて、それ以降、一般の方も含めて、フル稼働で少しでも早く、１日でも早く接種ができるようにお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"そういった場合に、品川区民でなくて区内の施設に従事している方も、同じように打てるのかどうか。そこの確認をさせてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、鈴木（博）委員長","answer":"現状では、接種券が、当区で手筈することのできる、品川区民の従事者に、キャンセルの対応等々で、各会場に打ちに行ってもらっているという運用をしております。 一番最初に住所と住民票とを照らし合わせて、それが合わなかったら、はねられてしまうから。だから、多分、今の説明は、要するに、品川区民ではないとマッチングしないから駄目ではないのかということです。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"研究はされていると思いますけれども、進めていって、改善をよろしくお願いしたいと。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"２回目が１.２％ということで、６５歳以上の方が７月末までには接種は終わるだろうという見通しを区として持っているのか、そこら辺のところ。そこの接種率というのが今後どのように進んでいくと想定しているのか、その点についてだけ説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"あくまで試算ではありますが、７月中に終わる方向で、今現在、一生懸命準備を進めておりますし、区としても動いているです。","id":"exchange-032"},{"speaker":"せお委員","kind":"質問・要望","question":"６５歳未満の方、７月初めから接種が開始されると思うのですけれども、予約が取れないと。そこら辺の見込みが分かれば、教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もちろん解消に努めるようにはしていますが、ただ、会場のキャパシティ等々にもよりまして、それがなかなか実現できないところもあります。１日の接種人数としては、そういった会場も含めての見込みというか、試算をしているとご理解いただければと思います。","id":"exchange-033"},{"speaker":"せお委員","kind":"質問","question":"そうでなくても取れるのかというところで、クリニックのお考えがすごく重要になってくるのですけれども、それは統一するということですよね。〔「医療機関によって違う」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どうしようか考えたのだけれども、特別区議会議長会への要望でも、やはり保健所機能の強化はやったほうがいいと思うのです。どこかでやはり１回はやったほうがいいような気がしてならないので、そういう問題も取り上げていただけたらどうですかということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":48155,"voices":161}},{"id":"r03-20210607-8","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"建設委員会","time":"午後 １時００分～午後 ３時１３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"立憲・無所属しながわのあべ祐美子です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そういうことがやはり大前提にあると思いますので、この住民の意見の反映の仕方をどう考えていらっしゃるのか、伺いたいと思います。住民を守るということでは意味がありませんので、やはり効果がないというふうに思っておりますけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長、鈴木都市計画課長","answer":"外環道の陥没事故がございましたので、同じような工法を区でも使うというところから、より安全性に努めて検討していただきたいという内容です。ＪＲ東海は… 平成２５年に策定した計画について、今年度ならびに昨年度、２年間かけて行っていく予定です。ならびに、改定案につきましては、しっかりパブコメを行って、区民の声を計画のほうにしっかりと反映していきたいという予定です。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"シールドマシンが真下を通る住民には、残らず事業者が説明をすべきだというふうに思いますけれども、いかがでしょうか。そして、事業者が説明をしない場合は、区がこの影響などを説明していくべきだと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、そういったことをどう食い止めていくのか、区の仕組みを伺いたいと思います。ぜひ応じていただきたいと思うのですけれども、そういったことを業者にも言っていただきたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"２点ほどお伺いしたいと思います。既に取り入れているよということであれば、ちょっとまだ不十分な気もするのですけれども、その評価も含めて教えてほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"そうした中で、地域の方の意見というものは吸い上げたり、またはこちらのほうから丁寧に説明をしていきたいというふうな形で進めてきたです。説明会であったり、区民の方が参画する場面というのが多々ありますので、そうした中で意見を聞いていきたいというふうに考えてあります。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"説明会を開いて、ぜひそこは区も積極的に取り入れてほしいと求めましたし、ぜひそこは心がけてやってほしいと求めました。２点目なのですけれども、どういうくくりなのかというのをご説明いただきたいのと、これを増やす考えがあるのかということを確認したいと思います。","respondent":"鈴木都市計画課長","answer":"今ご質問いただいたことに対するお答えとすると、都市計画課のほうで所管するのは航空機騒音に関して、それ以外は環境課のほうでです。昨年度も短期測定局の設置というところで、そうしたところを国のほうに、今後も引き続きそうした取組を区としては求めていきたいです。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"住民の方々からご要望も多いところですので、国との折衝の中でも役立てていただきたいですし、区としてもぜひ主体的に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"大きく２つ確認をしたいと思います。１つの項目として挙げてもいいのではないのかという、この１年間を通しての議論の仕方について、お答えほしいと求めました。","respondent":"鈴木都市計画課長","answer":"国が責任を持って進めるです。ご議論といいますか、報告をさせていただいてご説明させていただきたいというところで、私としては考えている次第です。","id":"exchange-008"},{"speaker":"西本委員","kind":"提案","question":"もう１つの確認事項、仕切りの問題です。これから１年間、特別委員会の正副委員長との打合せはどういうところまでされているのか、今後のお考えも聞きたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"将来にわたっての考え方というのも含まれるのかなというふうに思います。できれば私たちも建設委員会の立場として議論したい部分もたくさんあるものですから、ではどこまでやったらいいのみたいなことになってしまうので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に３つ伺いたいのですが、この姿勢を改めるべきだと私は思っておりまして、区民の住宅事情は大変さを増しています。区内で言うと京急線などがなかなか設置されない状況ですけれども、区のお考えを伺いたいと思います。","respondent":"竹田住宅課長、鈴木都市計画課長","answer":"区営住宅あるいは区民住宅、都営住宅等の公営住宅等、総合的に区内の住宅については推進していきたいと考えております。ご質問のありました区営住宅の増設ですが、今のところは考えておりませんので、維持管理という表現にしています。今年２月まで測定結果をホームページで公表していますけれども、来年度以降の事務事業概要のほうには検討してまいりたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"区営住宅のところです。推進をしていきたいということですが、増設はしないというのは矛盾するのではないかと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"事務事業概要を再び議題に供します。 進め方でございますが、先ほどと同様に、災害対策担当も含め、防災まちづくり部の事務事業概要","agenda":"事務事業概要を再び議題に供します。 進め方でございますが、先ほどと同様に、災害対策担当も含め、防災まちづくり部の事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"先日、説明会があったと思うのですが、何人の方が参加をされて、どういったご意見があったのか伺いたいと思います。都との分担がどうなっているのかということと、１週間の備蓄をと、そこの関係性というのはどういうふうになっているのか伺います。","respondent":"高梨公園課長、平原防災体制整備担当課長","answer":"最初に、私のほうから、しながわ区民公園の説明会についてのお答えをします。６月１日１８時から、事前申込み制といった形で説明会の開催をいたしました。一昨年の台風１５号等をはじめといたしまして、新たに顕在化した問題に対応するために、計画的に資器材を導入させていただいているところです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"震度７レベルになると。そうしたときに、３日分で足りるのかという思いがあるのですが、いかがか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"３日分ですけれども、あるいは自治体側の被災に伴いまして、どのような物資が必要かということが政府に届かないということもございました。そちらにつきましては、被災のないところから集中的に様々な機関の協力を得て政府が運び入れるということになってあります。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問・要望","question":"だからこういう形で置いておくことが必要なのだということがあれば教えていただきたいのと、用地担当課長というのは道路だけの用地なのでしょうか。どういうくくりになっているのか確認させてください。","respondent":"溝口用地担当課長","answer":"学校ですとか、そういったものの事業用地の取得の用地の契約については、全て私どもの用地担当のほうでやっているというのが実情です。そういったところをしっかりやっていくというところでの組織づくりというふうに認識して、今兼任ですが、やらせていただいているところです。","id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"でも実際に訓練というと、１１会場での訓練は終わっているという認識ではあるのですが、ほかの会場ではやっていないという認識なのですね。ですので、この件は、今年はどうされるのかなと思っているのですが、確認したいと思います。","respondent":"五十嵐災害対策担当課長","answer":"差引き４１会場の訓練については、実際にはできておりません。コロナ禍ではありますけれども、まだ続くかもしれませんが、その中でもできる訓練というのをご提案しながら進めていきたいと考えております。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"これも確認ですが、１１会場でされたということで、自由選択になってしまっている部分があったのか。ご理解をやはり求めていくということは、意見になってしまいますけれども、その辺のお考えを説明を求めました。","respondent":"五十嵐災害対策担当課長","answer":"西本委員のご意見を踏まえて、今年度はそのような形で進めていきたいと考えています。","id":"exchange-017"}]},{"id":"topic-04","title":"が、所管する議題が終了した理事者の方は、ご退席いただいて結構です。 ありがとうございました。 それでは、報告事項「『東京河川改修促進連盟』の総会および促進大会」","agenda":"が、所管する議題が終了した理事者の方は、ご退席いただいて結構です。 ありがとうございました。 それでは、報告事項「『東京河川改修促進連盟』の総会および促進大会」","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"今後、この予備費を１,０００万円からまたさらにどんどん増えていくようなお金の構造になっていくのかと思うと、ちょっと心配なのですね。今すぐにどうしろというわけではないのですけれども、私としてはそういう意見も付していただきたいなと思いますけれども、いかがか尋ねました。","respondent":"栗原河川下水道課長","answer":"令和３年度歳入歳出予算（案）に関しましては、委員ご指摘のとおり、分担金の徴収はしないこととなっております。今後の分担金の徴収等に関しましては、私のほうから事務局のほうに申し伝えて、今後のあり方について検討するよう伝えていきたいと思います。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4322#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":41019,"voices":136}},{"id":"r03-20210607-9","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"文教委員会","time":"午後 １時００分～午後 ３時２８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"中止を求める世論も高まっていますが、今の時点で中止すべきだと思うのですけれども、いかがでしょうか。最後にコロナに関連して、不登校の話もありましたけれども、コロナでちょっと増えているのかどうか、その辺の状況を伺いたいと思います。","respondent":"矢部教育総合支援センター長、工藤指導課長、勝亦学務課長、有馬庶務課長、米田教育次長","answer":"一番最後にご質問ありました不登校についてですが、正確な数値はまだ速報値なのですけれども、大分増えているように把握しております。… お尋ねありました観戦事業につきましては、現在会場下見なども行いながら、都教委の指導に基づきながら準備を進めているところです。そういった観点… 来年度は、小学校１年、２年、３年生が３５人学級ということで、対象となっています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、もう小１から小３までは、もう必ず整えていくという決意でよろしいのかということです。現時点で３５人の学級編制になるのにもかかわらず、学校のお考えなのでしょうか、一部３５人以上の学級をつくっているところがあります。","respondent":"勝亦学務課長、有馬庶務課長、工藤指導課長","answer":"それから教材・教具等につきましては、指定の学級編制ができるように、今年度から対応していく考え方です。… この学級編制、どうしても物理的に無理なところについては、学区内の子どもたちだけであれば４０人までが認められているというところがあります。… 現在も、緊急事態宣言下におきましても、学校行事等につきましては、ガイドラインに従いながら工夫して実施をしている部分があります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり子どもにとってを考えていただきたいということで、第二延山小学校については、物理的には可能ですよねという。３５人という国が決めた、来年４月から可能だという理解でよろしいのか、それをお伺いします。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"前回答弁させてもらった内容になりますけれども、これは第二延山小学校は物理的にも厳しいということは事実としています。それがもう４クラス、４クラスになったら、物理的に余裕があるという話ではないです。 第二延山小学校の場合は学年が１クラスだけ下に、３階なら３階にずれてしまって指導がしにくいというところもあると聞いていますので、両方があるのではないかと思います。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、やはり３５人編成というのは、もうありとあらゆる支援をしていただきたいということです。学区をどうするかということも含めて、改善していただきたいというように、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"数日前の報道によりますと、大会の組織委員会自体は、自治体を通じて学校からの観戦のキャンセルを受け付けているというような報道がされております。組織委員会から、キャンセルする場合は連絡してくださいというような通知が来ているのかどうか、それをお願いしますとの意見を述べました。","respondent":"工藤指導課長","answer":"私どもが予定しております学校連携応援観戦というものは、また、その都教育委員会は組織委員会からチケットを配券いただくというものです。私ども都教育委員会からは、この間そういった連絡は来ておりませんので、準備を進めているという状況ではあります。","id":"exchange-006"},{"speaker":"松本委員","kind":"意見","question":"では、ちょっとこの報道とは違うというような理解なのだと思います。欠席扱いするのかどうかというところ、子どもは欠席扱いになるのかどうかということもよく最近聞かれるので、そこもお願いいたしますとの意見を述べました。","respondent":"工藤指導課長","answer":"その日は授業日というように設定する予定ではありますが、出席停止と同じ扱いで、欠席とはならないという措置をするというところで教育課程を組んでいます。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"できれば校長の判断も尊重していただきながらご判断いただきたいなという意見がありますので、どうかその辺り、引き続きご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"やはり子どもたちの学びについてもこれは影響があって、感染しないだけでは、学校事業としては成り立たないのではないかなと思っています。教育という、学びという視点からのコロナ対策というものがあるのかと思っていたのですけれども、その辺についてはいかがなのか尋ねました。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"まず教育委員会の事務事業概要の５ページのところで、新型コロナ感染症への対応というところで項目を設けさせていただきました。これを今言ったように、どのようにこれを表そうかというところは、これを作る上で検討させていただきまし… 庶務課長からもありましたとおり、ガイドラインを毎回バージョンアップして、今１１です。研修もしていますので、教員もＩＣＴを使いこなして、子どもたちに指導しています。","id":"exchange-009"},{"speaker":"吉田委員","kind":"確認","question":"今のお話でその辺のことをきちんとされていると確認できましたので、これからまた具体的なことで伺っていきたいと思います。これは意見として申し上げるということで答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"本当に初期の段階で子どもたちの接種はどうなのですかと伺ったときには、当時は、ここに来て一気にこの年齢の拡大が広がってきたと。ですから、やり取りがあるのかどうかということを教えていただきたいということと、１２月だったか尋ねました。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"これはもう区全体として対応するということで、会場のほうでご案内をしているというような状況で、それは全庁的に取り組んでいるです。今そういったところで、中学生の対応については… 引き続きですが、子どもたちや保護者への発信についてです。お子さんたちの様子が一番大切ですので、そちらを十分踏まえて、どのような手法で発信するかということはこれから検討してまいりたいと思います。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"それも含めての確認と、もしそうなった場合ですが、しっかりと取っていただきたいなと思います。その人権の観点だけ、もう１回、すみません、確認をさせてほしいと求めました。","respondent":"矢部教育総合支援センター長","answer":"一番大切な権利ですので、大事にして、子どもたちや保護者に不都合が生じないように、平等に進めてまいります。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとあと４５ページには、これはどういった理由で増えているのか、そこは伺いたいと思います。区に求めていると思うのですが、少なくとも公園の利用者の方への説明というのですか、そちらはいつなのかということを伺います。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"子供の森公園の一部を活用するに当たりまして、その場所も含めて公園の再整備を予定しており、こちらを選定した理由の１つとなっております。それから公園利用者への説明会の件ですけれども、現在説明会を開催というよりも… 私ども子ども家庭支援センターのほうが、令和２年４月から始動したところを含めて、体制の整備が相談の増につながっているという部分もあります。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"いずれにしても、本当に重要な課題、テーマになってくると思うのです。私たちにぜひ説明会をやってほしいという要望が上がっているわけですから、やはり丁寧に説明していって、もう一度だけ最後に伺って終わりにします。","respondent":"加島児童相談所移管担当課長","answer":"ご要望には可能な限り対応してまいりますが、ご説明のほうにつきましては、所管では個別に対応させていただきたいと考えているところです。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"事業を広げていくようなときにはどちらが主導していくというか、そのような役割分担というか、連携の仕方というものがもしあったら教えていただきたいのですけれども。","respondent":"廣田子ども育成課長","answer":"例えば公園等を使って事業をする場合には、所管である子どもの部門から公園課にこのようなことをやりたいというところを諮って、協議していくという形になっています。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"では結局、子ども育成事業なので、そちらのこのような事業をやりたいというイメージが先にあって、そこから公園課に連携を諮るというような理解でよろしいのか尋ねました。","respondent":"廣田子ども育成課長","answer":"冒険ひろばについては場所を探しているのでというところもありましたけれども、例示がちょっと具体的にできないのですが、公園側から、ここにこんな場所があるので、何か子ども向けの事業ができないかということもないことはないので、必ずしもこちらからということではないです。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"一般的なその職業としての捉え方があったのですけれども、やはり保育指針にのっとって、そのような理解でよろしいのでしょうか。ぜひそうあってほしいなと思っての質問なのですけれども、いかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"先ほど説明もありましたが、教育を充実させていくというようなことで、ハードとソフト一体になってやれるというような形で体制を整えたです。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"この担当課長が新たに置かれたということで、保育の質の確保について、ぜひ力を入れていってほしいと求めました。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"長３のその他","agenda":"長３のその他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２日間の出席停止ということですが、その間の学校の活動というものは、教育活動はどのような形でカバーされるのか伺います。","respondent":"矢部教育総合支援センター長","answer":"必要な紙の資料等も配付することになりまして、長い期間になりましたら、いよいよＩＣＴも早速使ってフォローしていきたいと考えております。ただ、学校の事情もありますので、センターとしての連絡を取り合って支援してまいります。","id":"exchange-019"}]},{"id":"topic-04","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"先ほど３５人学級について質疑させていただいたのですけれども、地域、学校によっては教室をどう増やすかなど課題があるということが分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5034#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":45901,"voices":124}},{"id":"r03-20210607-5","meetingId":"r03-cm06","date":"2021年6月7日","dateIso":"2021-06-07","committee":"総務委員会","time":"午後 １時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今ご注意がありましたけれども、デジタル化に関することは全く質問しないほうがいいのですか。ちょっと伺いたいなと思ってきたのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"デジタル化、情報推進課の事務事業概要でいろいろ触れられていたのですけれども、今後の展開、それから、どういう分野で、どういう展開を考えておられるのか、ざっとでいいですから、ご説明いただければと思ったのですが、いかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"デジタル化をする目的としましては、ＩＣＴ等の先端技術を活用しまして、区民の利便性の向上、または、業務の効率化を目指すものです。例えばシステムの標準化対応であったり、それ以外には、ＡＩやＲＰＡといった先端技術を活用していくといったものです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"確認","question":"でも、大事なことですから、それを１点確認しておきたいと思います。ですから、やっぱりもう１点確認しておきたいと思います。","respondent":"宮澤情報推進課長","answer":"スムーズな手続きであったり、そういった区民の方々の利便性向上を目的としておりますので、そこは注意して進めていきたいと考えています。それは引き続き気をつけながら進めていきたいと考えています。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"今のお話と関連するのかもしれないですけれども、品川区内の５Ｇ基地局の設置場所の把握は、情報推進課になるのか、それとも、また別の部署になるのか、そこだけ確認させていただきたいのですけれども、いかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"いわゆる民間の携帯電話会社等の５Ｇ、携帯電話の基地局に関しましては、情報推進課のほうでは特段把握はしてございません。","id":"exchange-004"}]},{"id":"topic-02","title":"に戻りまして、幹部職員紹介","agenda":"に戻りまして、幹部職員紹介","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"２０１９年度の１.６倍に急増したのだと報道され、それから、それへの対応はどうなっているのかということを伺いたいと思います。そして、品川区として、なぜコロナでＤＶが増えているのだろうと考えていらっしゃるのか、そのお考えも伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"今後ですが、ＤＶセンターを立ち上げたことによりまして、実務者対応の会議等々を開催することにしております。これによりまして、やはり引き続き区内の状況にも注視しながら対応していきたいと考えているところです。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"これは要望として申し上げておきたいと思います。どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"意見","question":"次の令和２年度の実績のところに、令和３年、今年の……。今年の１２月末、性の多様性の啓発が今年の１２月ということなのですけれども、そこら辺についてお知らせいただけますかとの意見を述べました。","respondent":"島袋人権啓発課長","answer":"１２月２日を予定しているので、まだきゅりあんでの活動になりますので、きゅりあんの会議室等々で開催する予定でいます。日にちにつきましては、１２月の第１土曜日を予定しています。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"皆さんに説明というか、報告をされたほうがいいと思うのですが、その辺は何かお考えでしょうか。もし答えられたら、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2200#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25683,"voices":102}},{"id":"r03-20210608-14","meetingId":"r03-cm06","date":"2021年6月8日","dateIso":"2021-06-08","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"公明党のあくつ広王です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"確認等々させていただけたらと思うのですが、公有地等の活用のところで、先ほどそれを待っているとおっしゃったのですか。様々広報媒体がある中で、区として課題と考えていることがあれば、大まかに教えていただけたらと思います。","respondent":"佐藤企画調整課長、濱中庁舎計画担当課長、大澤広報広聴課長","answer":"１つ目のご質問の元芝アパートの状況ですが、区から都に対して意向調査のほうを回答して、言葉が足りずすみません。そういうことです。 層化２段無作為抽出法ですが、その比率が公平に分配されるような形で抽出をして、郵送をするというような方法です。 今、その両方、紙と紙以外のもの両方の発信を同時にしていくということが大切なことだというふうに認識しています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"庁舎のアンケートのところなのですけれども、２段というのは、要は１段目がどういうことで２段目があるのか。地域の人口比率に合わせて取っていくということは分かったのですが、層化というのが分かりづらいのですけれども、もう一度いいか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"５地域を中心に８地域の人口比率に応じて、それに応じた形で抽出をしまして郵送していくという方法です。こちら、区の世論調査と同じ抽出方法でやらせていただきます。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"議会機能ということについては結構細かく議会から議論をして要望しているというところが、他自治体はたくさんそういう事例がありますので。電源をどうしていくのかとか、活発な議論をさせていただきたいなと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはごめんなさい、要望になってしまいました。あるいは、今どういう仕組みで動いていらして、それをどうやって拡大するのかということを教えてほしいと求めました。","respondent":"佐藤企画調整課長、濱中庁舎計画担当課長、宮澤情報推進課長","answer":"３番の元芝アパートに関しましては都有地ですので、都の回答を待っていると。４番の平塚二丁目寄付物件に関しましては、令和８年度までの予定です。新庁舎は５０年、６０年と長く使われる庁舎です。次世代を担う子どもたちも使う庁舎ですので、関係部署とも連携をしながら… 新型コロナに対応するテレワーク環境というところで、ＬＧＷＡＮへのリモート接続というのが認められてきているところであります。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"最初の質問の中で、そうすると、今、貸付け中のものというのは、逆に第一日野小学校跡地だけということでよろしいのでしょうか。私のほうは例示として挙げただけなのですけれども、特にそれ以外はないということでしたか。","respondent":"佐藤企画調整課長","answer":"お尋ねの区有地を民間等々に貸付けている用地というのは、今現在、第一日野小学校跡地のみというところで理解しています。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問・要望","question":"次にこちらの委員会で報告されるのはそれぞれどういう状況で、どういう時点での報告になるのか、教えていただきたい。これは分からないのですけれども、理事者に聞いていいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問","question":"旧荏原第四中学校とか、清掃作業所とかのそれぞれの段階についてもこちらで話してからということでよろしいですか。その他のところでお話しするということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"この１７業務というのは本当に基幹となるような区の住民基本台帳ですとか、個人住民税ですとか、そういう大きな話だと思うのです。この１年間で、どのぐらいのことがこの１年間で、確認させていただきたいのですが。","respondent":"宮澤情報推進課長","answer":"こちらに関しては、国のほうから令和７年度末までに移行するという方針が示されております。恐らくは第１、第２という形で、２段構えでそれぞれ１７業務の標準的な仕様書というのが示されてくるという形で認識している状況です。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"２段構えとおっしゃったのは、第１回、第２回というのが、この年度内に出てくるというようなことでよろしいのか尋ねました。","respondent":"宮澤情報推進課長","answer":"２段構えが今年度中に出てくるかどうかはまだ示されておりません。１７業務を、それぞれの２段のタイミングで同時に出てくるかどうかもまだ示されていないので、そこは夏の国の動向を注視している状況です。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"追加で１点。取り入れていっていただきたいと思っているのですけれども、そこだけ１点確認させてください。","respondent":"濱中庁舎計画担当課長","answer":"新庁舎に関しまして、ユニバーサルデザインのご意見を頂きまして、今後、ユニバーサルデザインとしましては、まずバリアフリー化等のハードや、また案内サインの表示なども含めて、ユニバーサルデザインの検討を深めていきたいと考えています。","id":"exchange-011"},{"speaker":"芹澤委員","kind":"質問","question":"デジタル化について１点だけお伺いしますが、決算特別委員会かどこかで伺ったのですけれども、検討状況がもし分かれば説明を求めました。","respondent":"宮澤情報推進課長","answer":"デジタル化を進めていくにあたっての体制というところで、この４月に情報推進課の中に情報戦略担当というのを新設いたしました。進めていくにあたってのビジョン、計画につきましても、現在検討しているという状況です。","id":"exchange-012"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"１７業務がやられているということですが、その１７業務がどういったものになるのか、伺いたいと思います。そうしたことがないようにしていくべきだと思うのですけれども、区の考えを伺いたい。","respondent":"佐藤企画調整課長、濱中庁舎計画担当課長、宮澤情報推進課長","answer":"その点も踏まえながら、今現在、私どものほうでたたき台を検討しているところです。今年度の行政改革特別委員会でまたご報告させていただいて… こちら、先行して５月１４日からホームページでご案内をしまして、意見募集フォームをやっているところです。今後、広報しながわにおきましても… １７業務は主要な業務ですが、年金、こういった主要な業務になってあります。","id":"exchange-013"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"検討中ということで、ぜひ住民参加でいろいろ検討会などもやりながら、住民要望を叶える施設検討をしていってほしいと求めました。システムの標準化のところでは、ぜひ、そういったことがないようにしていただきたいというふうに要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"そうした点も含めて、多くの区民の声を聞いていくべきだと思います。少し抽象的ですが、以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"そうすると、この議論を始めるのに適正な時期というのは、共産党はいつからとお考えになっているのですか。１５年後にはもう駄目だということを、先ほどご自身でもおっしゃっているのですけれども、いつぐらいが適当だと思いますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"意見","question":"どういう庁舎にするのかというものを区民も交えて考えて、１０年以上かけて検討して、少し短すぎるのではないか。それは要は広町の開発に合わせているからだと思うのですけれども、だから、そこを一旦切り離して進めていくべきだというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"では、先ほど申し上げたように、これはいつ結論を出すべきだと思っていらっしゃるのですか。１０年検討して、その５年後に建て替えの、共産党がおっしゃる１５年、そこから建設を始めるという、そういう認識でいいということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"意見","question":"１５年もつということなので、１５年経ってから建設が始まる、一、二年で検討するというのでは大変ですので、１５年後に間に合うような検討でいけばいいのではないかなというふうに思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/444693?Template=document&Id=6110#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19534,"voices":90}},{"id":"r03-20210609-19","meetingId":"r03-cm06","date":"2021年6月9日","dateIso":"2021-06-09","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 １時５２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今日は概要のご説明ということですけれども、災害廃棄物に関することで、災害廃棄物処理計画の作成が、もう６月に庁内会議を設置ということで、もう今月で差し迫っておりますので、この庁内会議がどのような形で設置されるのかだけ説明を求めました。","respondent":"山本防災課長","answer":"庁内会議の設置のメンバーですけれども、中心としては防災まちづくり部となり、プラスで都市環境部、それから衛生の部分もありますので、保健所の生活衛生課のメンバーを、部課長等を入れて進めていきたいというふうに考えているところです。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"まず最初の第１次の仮置場ですか、なるべくだったら便利で身近なところにあってほしい、どのようなイメージをお持ちか尋ねました。","respondent":"山本防災課長","answer":"仮置場の設置ですけれども、面積としては一定規模の面積、公園等が中心になってくるというふうに考えているところです。内部の検討会のほうで決めていきたいというふうに考えておりまして、現在は個別に区民の方のご意見をいただくというところは考えていないところです。","id":"exchange-003"},{"speaker":"吉田委員","kind":"意見","question":"これは意見です。ぜひ今後の庁内会議の中では、そのような方たちの参加をとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"品川区一般廃棄物処理基本計画について少し大きな、大きなというか、大ざっぱなことを２つほどお伺いいたします。令和３年度なのですが、令和５年３月までが今の計画ですから、令和４年度からつくり始められるのかということをお伺いしておきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"１点目、これをつくった当初が２６％となっておりますが、大体その辺りの水準というようになっております。今年度後半ぐらいから多分データ収集に入りまして、来年度作成というような形でいこうかというふうに考えております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"まず１つ、要配慮者の避難ということについてちょっと伺いたいのですが、ちょっとそこのところを教えてほしいと求めました。それは私はすごくいいなと思っているのですが、その検討会というものはどのような形でされていくのか、その点についても伺いたいと思います。","respondent":"山本防災課長","answer":"内部の検討の状況ですけれども、そういった避難行動要支援者に対する避難行動をどうしていくかというところ、その辺りを検討しているところで。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１番が避難計画に関することということになっているのですが、避難所に行くまでだけでなく、避難所の生活というものがかなり重要だと思うのです。４番の防災情報に関することですけれども、何というのですか、その点についてはいかがか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"今回ご説明をさせていただきましたが、委員ご指摘のとおり、防災情報には様々なものがあるということは承知しております。今回ちょっと言葉では簡単に概要ということで説明させていただきましたが、私どもも検討を進めていくという必要性は思っておりますので。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１月に委員会報告となっていますけれども、何というのですか、すごく絶好のチャンスになると思うのです。もし、何かご回答がありましたらお願いします。","respondent":"山本防災課長","answer":"区民への説明会というところは、今のところ予定はしておりませんで、幅広く意見のほうを聴取できればというふうに考えているところです。ただ、こちらの計画等の策定をしたときには、様々な形で区民の方にお知らせできるようにしていきたいというふうに考えているところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのたびごとに説明会をやっていただきたいということで要望していますが、説明会をやっていただくように要望させてほしいと求めました。そのような点では、在宅避難の方に対しての食料の備蓄というのは、区としてどのような状況になっているのかについて教えていただけたらと思います。","respondent":"平原防災体制整備担当課長","answer":"大体１週間ぐらいというようなところで言っているところです。政府や都からの支援物資、こういったものを在宅避難者に対しまして支援していくというような形で、物資を供給していくことと考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは在宅で、本当にきちんとした環境が整っていないにもかかわらず、在宅避難せざるを得ないという方もいらっしゃると思いますので、これはその具体的な審議のときに、また意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"何というのですか、何というのですか、変えていくという方向はあるのか尋ねました。","respondent":"河内環境課長","answer":"中間の見直しを令和４年度に予定している中ではありますが、最終的には２０５０年のゼロエミッション、２０３０年の５０％削減までを視野にです。そういったところを視野に踏まえながら、検討をしていきたいというようなところで進めているところです。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、あくまでそこを意識した上で、ＺＥＢ、ＣＯ２削減の取組みというもののご報告もいただくし、我々もそれをあれしていくので、もしかすると、読み込んでいませんけれども、当時の品川区環境基本計画の数値よりも、もっと大幅に減らしていくのだということでよろしいのか尋ねました。","respondent":"河内環境課長","answer":"ＺＥＢというところも踏まえて、そういった目標に向かって検討を進めてまいりたいというふうに考えている中でのＺＥＢの展開です。こういった有用性がうたわれているところでございまして、こういったところも踏まえ、進めてまいりたいというふうに考えているところです。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのことで質問というよりも、そして理事者の皆様にご要望なのですが、防災協定１７８件と出ております。その１点お願いします。","respondent":"安藤委員長","answer":"ありがとうございました。ただいまの委員のご意見を踏まえまして、正副で十分に検討していきたいと思います。","id":"exchange-013"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとこの中にも、要望もさせていただきましたが、みんなの共通認識となる形で資料として出していただけたらありがたいなと思います。同じ前提に、議論の前提になると思いますので、出していただけたらということで要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"すみません。ほかの自治体の事例なども情報収集していただき、そうした資料もご提供いただければなと思いますので、ご検討いただけますか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それはあれですか、１日その部分をやるなどということも、なるべく多岐にわたるような進め方でやってもらえればいいかなと思います。これは要望ですけれども、一応もし何かあれば説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/822771?Template=document&Id=6596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":17014,"voices":68}},{"id":"r03-20210611-10","meetingId":"r03-cm06","date":"2021年6月11日","dateIso":"2021-06-11","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"そして２番目、デフリンピックの日本誘致を実現し、東京２０２０大会が実施された会場で行っていただきたい旨の要望です。ＧＩＧＡスクールに関する要望、そして環境に関する要望、この６点を東京都に出しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"国に対する第２位は、行政のデジタル化、デジタルトランスフォーメーションに関する要望ということです。３番目が、高齢者施設に関する要望というところで、大枠で書かせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"せお委員","kind":"質問・要望","question":"自民・無所属・子ども未来からの要望は、まず、カーボン・ニュートラル社会の構築、こちら国や都に対してです。こちらは都に要望するものですが、教育のインクルージョンの推進についてということで、提出いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"国への要望として、２つ目は、住環境の影響について調査をし公表することを求めさせていただきました。国への要望ということで、２つ目が、同じく国による公費の大幅引上げを要望するものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望内容として、４番目に、以上のような大型施設を自治体に１つずつ確保することを要望いたします。２つ目に、東京都への要望として、給与は都が負担しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"国に対する要望で言うと、時代の変わり目だと思っていますので、ぜひ前向きにご検討ほしいと求めました。国に対する要望に関しては、ＧＩＧＡスクール構想もぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問・要望","question":"国に対して出す要望と被りますが、ぜひ都にも出していきたいと、会派として思っています。まだ大きな改善がなく、全区的な課題だとも思っていますので、ぜひこれも前向きに御検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"これを出しているわけですから、好ましいのではないかと私は考えておりますので、そのような取り計らいを委員長にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"２番目の環境と、次の行政のデジタル化・ＤＸについてというところも、できればこれも複数会派から出ているので、まとめてほしいと求めました。は大沢委員のおっしゃるとおりで、また正副議長のほうで調整しながらやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"各会派の要望もしっかりと読ませていただきました。やはり、マイナンバーにひもづけることには同意できませんので、この点については反対をさせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"なければ１点だけいいですか。中学校も拡大を求めていこうという点においては、ぜひ少人数学級を中学校で実施していただきたいという国への要望、ご調整をいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"課題はあるにせよ、会議体が２つでも、これは委員長なり、座長なりの調整で、十分できるかと思います。理由は、最終的にこの議運で確認もされるという仕組みになっているので、議長提案で言われたとおりで諮っていけばいいのかなという思いがありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"行革は行革でまた報告をするのでしょうから、それで策定委員会は策定委員会でやはりきちんと多くの有識者を集めてやっているのでしょうから。ですから、各会派のご意見を区のほうにぶつける、伝えるということでいかがでしょうかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"議会全体で１つ持っていくということは、要望もあるわけですから、それが区議会としての意見ですというふうなほうがいいのではないですか。最終的には策定委員会で決めるのですから、非常にスムーズに行くのではないかなという気がするのですが、皆さんのお考えを説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問","question":"最初から、いやそれはできないから、そちらで勝手に決めてくれと言っているようなものではないですか。しかるべきところでそれなりにやって、時間的なことを考えていけば、集中的にそれはやるということは必要なのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう１回だけいいですか。私は申し上げているだけで、別に私の意見を通そうとは思っていないので、こういうことを認識していただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと、議会としての統一した意見が求められているのであって、これはもうまるっきりまとまりがつかないものであります。そしてまた、たけうち委員が言ったことにまるっきり同感でありますので、そのような取り計らいで進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"同じく議会棟についても、いずれ建て替えるわけですから、検討することはあっても、そこは十分に時間をかけることが必要だと思います。議会棟の議論ですから、希望する方がいらっしゃれば保証すべきだと思いますので、思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"７月末までにと言われても、７月末までという投げかけである以上、なるべく早く情報を出していただきたいということが１つです。なるべく資料の件はぜひ役所側にプッシュしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう説明の場を国に求めていこうではないかという点で一致をするのであれば、しっかりご説明できる方に来ていただきたいなと思っておりまして。先ほど議長から投げかけられたとおり、できるだけスピーディーにことを進めていただけたらと、改めて要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5416#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":23525,"voices":72}},{"id":"r03-20210622-10","meetingId":"r03-cm06","date":"2021年6月22日","dateIso":"2021-06-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"令和３年第３回定例会の日程","agenda":"令和３年第３回定例会の日程","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"コロナ感染の状況をよく見極めて、各委員会対応がばらばらというよりも、区議会として同じ対応ができるように調整していただきたいと。意見だけ述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"確認と質問と意見を述べさせていただきたいのですけれども、まず確認です。最終的な取りまとめは全会一致ということで確認されておりましたが、今回も同じ取扱いでよいのか、確認させてほしいと求めました。","respondent":"本多議長","answer":"最初のほうですけれども、議会改革推進会議で協議をしていただきたいという発言をさせていただきました。その会議体によるまとめが出来上がりましたら、それを議会運営委員会で確認していただけないかと、そういう趣旨です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"最終的に要望をまとめる段階においては、従来のことを変えるべきではないと思いますので、その辺だけ確認したいです。これは誰に聞いたらいいのか分からないですけれども、全会一致だけ確認させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"最終的には要望事項を協議したいということですけれども、まずは現状の課題を丁寧に抽出していくことが求められていると思います。どうしてもスケジュールがタイトなので、せめて２日前に提供していただきたいと、意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"メンバーの傍聴はそれでいいと思うのですけれども、やはりとても大事な議会棟の議論になりますので、メンバー以外の方から発言をしたいという申出があったときには、委員会に諮って発言を認めるかどうか、そういう丁寧な進め方ができたらと、要望したいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"中塚委員のほうからも要望しましたように、どう聴取するかについて、どのようなお考えがあるのか。これは大事な、基本構想をつくるということであれば必ずやっていかなくてはいけないことだと考えていますので、要望とともに質問をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今、品改の話をしていただいて、ありがとうあります。そちらで検討が進められているのですから、議論することは考えておりませんので、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望事項の５番にマイナンバーカードの普及促進とあります。この要望事項は共通する事項で進めていこうという趣旨でありますので、適切ではないと思いますので、一言意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"当事者の方のご意見を伺うのが一番だと思いますけれども、でも、テレビでやっているのか。委員会と本会議での手話通訳の配置について、ご説明ほしいと求めました。","respondent":"工藤区議会事務局長","answer":"今回、所管からお話しいただいていますのが、７月６日の厚生委員会と、７月１４日の本会議最終日に、手話通訳者をです。そのような形で私ども見込んでおりますので、傍聴者にしっかり伝わるような形で対応してまいりたいと考えております。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5418#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":11181,"voices":54}}]);
